  @override
  String get benzoMilestone7Title => 'Fase de Retirada Antecipada';

  @override
  String get benzoMilestone7Description =>
      'Depois de completar uma redução gradual, podem aparecer sintomas de abstinência precoce, como ansiedade rebote e insônia.Este é o seu sistema nervoso começando a se reajustar.O apoio médico durante esta fase é crucial para a segurança e o conforto.';

  @override
  String get benzoMilestone14Title => 'Pico de Retirada Aguda';

  @override
  String get benzoMilestone14Description =>
      'Os sintomas agudos de abstinência normalmente atingem o pico nas primeiras duas semanas.Você pode sentir ansiedade, distúrbios do sono e desconforto físico.Esses sintomas, embora desafiadores, indicam que seu cérebro está começando a se curar e a se reequilibrar.';

  @override
  String get benzoMilestone60Title => 'A arquitetura do sono melhora';

  @override
  String get benzoMilestone60Description =>
      'Estudos mostram que após 2 meses, os seus padrões naturais de sono começam a ser restaurados.O sono de ondas lentas aumenta e a qualidade do sono melhora em comparação com o uso de benzodiazepínicos, embora a eficiência geral do sono ainda possa estar se recuperando.';

  @override
  String get benzoMilestone90Title => 'Estabilização da saúde física';

  @override
  String get benzoMilestone90Description =>
      'Por volta dos 3 meses, muitos sintomas físicos de abstinência melhoraram significativamente.Seu corpo continua a se ajustar para funcionar sem medicação.A ansiedade e o humor ainda podem flutuar, mas o funcionamento geral melhora.';

  @override
  String get benzoMilestone180Title =>
      'Pensamento e memória começam a se recuperar';

  @override
  String get benzoMilestone180Description =>
      'Aos seis meses, a memória e a atenção apresentam melhorias mensuráveis.A investigação revela recuperação em muitas competências de pensamento, com ganhos que continuam para além dos seis meses.';

  @override
  String get benzoMilestone365Title => 'Um ano de cura';

  @override
  String get benzoMilestone365Description =>
      'Após um ano, tornam-se aparentes melhorias significativas no bem-estar físico e mental.Muitos relatam redução da ansiedade, melhor qualidade do sono e melhora da saúde geral em comparação com o uso de benzodiazepínicos por um longo prazo.A cura do cérebro continua.';

  @override
  String get benzoMilestone540Title => 'Recuperação cerebral contínua';

  @override
  String get benzoMilestone540Description =>
      'Aos 18 meses, a memória, a atenção e o raciocínio claro continuam melhorando.O sistema GABA calmante do cérebro teve mais de um ano para se estabelecer, enquanto o cérebro continua construindo padrões mais saudáveis.';

  @override
  String get benzoMilestone730Title => 'Dois anos: grande progresso';

  @override
  String get benzoMilestone730Description =>
      'Dois anos marcam uma recuperação substancial.A maioria das pessoas tem pensamentos muito mais claros, emoções mais estáveis ​​e uma qualidade de vida muito melhor do que durante o uso prolongado de benzodiazepínicos.';

  @override
  String get benzoMilestone1095Title => 'Três anos: recuperação a longo prazo';

  @override
  String get benzoMilestone1095Description =>
      'Aos três anos, o longo período de retirada está muito atrás da maioria das pessoas.O sono, o humor, a memória e a atenção levaram anos para se recuperar, e a vida cotidiana costuma ser muito melhor do que durante o uso prolongado.';

