  @override
  String get nitrousOxideMilestone3Description =>
      'Aqui estão boas notícias: o óxido nitroso não causa abstinência física.Os impulsos que você sente são psicológicos – hábito e associação, e não seu corpo exigindo uma substância.Isso os torna gerenciáveis.';

  @override
  String get nitrousOxideMilestone7Title => 'Uma semana - B12 subindo';

  @override
  String get nitrousOxideMilestone7Description =>
      'Uma semana sem que nenhuma nova B12 seja destruída.Se você começou a suplementar, seus níveis já estão subindo.Energia, humor e foco estão todos ligados ao B12 – você deve começar a senti-los melhorar.';

  @override
  String get nitrousOxideMilestone14Title => 'Duas Semanas - Cura dos Nervos';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12 é essencial para a camada protetora das fibras nervosas.Duas semanas depois, esse processo de reparo está em andamento.Qualquer formigamento ou dormência que você sentiu deve estar diminuindo – seu sistema nervoso está se recuperando.';

  @override
  String get nitrousOxideMilestone30Title => 'Um Mês - Retorno de Energia';

  @override
  String get nitrousOxideMilestone30Description =>
      'B12 desempenha um papel fundamental na produção de glóbulos vermelhos, o que significa fornecimento de oxigênio a todas as células do seu corpo.Um mês de recuperação e suplementação significa energia significativamente melhor, pensamento mais claro e humor mais estável.';

  @override
  String get nitrousOxideMilestone90Title =>
      'Três Meses - Recuperação Neurológica';

  @override
  String get nitrousOxideMilestone90Description =>
      'Três meses sem destruição de vitamina B12 significam três meses de reparação nervosa.O sistema nervoso é resiliente – a maioria das pessoas que iniciaram o tratamento imediatamente apresentam uma recuperação significativa do formigamento, da fraqueza e da confusão mental neste ponto.';

  @override
  String get nitrousOxideMilestone365Title =>
      'Um ano - Saúde garantida a longo prazo';

  @override
  String get nitrousOxideMilestone365Description =>
      'Um ano inteiro livre de óxido nitroso.Seus estoques de vitamina B12 foram restaurados, seu sistema nervoso teve um ano para se curar e o risco cardiovascular causado pela homocisteína elevada foi resolvido.Seu corpo está operando novamente com sua própria química.';

