  @override
  String get alcoholMilestone1Description =>
      'Seus ciclos de sono REM começam a normalizar no primeiro dia.Embora o álcool possa ajudá-lo a adormecer inicialmente, ele perturba o sono profundo e os ciclos REM durante a noite, causando um sono fragmentado.';

  @override
  String get alcoholMilestone3Title => 'Restauração dos níveis de hidratação';

  @override
  String get alcoholMilestone3Description =>
      'Seus rins estão se recuperando dos efeitos diuréticos do álcool.O álcool suprime o hormônio antidiurético, levando ao aumento da micção e à desidratação.No terceiro dia, o equilíbrio de fluidos do seu corpo está melhorando significativamente.';

  @override
  String get alcoholMilestone7Title => 'Sistema imunológico fortalece';

  @override
  String get alcoholMilestone7Description =>
      'Os seus glóbulos brancos estão a recuperar a sua função.Mesmo um único consumo excessivo de álcool pode prejudicar a função imunológica por até 24 horas, e o consumo crônico enfraquece significativamente a capacidade do corpo de combater infecções.';

  @override
  String get alcoholMilestone14Title =>
      'Começa a recuperação do volume cerebral';

  @override
  String get alcoholMilestone14Description =>
      'O volume cerebral começa a se recuperar nas primeiras duas semanas.O pensamento e a memória continuam melhorando nos meses seguintes.';

  @override
  String get alcoholMilestone30Title => 'A pressão arterial normaliza';

  @override
  String get alcoholMilestone30Description =>
      'Seu sistema cardiovascular apresenta melhora significativa.O consumo regular de álcool eleva a pressão arterial, mas a abstinência por cerca de um mês pode ajudar a trazer a pressão arterial de volta a níveis mais saudáveis.';

  @override
  String get alcoholMilestone60Title => 'Função hepática melhora';

  @override
  String get alcoholMilestone60Description =>
      'Seu fígado apresenta melhora mensurável na função.Este órgão regenerativo pode se recuperar significativamente dos danos induzidos pelo álcool, com as enzimas hepáticas e o acúmulo de gordura apresentando melhora dentro de 2 meses de abstinência.';

  @override
  String get alcoholMilestone90Title =>
      'Pensamento e memória melhoram substancialmente';

  @override
  String get alcoholMilestone90Description =>
      'Os primeiros três meses trazem grandes ganhos de memória, concentração e tomada de decisões, com a recuperação continuando nos meses seguintes.';

  @override
  String get alcoholMilestone180Title =>
      'Volume e Função Cerebral Continuam Recuperação';

  @override
  String get alcoholMilestone180Description =>
      'Seis meses sóbrio dão ao cérebro tempo suficiente para se recuperar.O volume do cérebro e as habilidades de pensamento continuam a melhorar.';

  @override
  String get alcoholMilestone365Title =>
      'A redução do risco de câncer pode começar';

  @override
  String get alcoholMilestone365Description =>
      'Um ano de abstinência pode começar a reduzir o risco de cancro.Embora o álcool aumente claramente o risco de vários cancros (fígado, mama, colorrectal, esófago), a investigação sobre o cronograma de redução do risco ainda está a surgir e varia consoante o tipo de cancro.';

  @override
  String get smokingMilestone1Title => 'Remoção de Monóxido de Carbono';

  @override
  String get smokingMilestone1Description =>
      'Seu sangue está respirando de novo!Dentro de 24 horas, os níveis de monóxido de carbono caem ao normal e os níveis de oxigênio aumentam.Seu coração não precisa mais trabalhar horas extras para bombear sangue envenenado por todo o corpo.';

  @override
  String get smokingMilestone3Title => 'Picos de abstinência de nicotina';

  @override
  String get smokingMilestone3Description =>
      'O monstro da nicotina está mais furioso, mas você está vencendo a batalha!Toda a nicotina saiu do seu sistema.Os piores desejos acontecem agora, mas também são o seu bilhete para a liberdade do outro lado.';

  @override
  String get smokingMilestone7Title => 'Sabor e olfato melhoram drasticamente';

  @override
  String get smokingMilestone7Description =>
      'A comida está prestes a se tornar uma aventura novamente!Fumar destrói as papilas gustativas e os receptores olfativos.Depois de uma semana, você está redescobrindo sabores que esqueceu que existiam.Prepare-se para uma apreciação séria da comida!';

  @override
  String get smokingMilestone14Title => 'Circulação e caminhada melhoram';

  @override
  String get smokingMilestone14Description =>
      'Suas pernas agradecem a cada passo!A circulação sanguínea melhora drasticamente, tornando a caminhada e os exercícios visivelmente mais fáceis.Essas escadas não parecem mais tão intimidantes, não é?';

  @override
  String get smokingMilestone30Title => 'Aumento da função pulmonar';

  @override
  String get smokingMilestone30Description =>
      'Seus pulmões estão dando uma festa de retorno!Os cílios cresceram novamente e estão varrendo anos de alcatrão e detritos.A capacidade pulmonar aumenta significativamente e a tosse do fumante é história.';

  @override
  String get smokingMilestone90Title =>
