  String get ssriHeaderStarted => 'Sua jornada de recuperação';

  @override
  String get ssriHeaderNotStarted => 'Benefícios da redução gradual dos ISRSs';

  @override
  String get ssriSubtitleStarted =>
      'Acompanhe seu progresso e comemore cada marco';

  @override
  String get ssriSubtitleNotStarted =>
      'Veja o que acontece quando você diminui gradualmente';

  @override
  String get ssriMilestone3Title => 'Dia 3: Picos da Síndrome FINISH';

  @override
  String get ssriMilestone3Description =>
      'Os sintomas de abstinência geralmente atingem o pico por volta do 2º ao 4º dia.Os ISRS mudam a forma como a serotonina é reciclada, por isso o cérebro precisa de tempo para se ajustar depois de parar.Espere sintomas semelhantes aos da gripe, tonturas, insônia, náuseas e \'ataques cerebrais\'.A paroxetina tende a causar abstinência mais forte;a fluoxetina dura muito mais tempo no corpo e geralmente é mais suave.';

  @override
  String get ssriMilestone7Title =>
      'Uma semana: fase aguda começando a diminuir';

  @override
  String get ssriMilestone7Description =>
      'Os sintomas físicos mais intensos estão começando a diminuir.Seu cérebro está ajustando a sinalização da serotonina para funcionar sem a medicação.O sono e o apetite estão começando a se estabilizar.';

  @override
  String get ssriMilestone14Title =>
      'Duas semanas: resolução dos sintomas físicos';

  @override
  String get ssriMilestone14Description =>
      'A maioria dos sintomas agudos de descontinuação física foram significativamente reduzidos ou resolvidos.Os ataques cerebrais, as náuseas e as tonturas estão desaparecendo.A sensibilidade emocional ainda pode aumentar à medida que seu cérebro continua a reequilibrar seus sistemas de serotonina.';

  @override
  String get ssriMilestone30Title =>
      'Um mês: estabilização do humor e da energia';

  @override
  String get ssriMilestone30Description =>
      'Um mês é um marco significativo.A qualidade do sono está a melhorar, os níveis de energia estão a estabilizar e muitas pessoas notam que o seu humor começa a encontrar um novo equilíbrio.O cérebro está restaurando ativamente a regulação natural da serotonina.';

  @override
  String get ssriMilestone90Title =>
      'Três Meses: Recuperação do Receptor de Serotonina';

  @override
  String get ssriMilestone90Description =>
      'Três meses é um marco importante de recuperação.O sistema da serotonina teve meses para se ajustar depois que o medicamento acabou.Humor, ansiedade, foco e pensamento claro são significativamente melhores para a maioria das pessoas.';

  @override
  String get ssriMilestone180Title =>
      'Seis Meses: Ajuste Cerebral de Longo Prazo';

  @override
  String get ssriMilestone180Description =>
      'Seis meses permitem um ajuste neurológico substancial.Os sistemas de serotonina do cérebro encontraram seu equilíbrio natural.Muitas pessoas relatam melhora do alcance emocional e, para aquelas que vivenciaram isso, a disfunção sexual causada pelos ISRSs normalmente foi resolvida.';

  @override
  String get ssriMilestone365Title => 'Um ano: recuperação alcançada';

  @override
  String get ssriMilestone365Description =>
      'Um ano marca um ciclo completo de recuperação.A investigação mostra que a maioria dos que completaram uma redução gradual e receberam apoio psicológico permanecem bem ao fim de um ano, com qualidade de vida comparável ou melhor do que aqueles que permaneceram sob medicação.';

  @override
  String get settingsShowSsriTracking => 'Mostrar rastreamento de SSRI';

  @override
  String get settingsNotifySsri =>
      'Notificar SSRI sobre o progresso de encerramento';

