      'Acompanhe seu progresso e comemore cada marco';

  @override
  String get tcaSubtitleNotStarted =>
      'Veja o que acontece quando você diminui gradualmente';

  @override
  String get tcaMilestone3Title =>
      'Dia 3: Picos de recuperação da acetilcolina';

  @override
  String get tcaMilestone3Description =>
      'Os TCAs bloqueiam a acetilcolina.Depois de parar, esse sistema pode ficar hiperativo por um breve período.Os sintomas incluem náusea, diarreia, cólicas estomacais, sudorese intensa, dor de cabeça, dores musculares e insônia.Esses sintomas geralmente atingem o pico precocemente e depois diminuem.';

  @override
  String get tcaMilestone7Title =>
      'Uma semana: alívio dos sintomas de recuperação';

  @override
  String get tcaMilestone7Description =>
      'O rebote da acetilcolina geralmente atinge o pico nos primeiros dias e começa a diminuir em uma semana.Os sintomas estomacais, a sudorese e a sensação de gripe estão diminuindo, enquanto os sistemas do corpo que controlam a frequência cardíaca, a digestão e a sudorese voltam ao normal.';

  @override
  String get tcaMilestone14Title =>
      'Duas semanas: reversão dos efeitos anticolinérgicos';

  @override
  String get tcaMilestone14Description =>
      'A boca seca, a prisão de ventre, a dificuldade para urinar e a visão turva causadas pelos ADTs são revertidas à medida que o sistema de acetilcolina se recupera.A memória e a atenção também costumam parecer mais claras.';

  @override
  String get tcaMilestone30Title =>
      'Um Mês: Estabilização do Sistema Nervoso Autônomo';

  @override
  String get tcaMilestone30Description =>
      'Em um mês, os sistemas do corpo que controlam a frequência cardíaca, a pressão arterial, a digestão e a transpiração estão se estabilizando.As alterações do ritmo cardíaco e da pressão arterial estão se normalizando e o sono REM dos sonhos está retornando.';

  @override
  String get tcaMilestone90Title =>
      'Três Meses: Assentamento de Sistemas Químicos Cerebrais';

  @override
  String get tcaMilestone90Description =>
      'Os TCAs afetam vários sistemas químicos cerebrais.Três meses lhes dão um tempo substancial para se estabelecerem.Humor, pensamento claro e bem-estar físico são notavelmente melhores.';

  @override
  String get tcaMilestone180Title =>
      'Seis Meses: Recuperação do Coração e do Pensamento';

  @override
  String get tcaMilestone180Description =>
      'Seis meses permitem uma grande recuperação do ritmo cardíaco, da memória e da velocidade de pensamento.As alterações no ritmo cardíaco e a confusão mental causadas pelos ADTs levaram meses para serem resolvidas.';

  @override
  String get tcaMilestone365Title => 'Um ano: Recuperação alcançada';

  @override
  String get tcaMilestone365Description =>
      'Um ano dá a cada sistema afetado por TCAs um ano inteiro para se recuperar.Os sistemas de acetilcolina, noradrenalina, serotonina e histamina se estabilizaram e a memória, o pensamento claro e o controle da frequência cardíaca foram substancialmente recuperados.';

