  @override
  String get adderallReferenceDay1 =>
      'Abstinência de anfetaminas: o que acontece desde o início\n\nFonte: MedlinePlus (Biblioteca Nacional de Medicina dos EUA)\n\nO que são anfetaminas?\nAs anfetaminas são drogas estimulantes que incluem substâncias ilícitas (como velocidade de rua) e medicamentos prescritos usados ​​para tratar TDAH e narcolepsia (como Adderall e Vyvanse).Eles aumentam drasticamente a dopamina e a noradrenalina, o que pode criar foco intenso, energia e euforia.Com o uso intenso e regular, o cérebro se adapta a esses surtos repetidos, portanto, parar pode deixar o humor, a energia e a motivação temporariamente baixos.\n\nSintomas comuns de abstinência\nMedlinePlus lista estes como típicos ao interromper as anfetaminas:\n• Forte desejo pela droga\n• Mudanças de humor que variam de depressão a agitação e ansiedade\n• Sentir-se cansado o dia todo\n• Não consegue se concentrar\n• Alucinações (ver ou ouvir coisas que não existem)\n• Reações físicas, como dores de cabeça, dores e incômodos, aumento do apetite e falta de sono\n\nA retirada é perigosa?\nMedlinePlus não descreve a abstinência de anfetaminas como medicamente perigosa em si, mas observa que sintomas graves podem exigir um programa de tratamento ao vivo, e que problemas emocionais e de humor decorrentes do uso de anfetaminas – incluindo depressão – podem ser graves e exigir apoio.\n\nObtendo ajuda\nMedlinePlus aconselha entrar em contato com seu médico se você ou alguém que você conhece é viciado em anfetaminas e precisa de ajuda para parar de usar.Se você tiver pensamentos de automutilação, isso direciona os leitores para recursos de crise, como 988 ou 911.';

  @override
  String get adderallReferenceDay3 =>
      'Gerenciamento da abstinência de anfetaminas: Dia 3\n\nFonte: \"Diretrizes Clínicas para Gerenciamento de Abstinência e Tratamento da Dependência de Drogas em Ambientes Fechados\", Organização Mundial da Saúde (2009), na estante do NCBI\n\nOnde fica o dia 3\nAs diretrizes da OMS afirmam que os sintomas de abstinência de estimulantes \'começam 24 horas após o último uso de estimulantes e duram de 3 a 5 dias\'.O terceiro dia está dentro desta fase aguda – normalmente um dos dias mais difíceis antes que os sintomas comecem a desaparecer.\n\nOs sintomas\nPara estimulantes do tipo anfetamina, a lista de diretrizes:\n• Agitação e irritabilidade\n• Depressão\n• Aumento do sono e do apetite\n• Dores musculares\nUsuários pesados também podem desenvolver sintomas psicóticos, como paranóia, pensamentos desordenados ou alucinações.\n\nPrincipalmente um desafio psicológico\nAo contrário da abstinência de álcool ou opioides, a abstinência de estimulantes não provoca vômitos, tremores ou convulsões.A dificuldade dominante é psicológica – mau humor, perda de prazer e desejo impulsionado por um cérebro sem dopamina.\n\nAbordagem de Gestão\nAs diretrizes da OMS recomendam cuidados de suporte:\n• Beber pelo menos 2–3 litros de água por dia\n• Suplementos multivitamínicos com vitaminas do grupo B e vitamina C\n• Medicação sintomática para dores e ansiedade\n• Para agitação grave, estratégias comportamentais primeiro, com sedação com diazepam somente se necessário\n\nAlém da Fase Aguda\nAs diretrizes dizem que a abstinência mais difícil dura apenas alguns dias, seguida por um período de recuperação mais brando que pode durar de um a dois meses.';

  @override
  String get adderallReferenceDay7 =>
      'Uma semana sem Adderall: o pior está passando\n\nFonte: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), no PubMed Central\n\nA fase aguda resolve\nEsta revisão de evidências descreve a retirada de psicoestimulantes em fases.Na fase aguda, os sintomas “aumentam após os primeiros 2–3 dias” e “o grande desconforto causado por esses sintomas geralmente desaparece em 4–7 dias”.No final da primeira semana, a parte mais difícil da crise já passou para a maioria das pessoas – a energia e o apetite começam a se estabilizar e o sono começa a se regular.\n\nO que vem a seguir\nA revisão diz que a maioria dos sintomas restantes continua diminuindo nas próximas duas a três semanas.No sétimo dia, a recuperação já está bem encaminhada.\n\nO que ainda está presente no dia 7\nOs sintomas psicológicos normalmente duram mais que o impacto físico:\n• Baixa motivação e perda de prazer\n• Dificuldade de concentração\n• Humor ainda abaixo do normal\nEstes refletem um sistema de dopamina que está se reajustando – uma parte normal e temporária da recuperação.\n\nSinal de recuperação\nNenhum medicamento aprovado pela FDA trata especificamente a abstinência de estimulantes, portanto, cuidados de suporte, estrutura, sono, nutrição e apoio psicológico são os pilares nesta fase.';

  @override
  String get adderallReferenceDay14 =>
      'Duas semanas de folga em Adderall: na fase de recuperação mais longa\n\nFonte: \"Diretrizes Clínicas para Gerenciamento de Abstinência e Tratamento da Dependência de Drogas em Ambientes Fechados\", Organização Mundial da Saúde (2009), na estante do NCBI\n\nPassada a Fase Aguda\nA OMS estima que a retirada mais difícil do estimulante ocorra em cerca de três a cinco dias, seguida por um período de recuperação mais brando que dura cerca de um a dois meses.Em duas semanas, o acidente já ficou para trás.\n\nComo é a fase de recuperação mais longa\nO sono pesado, a agitação e as dores musculares desapareceram em grande parte.O que resta é geralmente mais brando: humor deprimido ou variável, motivação reduzida e desejos intermitentes à medida que o sistema de recompensa do cérebro se reajusta.\n\nSono e apetite\nO aumento do sono e do apetite da fase aguda está se normalizando.À medida que o sono se estabiliza, o humor, a concentração e a energia tendem a acompanhar.\n\nRisco de recaída e TDAH\nEste ainda é um período de maior risco, especialmente se os sintomas subjacentes de TDAH retornarem sem medicação.As directrizes da OMS enfatizam o apoio psicológico e as competências de prevenção de recaídas;para pessoas que tomaram Adderall para TDAH, este é um bom momento para discutir estratégias ou alternativas não estimulantes com um médico.';

  @override
  String get adderallReferenceDay30 =>
      'Um mês de folga em Adderall: a maioria dos sintomas atrás de você\n\nFonte: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), no PubMed Central\n\nOnde fica um mês\nA revisão conclui que a maioria dos sintomas de abstinência desaparecem nas primeiras duas a três semanas.Aos 30 dias, a maior parte deles já melhorou e o humor e a motivação geralmente estão muito melhores do que na primeira semana.\n\nA fase de recuperação posterior\nDe um a seis meses, a memória, o planejamento, o foco e a tomada de decisões continuam a melhorar.Em um mês, a crise acabou e esses ganhos já estão em andamento.\n\nHumor e motivação\nA profunda perda de prazer causada pelo acidente já foi praticamente dissipada.As atividades que pareciam tristes na primeira semana começam a ser gratificantes novamente à medida que a sinalização natural da dopamina se recupera.\n\nPara pessoas com TDAH\nSe Adderall foi prescrito para TDAH, os sintomas subjacentes podem ser mais perceptíveis agora.Trabalhar com um profissional de saúde sobre estratégias ou alternativas não estimulantes é importante durante esta fase.';

  @override
  String get adderallReferenceDay60 =>
      'Dois meses de folga em Adderall: a fase de recuperação mais longa termina\n\nFonte: \"Diretrizes Clínicas para Gerenciamento de Abstinência e Tratamento da Dependência de Drogas em Ambientes Fechados\", Organização Mundial da Saúde (2009), na estante do NCBI\n\nOnde ficam dois meses\nA OMS descreve um período de recuperação mais brando, durando cerca de um a dois meses após a queda inicial.Aos 60 dias, você está no final dessa janela e os sintomas persistentes estão desaparecendo em grande parte.\n\nO que melhora\nA agitação, o humor deprimido e os distúrbios do sono e do apetite da lista de diretrizes para a abstinência de estimulantes foram, para a maioria das pessoas, resolvidos substancialmente:\n• O humor habitual é mais estável, com menos oscilações da recuperação inicial\n• O sono e o apetite normalizaram\n• O sistema de recompensa responde mais prontamente aos prazeres do dia a dia – comida, exercício, conexão\n\nSinal de recuperação\nDoses mais altas e uso mais prolongado podem fazer com que a recuperação demore mais, enquanto permanecer abstinente mantém o humor, a motivação e o pensamento claro voltando ao normal nos meses seguintes.\n\nSaúde Física\nOs efeitos estimulantes sobre a frequência cardíaca, o apetite e o peso diminuem à medida que a droga desaparece da vida diária e a tensão cardiovascular causada pelo uso de estimulantes é aliviada.';

  @override
  String get adderallReferenceDay90 =>
      'Três meses de folga em Adderall: através do pior, ainda curando\n\nFonte: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), no PubMed Central\n\nOnde ficam 90 dias\nAos três meses, os primeiros sintomas já desapareceram, enquanto a memória, o planejamento, o foco, a tomada de decisões e o sistema de recompensa continuam a melhorar.\n\nO pensamento e a memória continuam se recuperando\nA revisão conclui que a memória, o planejamento, o foco e as decisões sobre riscos podem continuar melhorando durante meses.Aos 90 dias, a concentração e a memória ainda estão se movendo na direção certa com a abstinência contínua.\n\nPor que esta janela ainda é importante\nNenhum medicamento aprovado pela FDA visa especificamente a abstinência de estimulantes; portanto, estrutura, terapia, exercícios, sono e suporte são as ferramentas que conduzem a recuperação nesta fase.Construir esses hábitos agora é o que leva a recuperação adiante.\n\nO panorama geral\nTrês meses é uma verdadeira conquista – os períodos físicos e emocionais mais difíceis ficaram para trás, e a trajetória a partir daqui, com abstinência contínua, é de melhoria constante.';

  @override
  String get adderallReferenceDay180 =>
      'Seis meses de folga em Adderall: a parte difícil já passou\n\nFonte: \"Síndromes de Abstinência\", StatPearls (NCBI Bookshelf), Biblioteca Nacional de Medicina dos EUA\n\nO que StatPearls diz sobre estimulantes\nEsta referência clínica descreve a recuperação do estimulante como uma queda seguida de uma melhora gradual.Problemas comuns incluem depressão, dormir muito, aumento da fome, mau humor e movimentos e pensamentos mais lentos.A depressão pode durar várias semanas, com uma recuperação mais branda continuando além disso.\n\nOnde ficam seis meses\nAos seis meses, você já passou do período agudo e da fase depressiva de várias semanas que StatPearls descreve.A recuperação lenta a que se refere teve um tempo substancial para progredir e, para a maioria das pessoas, o humor, o sono, o apetite e a motivação habituais estão agora estáveis ​​e confiáveis.\n\nSinal de recuperação\nStatPearls descreve uma recuperação gradual além das semanas iniciais.Aos seis meses, o colapso agudo e a fase depressiva de várias semanas já ficaram para trás, com humor, sono, apetite e motivação estáveis ​​agora como padrão dominante.\n\nRelação com TDAH\nPara pessoas que tomaram Adderall para TDAH, seis meses de abstinência é um bom ponto para uma revisão lúcida com um médico dos sintomas atuais e se abordagens não estimulantes – exercício, sono, estrutura, terapia ou medicação alternativa – estão atendendo às suas necessidades.';

  @override
  String get adderallReferenceDay365 =>
      'Um ano de folga em Adderall: recuperação substancial, enquadrada honestamente\n\nFonte: Berman et al., \"Potenciais efeitos adversos do tratamento com anfetaminas no cérebro e no comportamento: uma revisão\", Molecular Psychiatry (2008), no PubMed Central\n\nSobre esta revisão\nEsta revisão rastreia o que a exposição a altas doses ou a longo prazo de anfetaminas pode fazer ao cérebro e documenta a recuperação mensurável durante a abstinência.\n\nO que diz sobre recuperação\nA revisão documenta a recuperação do fluxo sanguíneo cerebral e das proteínas que reciclam a dopamina após abstinência prolongada.Algumas áreas do cérebro se recuperam mais rapidamente do que outras, mas a direção geral é clara: o cérebro se recupera após a interrupção do uso.\n\nRecuperação a longo prazo\nA revisão documenta uma recuperação mensurável no fluxo sanguíneo cerebral e na reciclagem de dopamina após abstinência prolongada.Com um ano, esses sistemas cerebrais tiveram um ano inteiro para serem reconstruídos.\n\nO que isso significa em um ano\nPara a maioria das pessoas – especialmente aquelas que tomaram Adderall nas doses prescritas – um ano de folga significa que os sistemas de recompensa, atenção e motivação estão funcionando bem no dia a dia.O uso mais intenso ou prolongado pode levar mais tempo, mas a recuperação continua.O risco de recaída é muito menor do que na recuperação inicial.';

  @override
  String get alcoholReferenceDay1 =>
      'O que acontece com seu sono quando você para de beber?\n\nFonte: \"Alcohol and the Sleeping Brain\" (Colrain, Nicholas & Baker), Handbook of Clinical Neurology - revisado por pares, hospedado pelo NIH\n\nArquitetura do Álcool e do Sono\nO álcool é sedativo, por isso encurta o tempo que leva para adormecer e aumenta o sono profundo de ondas lentas na primeira metade da noite.Mas tem um custo: o álcool suprime o sono REM (movimento rápido dos olhos) – a fase restauradora ligada à consolidação da memória e à regulação emocional – e fragmenta o sono na segunda metade da noite à medida que é metabolizado.\n\nA primeira noite sem álcool\nComo o álcool suprime o sono onírico REM, as primeiras noites sem ele costumam trazer uma recuperação REM: sonhos vívidos e sono mais leve e interrompido, enquanto os padrões normais de sono retornam.Esta é uma parte normal e temporária da recuperação.\n\nA recuperação começa\nÀ medida que o cérebro se reajusta nos dias e semanas seguintes, o REM e a qualidade geral do sono melhoram.Os distúrbios do sono são um dos sintomas mais persistentes relacionados à abstinência, mas tendem ao normal com a abstinência sustentada.\n\nUma nota sobre consumo excessivo de álcool\nPara bebedores diários pesados ou de longo prazo, as primeiras 24 horas também podem trazer sintomas de abstinência (ansiedade, sudorese, tremor, náusea).A abstinência grave pode ser perigosa – se você bebe muito todos os dias, converse com um médico antes de parar abruptamente.';

  @override
  String get alcoholReferenceDay3 =>
      'A Fase Aguda e Recuperação Precoce\n\nFonte: \"Abstinência de Álcool\", StatPearls - revisado por pares, NIH National Library of Medicine\n\nAs primeiras 24 a 72 horas\nStatPearls documenta que os sintomas de abstinência aparecem horas após a última bebida – tremor, insônia, agitação, sudorese, aumento da frequência cardíaca e pressão arterial – e que os sintomas geralmente atingem o pico em torno de 72 horas.A maioria das pessoas superou o pior da fase aguda no final do terceiro dia.A abstinência grave (convulsões ou delirium tremens, que o StatPearls observa pode ocorrer a qualquer momento até 3 a 5 dias após a interrupção ou redução) é uma emergência médica: quem bebe muito diariamente não deve parar abruptamente sem orientação médica.\n\nOs desejos vêm em ondas\nOs desejos muitas vezes se intensificam nos primeiros dias, mas um desejo individual dura pouco – geralmente passando em minutos.Reconhecer que cada onda desaparece por si só torna mais fácil superá-las.\n\nA hidratação recupera\nO álcool suprime o hormônio antidiurético (ADH), fazendo com que os rins excretem mais água e deixando os bebedores regulares cronicamente desidratados.Assim que parar de beber, este efeito diurético termina e o equilíbrio de fluidos começa a recuperar durante os primeiros dias – muitas vezes notado como pele mais clara e energia mais estável.\n\nMente e sono começam a se acalmar\nÀ medida que a fase aguda passa, a química cerebral que o álcool interrompeu (GABA e glutamato) começa a se reequilibrar.A clareza mental melhora e o sono – muito fragmentado durante a abstinência precoce – começa a tender para uma melhor qualidade durante a primeira semana.';

  @override
  String get alcoholReferenceDay7 =>
      'Como o sistema imunológico se recupera\n\nFonte: \"Alcohol and the Immune System\" (Sarkar, Jung & Wang), Alcohol Research: Current Reviews - revisado por pares, hospedado pelo NIH\n\nComo o álcool enfraquece a imunidade\nO álcool enfraquece o sistema imunológico de várias maneiras.Mesmo uma sessão de consumo excessivo de álcool pode reduzir a capacidade de combate a infecções por até 24 horas.O uso prolongado reduz os glóbulos brancos, perturba os sinais imunológicos e danifica as defesas intestinais e pulmonares, aumentando o risco de infecções e retardando a cicatrização de feridas.\n\nRemovendo o insulto\nMuitos desses efeitos melhoram quando o álcool acaba.Os glóbulos brancos e a sinalização imunológica começam a se recuperar, enquanto as defesas intestinais e das vias aéreas começam a se reparar.Na primeira semana, o seu sistema imunológico não é mais prejudicado diariamente e a resistência a infecções comuns começa a melhorar.\n\nUm processo gradual\nA recuperação imunológica completa leva mais de uma semana, e o grau de reparação depende de quão pesado e prolongado foi o consumo – mas a primeira semana sem álcool é onde a reconstrução começa.';

  @override
  String get alcoholReferenceDay14 =>
      'Recuperação cerebral precoce em abstinência\n\nFonte: Bartsch AJ et al., \"Manifestações de recuperação cerebral precoce associada à abstinência do alcoolismo\", Brain (2007) - revisado por pares\n\nMedindo a Recuperação\nEste estudo utilizou ressonância magnética para acompanhar pessoas recentemente desintoxicadas com dependência de álcool durante as primeiras semanas de abstinência, comparando-as com controles saudáveis.Ele capturou a reconstrução física do cérebro assim que a bebida parou.\n\nRecuperações de volume cerebral\nO uso crônico de álcool encolhe o cérebro – em parte devido à redução reversível do tamanho das células, e não apenas à perda permanente de células.Com a abstinência, os investigadores mediram um ganho médio global de volume cerebral de quase 2%, concentrado em torno do cerebelo, mesencéfalo, ventrículos e regiões frontais.Grande parte desse crescimento acontece cedo, nas primeiras semanas sem álcool.\n\nCerebelo e Atenção\nA recuperação foi especialmente clara nas áreas do cérebro usadas para movimento e atenção.Um marcador da saúde das células cerebrais aumentou juntamente com melhorias mensuráveis ​​na atenção, de modo que a cura física trouxe ganhos reais no pensamento.\n\nUma base, não o fim\nFunções superiores, como o raciocínio complexo, recuperam-se mais gradualmente, mas as primeiras duas semanas estabelecem que o cérebro começa a curar-se rapidamente assim que o álcool é removido.';

  @override
  String get alcoholReferenceDay30 =>
      'A pressão arterial cai quando você corta o álcool\n\nFonte: Roerecke et al., \"O efeito da redução do consumo de álcool na pressão arterial: uma revisão sistemática e meta-análise\", Lancet Public Health (2017) — revisado por pares\n\nA evidência\nEsta meta-análise reuniu 36 ensaios randomizados (cerca de 2.865 participantes) que testaram o que acontece com a pressão arterial quando as pessoas bebem menos.Descobriu-se um efeito claro e dependente da dose: quanto mais alguém reduzia, mais a pressão arterial caía.\n\nQual é o tamanho do efeito?\nPessoas que bebiam dois ou menos drinques por dia não observaram nenhuma mudança significativa na pressão arterial com a redução.Acima desse limite, o efeito foi dependente da dose: foi mais forte em pessoas que bebiam seis ou mais bebidas por dia e que reduziram a ingestão para cerca de metade, onde a pressão arterial sistólica caiu cerca de 5,5 mmHg e a diastólica cerca de 4,0 mmHg, em média.Uma redução desse tamanho é clinicamente significativa – comparável a alguns medicamentos para pressão arterial e suficiente para reduzir o risco de acidente vascular cerebral e doenças cardíacas a longo prazo.\n\nPor que um mês é importante\nO álcool aumenta a pressão arterial ao ativar a resposta ao estresse, aumentando o cortisol e enrijecendo os vasos sanguíneos.Os ensaios nesta revisão mostram que o benefício surge ao longo de semanas de redução sustentada – portanto, após cerca de um mês de abstinência, a pressão arterial de quem bebe mais teve tempo de se estabilizar em direção a um nível mais saudável.\n\nUm efeito de limite\nA revisão encontrou um limite claro: o benefício concentrou-se nas pessoas que bebiam mais de dois drinques por dia e aumentou progressivamente à medida que o consumo anterior aumentava.Se você bebe menos, não espere esse benefício específico para a pressão arterial - mas quem bebe mais obtém uma recompensa cardiovascular real e mensurável ao parar.';

  @override
  String get alcoholReferenceDay60 =>
      'Recuperação do fígado após parar de beber\n\nFonte: Instituto Nacional sobre Abuso de Álcool e Alcoolismo (NIAAA), \"Efeitos do Álcool no Corpo\"\n\nComo o álcool prejudica o fígado\nO fígado processa a maior parte do álcool que você bebe e sofre a maior parte dos danos.O NIAAA descreve uma progressão da lesão hepática relacionada ao álcool: começa com fígado gorduroso (esteatose – acúmulo de gordura nas células do fígado), pode avançar para hepatite alcoólica (inflamação) e com uso intenso prolongado para fibrose e cirrose (cicatrizes).\n\nOs estágios anteriores são reversíveis\nO ponto crucial é que o fígado é altamente regenerativo e os estágios iniciais desses danos podem melhorar quando o consumo de álcool é interrompido.O fígado gorduroso, em particular, geralmente se resolve com a abstinência sustentada.Após cerca de dois meses sem álcool, o fígado teve tempo real para eliminar os depósitos de gordura, acalmar a inflamação e restaurar uma função mais saudável – normalmente refletida na queda dos níveis das enzimas hepáticas (ALT e AST).\n\nAlém do fígado\nO NIAAA observa que o álcool também prejudica o coração, o pâncreas e o sistema imunológico.Dar ao corpo uma pausa prolongada do álcool permite que estes sistemas também se recuperem – contribuindo para uma energia mais estável e uma melhor saúde geral que muitas pessoas notam nesta fase.';

  @override
  String get alcoholReferenceDay90 =>
      'Pensamento e memória após três meses sóbrio\n\nFonte: Revisão sistemática da recuperação neuropsicológica após abstinência de álcool (PubMed Central, 2024) — revisado por pares\n\nO que as evidências mostram\nEsta revisão combinou estudos que acompanharam como o pensamento e a memória se recuperam depois que as pessoas param de beber.A maioria das habilidades volta ao normal em cerca de seis a doze meses, e algumas melhoram mais cedo.\n\nO que melhora primeiro\nDuas habilidades específicas se destacam por se recuperarem mais cedo do que as demais: velocidade de processamento básico (a análise descobriu que isso normalmente se recupera em cerca de um mês, embora a precisão em tarefas mais complexas fique para trás) e atualização da memória de trabalho.Por volta da marca dos três meses, muitas pessoas já notam essa elevação.\n\nO que demora mais\nAtenção, planejamento, tomada de decisões, controle de impulsos, percepção e memória continuam melhorando ao longo da janela de recuperação de seis a doze meses.\n\nO que influencia a recuperação\nA revisão observa que a recuperação é moldada por fatores como idade, tabagismo e capacidade pré-mórbida – mas, de forma encorajadora, não é consistentemente pela quantidade total ingerida anteriormente.A recuperação é a trajetória esperada.\n\nPor que é importante\nUm pensamento mais claro é uma recuperação prática: melhor atenção e tomada de decisões ajudam as pessoas a permanecer no tratamento e a evitar recaídas.';

  @override
  String get alcoholReferenceDay180 =>
      'Recuperação cerebral aos seis meses de sobriedade\n\nFonte: Revisão revisada por pares da recuperação estrutural e funcional do cérebro durante a abstinência do uso de substâncias (PubMed Central)\n\nA recuperação continua\nA recuperação precoce do volume cerebral nas primeiras semanas é apenas o começo.Esta revisão documenta que, com a abstinência sustentada, o cérebro continua a se recuperar estrutural e funcionalmente – a massa cinzenta se recupera e as vias da substância branca danificadas que coordenam a comunicação entre as regiões cerebrais são reparadas ao longo de meses.\n\nA frente do cérebro\nA recuperação é especialmente importante na parte frontal do cérebro, que lida com o julgamento, o planejamento e o autocontrole.À medida que cura, a tomada de decisões e o controle dos impulsos se fortalecem.\n\nReligação e função cerebral\nJuntamente com o reparo físico, a função cerebral e as conexões também se recuperam.O cérebro pode se reconectar e reaprender, o que torna a abstinência sustentada um momento poderoso para terapia e novos hábitos.\n\nSinal de recuperação\nAos seis meses, a estrutura e a função do cérebro estão claramente caminhando para um normal mais saudável.Permanecer abstinente dá mais tempo para a recuperação se desenvolver.';

  @override
  String get alcoholReferenceDay365 =>
      'Álcool, risco de câncer e abstinência\n\nFonte: Instituto Nacional do Câncer (NCI), \"Álcool e Risco de Câncer\"\n\nÁlcool causa câncer\nO NCI afirma que existe um forte consenso científico de que o consumo de álcool pode causar câncer.O álcool está ligado a cânceres de boca (cavidade oral), faringe (garganta), laringe (caixa vocal), esôfago, fígado, mama, cólon e reto.Quanto mais uma pessoa bebe – e quanto mais tempo bebe – maior é o risco.\n\nComo o álcool causa câncer\nOs mecanismos incluem o acetaldeído, um produto tóxico da decomposição do álcool que danifica o DNA;estresse oxidativo e inflamação;absorção prejudicada de nutrientes protetores;e, para o câncer de mama, aumentou os níveis de estrogênio.\n\nO risco cai depois que você para\nÉ importante ressaltar que o NCI relata que parar de beber está associado a um menor risco ao longo do tempo – estudos mostram que o risco elevado de cancro da cavidade oral e do esófago diminui após parar, embora possa levar anos para se aproximar do risco de alguém que nunca bebeu.Um ano sem álcool é um passo significativo nesse caminho.\n\nBenefícios compostos\nChegar a um ano também garante os ganhos cardiovasculares e hepáticos da abstinência – pressão arterial mais baixa, risco reduzido de arritmia e cura contínua do fígado – juntamente com a queda do risco de câncer.';

  @override
  String get benzodiazepineReferenceDay7 =>
      'Abstinência de benzodiazepínicos: a primeira semana\n\nFonte: \"Diretrizes Clínicas para Gerenciamento de Abstinência e Tratamento da Dependência de Drogas em Ambientes Fechados\", Organização Mundial da Saúde (2009), na estante do NCBI\n\nNota sobre segurança de retirada de Benzo\nA abstinência de benzodiazepínicos pode ser perigosa.As directrizes da OMS são explícitas que a abordagem mais segura é administrar benzodiazepinas em quantidades gradualmente decrescentes, o que “ajuda a aliviar os sintomas de abstinência das benzodiazepinas e a prevenir o desenvolvimento de convulsões”.Não pare abruptamente após uso prolongado – trabalhe com um médico para diminuir gradualmente.\n\nQuando a retirada aparece\nO cronograma da OMS depende da duração da ação do medicamento:\n• Ação curta (oxazepam, alprazolam, temazepam): a retirada começa 1–2 dias após a última dose e continua por 2–4 semanas ou mais\n• Ação prolongada (diazepam, nitrazepam): a retirada começa 2–7 dias após a última dose e continua por 2–8 semanas ou mais\nO marco da primeira semana é o ponto em que mesmo os benzodiazepínicos de ação mais prolongada foram eliminados o suficiente para que a abstinência tenha efeito total.\n\nSintomas de abstinência precoce\n• Ansiedade de rebote — muitas vezes mais intensa do que a ansiedade original tratada pela droga\n• Insônia e distúrbios do sono\n• Tremores e tensão muscular\n• Sudorese e palpitações\n• Maior sensibilidade à luz e ao som\n\nMonitoramento\nAs directrizes da OMS observam que a gravidade da abstinência “pode flutuar acentuadamente”, pelo que as escalas formais não são recomendadas;em vez disso, um médico deve fazer check-in a cada poucas horas, tranquilizar e explicar os sintomas.Os benzodiazepínicos aumentam o GABA, o principal sinal calmante do cérebro;o uso a longo prazo embota esse sistema, de modo que a remoção da droga deixa o cérebro superexcitado – a fonte da ansiedade, do tremor e do risco de convulsão que tornam essencial uma redução gradual.';

  @override
  String get benzodiazepineReferenceDay14 =>
      'Retirada de benzodiazepínicos: duas semanas\n\nFonte: Ashton, \"Síndromes de abstinência prolongada de benzodiazepínicos\", Journal of Substance Abuse Treatment (1991), no PubMed\n\nAinda em abstinência aguda\nApós duas semanas, muitas pessoas – especialmente aquelas que estão abandonando os benzodiazepínicos de ação mais prolongada – ainda estão na fase aguda, quando o desequilíbrio entre os sistemas calmante (GABA) e excitatório do cérebro é mais pronunciado.Ansiedade, insônia e distúrbios perceptivos são comuns.\n\nPor que a retirada do Benzo pode se arrastar\nA professora Heather Ashton descreve como os primeiros sintomas de abstinência podem se misturar a problemas duradouros.Ansiedade, insônia, dificuldade para pensar com clareza e alterações sensoriais podem continuar por meses porque as alterações de tolerância do cérebro podem demorar para serem revertidas.\n\nMudanças lentamente reversíveis\nAshton as caracteriza como “mudanças funcionais lentamente reversíveis no sistema nervoso central”.A reivindicação central é a recuperação: o sistema nervoso reverte progressivamente as adaptações funcionais criadas pela exposição prolongada aos benzodiazepínicos.\n\nA redução gradual é a chave\nA evidência apoia fortemente uma redução lenta e supervisionada como a forma mais segura de parar, permitindo que o cérebro se readapte gradualmente, em vez de enfrentar uma perda súbita de sinalização inibitória.';

  @override
  String get benzodiazepineReferenceDay60 =>
      'Benzodiazepínicos e recuperação do sono em dois meses\n\nFonte: Poyares et al., \"Uso crônico de benzodiazepínicos e retirada em pacientes com insônia\", Journal of Psychiatric Research (2004), no PubMed\n\nComo Benzos muda o sono\nOs benzodiazepínicos são amplamente prescritos para a insônia, mas alteram a arquitetura do sono.Neste estudo de polissonografia de pacientes que tomaram benzodiazepínicos todas as noites por uma média de quase sete anos, o uso crônico foi associado à redução do sono de ondas lentas (profundo) e a mais sono leve de estágio 2 – de modo que os usuários perdem o sono profundo restaurador mesmo quando se sentem sedados.\n\nO sono profundo volta\nA descoberta encorajadora: o estudo mediu o sono novamente 15 dias após a retirada e encontrou recuperação do sono de ondas lentas e da atividade delta em comparação com as noites de uso crônico, juntamente com melhora na qualidade subjetiva do sono.O sono profundo, suprimido pela droga, começou a retornar cerca de duas semanas após a interrupção.\n\nO que isso significa em 60 dias\nSe o sono profundo estiver se recuperando em duas semanas, então em dois meses seu cérebro terá tempo suficiente para continuar a reconstruir o sono natural e restaurador.A grave insônia de rebote da abstinência precoce normalmente se resolveu.Os autores foram honestos ao afirmar que a abstinência piorou o sono no início – razão pela qual uma redução gradual é importante – mas, no final do protocolo, a qualidade do sono melhorou em relação ao uso crônico de benzodiazepínicos.\n\nOutras melhorias em dois meses\nMuitos sintomas iniciais de abstinência física – tensão muscular, tremor, palpitações, sudorese – geralmente diminuíram ou desapareceram na marca de dois meses, à medida que o corpo se re-regula.';

  @override
  String get benzodiazepineReferenceDay90 =>
      'Três meses após os benzodiazepínicos: a saúde física se estabiliza\n\nFonte: Ashton, \"Síndromes de abstinência prolongada de benzodiazepínicos\", Journal of Substance Abuse Treatment (1991), no PubMed\n\nEstabilização Física\nAos 90 dias, a fase aguda já passou.Para as pessoas que completaram uma redução gradual controlada, a maioria dos sintomas físicos de abstinência – tremores, palpitações, dores de cabeça e as piores perturbações do sono – diminuíram substancialmente e o sono é geralmente mais estável.\n\nPor que alguns sintomas persistem\nAshton documenta que alguns sintomas podem durar meses.Aos três meses, ansiedade persistente, confusão mental e alterações sensoriais ainda podem aparecer enquanto o cérebro continua seu reajuste lento e reversível.\n\nDuas razões pelas quais a ansiedade persiste\n1. O sistema GABA do cérebro ainda está se readaptando à sensibilidade normal – um processo lento\n2. Qualquer ansiedade subjacente que levou ao uso de benzo agora é sentida sem um tampão impulsionado pelas drogas\n\nUm bom momento para terapia\nCom os piores sintomas iniciais atrás de você, três meses é um ponto forte para usar suporte, como terapia de fala, como TCC (TCC), para ansiedade e desenvolver habilidades de enfrentamento enquanto o sistema nervoso continua se acalmando.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'Pensamento e memória aos seis meses: ganhos mensuráveis\n\nFonte: Tata et al., \"Falta de recuperação cognitiva após retirada do uso de benzodiazepínicos a longo prazo\", Psychological Medicine (1994), no PubMed\n\nO que o estudo fez\nEste estudo testou 21 pacientes com benzodiazepínicos de longo prazo antes da retirada, logo após a retirada e novamente aos seis meses de abstinência, comparando-os com controles correspondentes.É um dos dados mais sinceros na literatura sobre recuperação de benzo.\n\nO que encontrou\nAntes de parar, os pacientes apresentavam problemas de aprendizagem verbal, memória, velocidade de movimento, coordenação visual e raciocínio visual.Logo depois de parar, houve poucas mudanças.Ao fim de seis meses, várias dessas áreas tinham melhorado de forma mensurável.\n\nO que isso significa\nAos seis meses, o aprendizado verbal, a memória, a velocidade de movimento e a coordenação visual estavam se recuperando de forma mensurável.A melhoria já era clara e tinha espaço para continuar.\n\nO panorama geral\nSe você se sentir confuso aos seis meses, esta pesquisa diz: isso é esperado, e a abstinência contínua é o caminho a seguir.Estudos de longo prazo mostram que a recuperação continua muito além deste ponto – o cérebro continua a cicatrizar.';

  @override
  String get benzodiazepineReferenceDay365 =>
      'Um ano após os benzodiazepínicos: o pensamento e a memória continuam se recuperando\n\nFonte: Barker et al., \"Persistência de efeitos cognitivos após retirada do uso de benzodiazepínicos a longo prazo: uma meta-análise\", Archives of Clinical Neuropsychology (2004), no PubMed\n\nA evidência mais forte que temos\nOs pesquisadores combinaram estudos que testaram novamente usuários de benzodiazepínicos de longo prazo após pelo menos seis meses sem o medicamento.O resultado combinado mostra uma recuperação clara do pensamento e da memória após a abstinência.\n\nAs boas novas\nOs estudos combinados encontraram melhorias genuínas e mensuráveis em diversas áreas do pensamento e da memória após a abstinência.Cerca de um ano, a recuperação é ampla e óbvia em comparação com o uso ativo.\n\nA recuperação continua\nOs estudos combinados encontraram ampla recuperação no pensamento e na memória.Em um ano, você estará no bom caminho de uma tendência de recuperação que já era mensurável em seis meses.\n\nO que isso significa em um ano\nEspere uma recuperação substancial do pensamento, da memória e da clareza em um ano – a maioria das pessoas se sente visivelmente mais aguçada do que durante o uso.Mas se algumas áreas ainda estiverem atrasadas, isso é consistente com as evidências e não é um sinal de que você estagnou.A recuperação continua e um ano de abstinência é um marco importante e valioso nesse caminho.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 meses após os benzodiazepínicos: recuperação lenta, mas real\n\nFonte: Ashton, \"Síndromes de abstinência prolongada de benzodiazepínicos\", Journal of Substance Abuse Treatment (1991), no PubMed\n\nPor que a recuperação do Benzo demora tanto\nOs benzodiazepínicos atuam no GABA, o principal sistema calmante do cérebro.O uso a longo prazo altera a intensidade com que o sistema responde, e essas mudanças podem levar meses para serem revertidas.É por isso que a recuperação do benzo é medida em meses e não em semanas.\n\nOnde ficam 18 meses\nAshton descreve sintomas de abstinência mais duradouros que podem levar meses para aliviar.Aos 18 meses, o pior já passou para a maioria das pessoas e a ansiedade persistente, as alterações sensoriais e a confusão mental desapareceram substancialmente.\n\nLentamente Reversível\nCrucialmente, Ashton enquadra as alterações subjacentes como “alterações funcionais lentamente reversíveis no sistema nervoso central”.Lento, mas reversível – o longo cronograma reflete a profundidade da adaptação causada pelos benzodiazepínicos, e não os danos permanentes na maioria das pessoas.\n\nSinal de recuperação\nAshton descreve as mudanças subjacentes como lentamente reversíveis.Aos 18 meses, o sistema GABA calmante do cérebro teve muito tempo para se estabilizar e a direção dominante é a recuperação contínua em direção ao normal.';

  @override
  String get benzodiazepineReferenceDay730 =>
      'Dois anos após os benzodiazepínicos: progresso importante e duradouro\n\nFonte: Barker et al., \"Persistência de efeitos cognitivos após retirada do uso de benzodiazepínicos a longo prazo: uma meta-análise\", Archives of Clinical Neuropsychology (2004), no PubMed\n\nUm marco em recuperação\nDois anos é um marco importante, especialmente depois de uma longa retirada.As fases iniciais e persistentes dos sintomas já passaram há muito tempo e os ganhos do primeiro ano tiveram mais um ano para se fortalecerem.\n\nO que as evidências apoiam\nOs estudos combinados mostram recuperação em muitas áreas após a retirada.Aos dois anos, a maioria das pessoas relata ansiedade igual ou inferior ao nível pré-benzo, sono confiável sem medicação, emoções mais estáveis ​​e pensamento mais claro do que durante o uso.\n\nSinal de recuperação\nOs estudos combinados estabelecem a recuperação em muitas áreas do pensamento e da memória.Aos dois anos, a recuperação sustentada é a expectativa apoiada em evidências.\n\nMantendo a Perspectiva\nDois anos proporcionam ao sono, ao humor, à memória e ao raciocínio claro uma longa janela de recuperação.A evidência mostra uma melhoria substancial em todos os quatro, com a cura continuando a partir daqui.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'Três anos após os benzodiazepínicos: cura a longo prazo\n\nFonte: Barker et al., \"Persistência de efeitos cognitivos após retirada do uso de benzodiazepínicos a longo prazo: uma meta-análise\", Archives of Clinical Neuropsychology (2004), no PubMed\n\nA visão de longo prazo\nTrês anos estão no final do cronograma de recuperação do benzo.Para a grande maioria das pessoas, mesmo após uma abstinência grave e prolongada, os sintomas perturbadores já passaram e a qualidade de vida é transformada em comparação com o uso ativo.\n\nO que a meta-análise encontrou\nEstudos combinados de usuários de longo prazo mostram recuperação em muitas áreas após a retirada.Ao longo de anos de abstinência, a história dominante é a ampla recuperação do pensamento, da memória e das funções do dia-a-dia.\n\nSinal de recuperação\nPesquisas de longo prazo mostram recuperação em muitas áreas do pensamento e da memória.Aos três anos, as fases de retirada precoce e prolongada já ficaram para trás e esses ganhos tiveram anos para se fortalecerem.\n\nUma mensagem de esperança\nA jornada de recuperação do benzo é uma das mais exigentes da medicina, e três anos de cura sustentada são uma conquista profunda.A evidência é clara: o cérebro cicatriza substancialmente, a maioria das pessoas recupera a clareza, o sono e a amplitude emocional, e a melhoria continua com o tempo.';

  @override
  String get cocaineReferenceDay1 =>
      'Abstinência de cocaína: as primeiras 24 horas\n\nFonte: \"Síndromes de Abstinência\", StatPearls (NCBI Bookshelf), Biblioteca Nacional de Medicina dos EUA\n\nCocaína e o Cérebro\nA cocaína bloqueia a recaptação de dopamina (e outras monoaminas) nos circuitos de recompensa do cérebro, fazendo com que a dopamina se acumule e produza intensa euforia e energia.Com o uso regular, o cérebro se adapta regulando negativamente esse sistema, de modo que, sem a droga, as atividades normais parecem planas.\n\nO acidente\nStatPearls descreve a abstinência de estimulantes como começando com um \"choque\" quando o uso é interrompido, caracterizado por depressão acentuada, sono excessivo, fome, mau humor e grave lentidão de movimentos e pensamentos.Nas primeiras 24 horas, isso normalmente inclui:\n• Fadiga extrema e maior necessidade de sono\n• Humor deprimido e movimentos e pensamentos mais lentos\n• Aumento do apetite (a cocaína suprime o apetite)\n\nDesejos, irritabilidade e ansiedade também são comumente relatados durante esta janela na literatura mais ampla sobre dependência, embora StatPearls não os liste especificamente como parte da crise.\n\nAo contrário de algumas outras drogas\nStatPearls observa que a abstinência de estimulantes é tratada com observação e cuidados de suporte;ao contrário da abstinência de álcool ou benzodiazepínicos, normalmente não causa convulsões ou delírio.O principal perigo é psicológico – depressão e, em utilizadores pesados, pode ocorrer ideação suicida durante o acidente, pelo que é aconselhável apoio e monitorização.\n\nNenhum medicamento aprovado\nAtualmente não existem medicamentos aprovados para tratar a abstinência de cocaína;o manejo é de suporte, e abordagens não medicamentosas, como o manejo de contingências, são os tratamentos baseados em evidências para o transtorno de uso subjacente.';

  @override
  String get cocaineReferenceDay3 =>
      'Três dias sem cocaína: navegando no pico do desafio\n\nFonte: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), Biblioteca Nacional de Medicina dos EUA\n\nComo a cocaína afeta o corpo\nStatPearls documenta que a cocaína bloqueia a recaptação de dopamina, noradrenalina e serotonina, prolongando a estimulação simpática.Isto é o que impulsiona tanto a sua euforia como o seu perigo – pode afetar quase todos os sistemas orgânicos.\n\nDias 2–4: Pico da Retirada Psicológica\nNo terceiro dia, a crise aguda deu lugar à mais intensa retirada psicológica:\n• Humor deprimido e humor deprimido em sua forma mais intensa\n• Perda de prazer\n• Desejos fortes e desencadeados por estímulos\n• Ansiedade e inquietação\n• Sono perturbado – excessivo em alguns, insônia em outros\n\nO perigo cardiovascular diminui\nStatPearls identifica a toxicidade cardiovascular como o efeito mais letal da cocaína: aumento da frequência cardíaca e da pressão arterial, aumento da demanda miocárdica de oxigênio, vasoespasmo coronariano e ativação plaquetária – aumentando o risco de arritmia, infarto e acidente vascular cerebral, mesmo em usuários jovens.A meia-vida da cocaína é curta, cerca de uma hora, e no terceiro dia a droga em si já limpou completamente o seu sistema – embora StatPearls observe que seus metabólitos ainda podem causar constrição dos vasos sanguíneos por horas após o uso, e um metabólito pode durar semanas, então alguma tensão cardiovascular residual pode durar mais que a própria droga.\n\nA estrada à frente\nA fase aguda é intensa, mas são os sintomas psicológicos – depressão, desejos, perda de prazer – que requerem mais apoio e que persistem por mais tempo.';

  @override
  String get cocaineReferenceDay7 =>
      'Uma semana sem cocaína: começa a recuperação física\n\nFonte: \"Síndromes de Abstinência\", StatPearls (NCBI Bookshelf), Biblioteca Nacional de Medicina dos EUA\n\nA fase aguda está terminando\nStatPearls descreve a abstinência de cocaína como uma passagem do acidente inicial para uma fase de recuperação mais longa.No final da primeira semana, os piores sintomas geralmente diminuem enquanto o sistema de dopamina continua a se reconstruir.\n\nRecuperação física em andamento\nAssim que a estimulação simpática da cocaína cessa, seus efeitos cardiovasculares, do apetite, do sono e das vias aéreas começam a ser revertidos nos dias e semanas seguintes:\n• Frequência cardíaca e pressão arterial voltando ao normal\n• O apetite retorna gradualmente (a cocaína o suprime fortemente)\n• Padrões de sono começando a se estabilizar\n• Passagens nasais começando a cicatrizar, se cocaína foi inalada\n\nOs sintomas psicológicos continuam\nStatPearls observa que a depressão e a perda de prazer são características da abstinência de estimulantes e duram mais que os sintomas físicos:\n• O humor permanece baixo, embora menos grave do que no pico\n• Os desejos desencadeados por estímulos permanecem fortes\n• A concentração e a motivação ainda estão prejudicadas\n\nFase Pós-Aguda\nA abstinência então se transforma em semanas ou meses de melhora mais constante no humor, nos desejos e no pensamento claro.Conhecer esse padrão facilita o gerenciamento da parte mais lenta da recuperação.';

  @override
  String get cocaineReferenceDay14 =>
      'Duas semanas sem cocaína: encontrando estabilidade\n\nFonte: \"Síndromes de Abstinência\", StatPearls (NCBI Bookshelf), Biblioteca Nacional de Medicina dos EUA\n\nDuas semanas depois\nEm duas semanas, os sintomas graves do acidente – depressão profunda, sono excessivo e lentidão de movimentos e pensamentos – geralmente diminuíram.A recuperação agora está focada na reconstrução da saúde cerebral e emocional.\n\nHumor e estado emocional\nApós duas semanas, o humor ainda pode estar abaixo do normal enquanto o sistema de dopamina se recupera.Em comparação com a primeira semana, a profunda perda de prazer está a diminuir e momentos genuínos de bem-estar estão a regressar.\n\nDesejos e gatilhos\nOs desejos desencadeados por estímulos são um desafio significativo nesta fase.O cérebro formou fortes associações entre o uso de cocaína e ambientes, pessoas, emoções e atividades específicas.Encontrar qualquer um desses gatilhos pode produzir desejos intensos, mesmo quando o humor geral está melhorando.É importante evitar ambientes de alto risco e construir novas associações.\n\nMelhoria do sono\nO sono é geralmente mais estável e restaurador em duas semanas do que era durante a fase aguda de abstinência.A melhoria do sono tem um efeito positivo significativo no humor, no pensamento claro e na capacidade de controlar os desejos.\n\nConstruindo a Fundação\nComo os tratamentos baseados em evidências para o transtorno por uso de estimulantes são comportamentais – gerenciamento de contingências, terapia e apoio de pares – a marca de duas semanas é um momento importante para se envolver com estruturas de apoio que sustentarão a recuperação a longo prazo.';

  @override
  String get cocaineReferenceDay60 =>
      'Dois meses sem cocaína: o humor e a recompensa começam a se recuperar\n\nFonte: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), no PubMed Central\n\nO que o cérebro está fazendo\nEsta revisão sintetiza estudos humanos e animais sobre o que acontece ao cérebro quando o uso de cocaína é interrompido.A cocaína crônica altera o sistema dopaminérgico e reduz a atividade no córtex frontal;a recuperação desses sistemas é o substrato para as melhorias de humor e motivação que as pessoas notam na abstinência precoce.\n\nProgresso do sistema de recompensas\nEm estudos com animais, as alterações relacionadas com a cocaína nos receptores de dopamina e na reciclagem de proteínas voltaram a níveis saudáveis com a abstinência sustentada.À medida que o sistema de recompensa se recupera, a profunda perda de prazer aumenta e as recompensas diárias – comida, conexão, realização – parecem gratificantes novamente.\n\nSinal de recuperação\nAos dois meses, o humor está melhorando e o sono está mais estável, enquanto os sistemas de dopamina e do córtex frontal continuam a se reconstruir.Estudos com primatas mostram alterações no receptor e no transportador D1 relacionadas à cocaína voltando aos níveis de controle com abstinência sustentada.';

  @override
  String get cocaineReferenceDay90 =>
      'Três meses sem cocaína: recuperação dos marcadores de dopamina\n\nFonte: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), no PubMed Central\n\nPor que 90 dias é um marco\nEsta revisão destaca o ponto de três meses como biologicamente significativo.Em primatas não humanos, os receptores e transportadores de dopamina D1 que a cocaína elevou mostraram “evidência de um retorno aos níveis de controle” após cerca de 90 dias de abstinência – evidência direta de que o sistema de recompensa pode se reajustar quando a droga acaba.\n\nA frente do cérebro\nOs autores destacam a recuperação na parte frontal do cérebro como um dos sinais mais importantes de abstinência prolongada.Esta área lida com o controle de impulsos, a tomada de decisões e o autocontrole, e essas habilidades se fortalecem à medida que se recupera.\n\nO que mostra 90 dias\nAos 90 dias, estudos com primatas descobriram que as densidades D1, D2 e dos transportadores de dopamina não eram mais significativamente diferentes dos controles não medicamentosos.Mesmo após longa exposição, a recuperação substancial do sistema de dopamina já é visível neste ponto e continua com a abstinência.';

  @override
  String get cocaineReferenceDay180 =>
      'Seis meses sem cocaína: pensamento mais claro\n\nFonte: \"Recuperação estrutural e funcional do cérebro em indivíduos com transtornos por uso de substâncias durante a abstinência: uma revisão de estudos de neuroimagem longitudinal\", no PubMed Central\n\nRecuperação que você pode imaginar\nEsta revisão reúne estudos longitudinais de imagens cerebrais que examinam repetidamente as mesmas pessoas à medida que sua abstinência aumenta.Para a cocaína, relata que a actividade funcional recupera de forma mensurável com a abstinência sustentada.\n\nEvidência de imagens cerebrais\nDois estudos de ressonância magnética funcional acompanharam usuários de cocaína ao longo do tempo e ambos encontraram ativação melhorada no mesencéfalo e no tálamo com abstinência mais longa.Num deles, após cerca de seis meses de abstinência, o padrão de ativação do cérebro era comparável ao de controles saudáveis ​​não viciados.Entre as substâncias, a revisão observa que os resultados das imagens nucleares apontam para uma recuperação dopaminérgica com a abstinência.\n\nO que isso significa em seis meses\nEsses ganhos funcionais acompanham as melhorias reais que as pessoas relatam nesta fase:\n• Melhor atenção e memória de trabalho\n• Tomada de decisão e controle de impulso mais precisos\n• Humor mais estável e regulação emocional\n\nSinal de recuperação\nCerca de seis meses depois, uma coorte longitudinal de fMRI mostrou um padrão de ativação comparável ao de controles saudáveis não viciados, enquanto a ativação do mesencéfalo e do cérebro profundo melhorou à medida que a abstinência se prolongava.Isso é uma recuperação cerebral funcional com imagem direta.';

  @override
  String get cocaineReferenceDay365 =>
      'Um ano sem cocaína: tensão cardiovascular removida\n\nFonte: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), Biblioteca Nacional de Medicina dos EUA\n\nPor que o coração é central\nStatPearls identifica a toxicidade cardiovascular como o efeito mais letal da cocaína.Cada uso aumenta a frequência cardíaca, a pressão arterial e a demanda miocárdica de oxigênio, ao mesmo tempo que causa vasoespasmo coronariano e promove a formação de coágulos – uma combinação que causa ataque cardíaco, arritmia e acidente vascular cerebral, mesmo em jovens.\n\nO que um ano de abstinência remove\nCada dia sem cocaína é um dia livre desses insultos agudos.Ao longo de um ano, os repetidos aumentos na pressão arterial e na frequência cardíaca desapareceram, o risco de espasmo coronário induzido pela cocaína e de enfarte agudo foi eliminado e o coração já não é levado à incompatibilidade de oxigénio.\n\nSinal de recuperação\nA interrupção da cocaína interrompe o vasoespasmo coronariano repetido, a taquicardia, a hipertensão, a promoção de coágulos e a incompatibilidade de oxigênio que causam lesões cardíacas agudas.A fibrose ou miocardite existente continua sendo um problema médico, mas o repetido insulto desencadeado pela cocaína desapareceu.\n\nRecuperação cerebral também\nEm um ano, os sistemas de recompensa e autocontrole tiveram um tempo prolongado para se recuperar, apoiando um melhor controle dos impulsos, um humor mais estável e uma resposta mais forte às recompensas diárias.';

  @override
  String get cocaineReferenceDay730 =>
      'Dois anos sem cocaína: recuperação sustentada\n\nFonte: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), no PubMed Central\n\nA visão de longo prazo\nEsta revisão reúne o que estudos em humanos e animais mostram sobre a abstinência prolongada de cocaína.A sua conclusão central é que a preservação e recuperação da função do córtex frontal é o marcador mais importante da abstinência a longo prazo – os abstêmios a longo prazo (mais de 10 meses) apresentaram maior atividade do córtex frontal do que os abstêmios a curto prazo.\n\nO que continua a curar\n• Os marcadores de dopamina alterados pela cocaína continuam voltando ao normal com abstinência sustentada\n• A integridade reduzida da substância cinzenta e branca observada em usuários ativos e em abstinência precoce pode ser revertida com uma abstinência mais prolongada, possivelmente através da maturação contínua da mielina\n• Circuito de controle frontal – controle de impulso, julgamento, regulação emocional – fortalece\n\nSinal de recuperação\nOs autores levantam uma cautela científica genuína: algumas das diferenças entre os abstêmios de longo prazo podem refletir um “efeito de sobrevivência” – pessoas que começaram com maior integridade cerebral podem achar mais fácil permanecer abstinentes – em vez de apenas recuperarem.O que está claro é que dois anos sem cocaína apoiam um cérebro que funciona muito mais próximo do de um não-usuário e uma vida que não é apenas abstinente, mas substancialmente reconstruída.';

  @override
  String get ghbReferenceDay1 =>
      'Retirada de GHB: as primeiras horas\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\n⚠ Esta é uma emergência médica\nA abstinência de GHB está entre as abstinências de substâncias mais perigosas, rivalizando com a abstinência grave de álcool e benzodiazepínicos.Se não for tratada, pode evoluir para delírio em mais de metade dos casos, com oscilações perigosas na frequência cardíaca e na pressão arterial e convulsões.Qualquer pessoa dependente de GHB, GBL ou 1,4-butanodiol deve procurar desintoxicação hospitalar supervisionada, em vez de parar sozinha.\n\nPor que começa tão rápido\nA meia-vida do GHB é de apenas 30 a 60 minutos, e os usuários dependentes normalmente precisam redosear a cada 2 a 3 horas apenas para evitar a abstinência – muito mais rápido do que o álcool ou os benzodiazepínicos.Essa rápida farmacocinética é a razão pela qual os sintomas podem aparecer muito mais cedo do que com outras abstinências sedativas-hipnóticas.\n\nSintomas iniciais\nAnsiedade, insônia, tremor, sudorese, batimentos cardíacos acelerados e aumento da pressão arterial.';

  @override
  String get ghbReferenceDay3 =>
      'Retirada de GHB: os dias mais difíceis\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\nO trecho mais difícil\nEste estudo descobriu que vários sintomas principais de abstinência – dores musculares, contrações musculares, sensação de tensão e estresse, frequência cardíaca acelerada e cólicas abdominais – pioraram nos primeiros três dias, com uma queda de mais de 70% na gravidade de muitos sintomas no quarto dia.Esta janela inicial é geralmente o período de maior risco, quando a abstinência não tratada tem maior probabilidade de evoluir para delírio, convulsões ou oscilações perigosas na frequência cardíaca e na pressão arterial.\n\nRecursos graves\n• Agitação e ansiedade intensas\n• Alucinações auditivas e visuais, paranóia\n• Tremor, sudorese, coração acelerado e pressão alta\n• Risco de convulsões\n\nGestão\nO estudo descreve a redução gradual dos benzodiazepínicos e a redução gradual do GHB farmacêutico como os dois métodos de desintoxicação comumente usados, observando algumas evidências de que a redução gradual do GHB pode controlar os sintomas de forma mais eficaz do que os benzodiazepínicos sozinhos.Qualquer uma das abordagens requer um monitoramento rigoroso – não é seguro fazer isso em casa.';

  @override
  String get ghbReferenceDay7 =>
      'Uma semana de desconto no GHB\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\nA maioria dos sintomas está desaparecendo\nVários sintomas principais de abstinência caíram mais de 70% em gravidade ou prevalência nos primeiros quatro dias.Na redução supervisionada, a fase de redução durou em média 11 dias, seguida por uma fase de recuperação de cerca de seis dias – portanto, em uma semana, muitas pessoas já estão nessa melhoria, mesmo que o processo não esteja totalmente concluído.\n\nO que pode permanecer\n• Sudorese, tremores e mãos trêmulas\n• Dormir muito ou, inversamente, insônia e inquietação\n• Desejos\n\nO estudo descobriu que esses sintomas específicos mudaram comparativamente pouco, mesmo após 11 dias, portanto a persistência nesta semana não é incomum.A supervisão médica contínua continua importante até que a síndrome esteja claramente resolvida.';

  @override
  String get ghbReferenceDay14 =>
      'Duas semanas de desconto no GHB\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\nDepois da Síndrome Aguda\nEm duas semanas, a síndrome física aguda descrita neste estudo – cujas fases de redução gradual e recuperação juntas duram em média cerca de 17 dias sob tratamento supervisionado – geralmente foi resolvida ou está muito próxima disso.A frequência cardíaca, a pressão arterial e a maioria dos sintomas físicos devem estar se estabilizando.\n\nO que permanece\nO estudo sinaliza especificamente o desejo e a insônia como ainda presentes no momento da alta para alguns pacientes, observando que estes podem contribuir para o risco de recaída.Apoio e estrutura são importantes agora, mesmo que a perigosa fase inicial tenha ficado para trás.';

  @override
  String get ghbReferenceDay30 =>
      'Um mês de desconto no GHB\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\nOnde fica um mês\nA fase aguda e perigosa descrita neste estudo já passou há um mês.Em um mês, a fase aguda perigosa – concentrada nos primeiros dias e seguida por um período supervisionado de redução gradual e recuperação com duração média de aproximadamente duas semanas e meia – já passou há muito tempo.O desejo e a insônia são os principais riscos residuais de recaída identificados na alta.\n\nPor que o suporte ainda ajuda\nSe desejos, mau humor ou problemas de sono ainda estiverem presentes em um mês, isso está de acordo com o que os autores do estudo sinalizaram como fatores de risco de recaída – e é exatamente por isso que o apoio e a estrutura contínuos são importantes.';

  @override
  String get ghbReferenceDay90 =>
      'Três meses de desconto no GHB\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\nTrês meses de recuperação\nAos três meses, a síndrome aguda de abstinência de GHB está resolvida há muito tempo.Os riscos residuais identificados na alta são o desejo e a insônia, portanto, três meses de abstinência proporcionam ao sono, à estabilidade autonômica e às rotinas de prevenção de recaídas um tempo substancial para consolidação.\n\nO que as pessoas comumente relatam\n• Humor habitual mais calmo\n• Sono mais confiável\n• Pensamento mais claro e menos desejos\n\nSe ansiedade, insônia ou mau humor ainda forem proeminentes aos três meses, vale a pena discutir isso com um médico, em vez de presumir que isso se resolverá por conta própria.';

  @override
  String get ghbReferenceDay180 =>
      'Seis meses de desconto no GHB\n\nFonte: \"Caracterização da Síndrome de Abstinência de GHB\", no PubMed Central\n\nMeio ano depois\nAos seis meses, a síndrome aguda de abstinência de GHB está resolvida há muito tempo e a recuperação mudou completamente da desintoxicação para um sono estável, controle do desejo e prevenção de recaídas.A perigosa fase autônoma e propensa ao delírio pertence aos primeiros dias e semanas, não a esta fase.\n\nO panorama geral\nSuperar a abstinência do GHB com segurança e permanecer afastado por meio ano é uma grande conquista, dado o quão perigosa é a fase inicial e o quão real pode ser o risco de recaída – impulsionado em parte pelo desejo persistente e pela insônia.Vale a pena manter as rotinas e o apoio que trouxeram você até aqui.';

  @override
  String get inhalantsReferenceDay1 =>
      'Parar os inalantes: primeiro dia\n\nFonte: Radparvar, \"A Avaliação Clínica e Tratamento do Abuso de Inalantes\", The Permanente Journal (2023), no PubMed Central\n\nPor que a retirada acontece\nO uso crônico de inalantes causa neuroadaptação – o sistema nervoso passa a esperar a substância.Muitos inalantes afetam os mesmos circuitos cerebrais que o álcool, portanto, parar deixa o cérebro temporariamente desequilibrado.Os produtos químicos limpam o sangue rapidamente, mas são armazenados na gordura corporal, o que pode tornar o momento da retirada imprevisível.\n\nSintomas iniciais\nEsta revisão descreve a abstinência de inalantes como semelhante à abstinência de álcool ou benzodiazepínicos, com sintomas relatados incluindo:\n• Náuseas, vômitos e sudorese\n• Tremor e aumento da frequência cardíaca\n• Insônia e distúrbios do sono\n• Ansiedade e irritabilidade\n\nUma nota de segurança\nEm casos mais graves, a revisão também lista alucinações, delírios e convulsões entre os sintomas relatados, embora não estabeleça um cronograma diário preciso – trate-os como sintomas que podem ocorrer, e não como um cronograma fixo.A supervisão médica é aconselhável durante a desintoxicação, especialmente para usuários intensos e de longo prazo.';

  @override
  String get inhalantsReferenceDay7 =>
      'Uma semana de folga em inalantes\n\nFonte: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), no PubMed Central\n\nA janela aguda\nA abstinência de inalantes é descrita na literatura clínica como semelhante à abstinência de álcool ou benzodiazepínicos, mas geralmente é considerada de curta duração.No final da primeira semana, os sintomas físicos agudos – náuseas, tremores, sudorese, insônia – geralmente desaparecem para a maioria das pessoas.\n\nO que resta\n• Fadiga e confusão mental\n• Humor baixo ou instável\n• Desejos\n\nNota sobre abstinência precoce\nA névoa cerebral nesta fase não significa danos duradouros – o cérebro ainda está se reajustando.A pesquisa sobre como o pensamento e a memória se recuperam especificamente nas semanas e meses seguintes é abordada em marcos posteriores.';

  @override
  String get inhalantsReferenceDay14 =>
      'Duas semanas sem inalantes\n\nFonte: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), no PubMed Central\n\nAtravés da Fase Aguda\nRevisões clínicas descrevem a abstinência de inalantes como semelhante à abstinência de álcool ou benzodiazepínicos, mas mais curta.Em duas semanas, as náuseas, os tremores, a insônia e a ansiedade geralmente desaparecem.\n\nA estrada à frente\nAtenção, memória, movimento e coordenação recuperam-se mais gradualmente nos meses seguintes.A abstinência contínua dá a todos esses sistemas tempo para melhorar.Uma boa nutrição (o uso de inalantes pode esgotar a vitamina B12) e a abstinência preparam o terreno para isso.';

  @override
  String get inhalantsReferenceDay30 =>
      'Um mês de folga em inalantes\n\nFonte: Dingwall et al., \"Recuperação cognitiva durante e após tratamento para abuso de solventes voláteis\", Drug and Alcohol Dependence (2011), no PubMed\n\nOnde fica um mês\nO período de retirada antecipada já ficou para trás.Neste estudo, algumas habilidades de aprendizagem melhoraram em seis semanas, enquanto a coordenação visual, a memória, o planejamento e a tomada de decisões melhoraram de forma mais gradual nos meses seguintes.\n\nO que pode melhorar\n• Atenção e algumas tarefas de aprendizagem\n• Humor e sono, à medida que o corpo se estabiliza\n• Velocidade do motor, gradualmente\n\nSinal de recuperação\nA conclusão do estudo é clara: a memória, o planejamento e a tomada de decisões melhoram gradualmente ao longo de meses a anos de abstinência.A abstinência contínua é o motor mais forte dessa recuperação.';

  @override
  String get inhalantsReferenceDay90 =>
      'Três meses sem inalantes\n\nFonte: Dingwall et al., \"Recuperação cognitiva durante e após tratamento para abuso de solventes voláteis\", Drug and Alcohol Dependence (2011), no PubMed\n\nUm processo desigual e mais longo\nEste estudo acompanhou pessoas além de um programa de tratamento de oito semanas e verificou algumas delas novamente cerca de um ano depois.Algumas habilidades de aprendizagem melhoraram em seis semanas, enquanto a coordenação visual, a memória, o planejamento e a tomada de decisões continuaram melhorando durante um período mais longo.\n\nMantendo o curso\nO estudo mostra que as habilidades mais lentas melhoram gradualmente ao longo de meses ou anos.Aos três meses, a abstinência contínua é a alavanca mais forte para aumentar a recuperação mês após mês.';

  @override
  String get inhalantsReferenceDay365 =>
      'Um ano de folga em inalantes\n\nFonte: \"Um estudo prospectivo de alterações neurocognitivas 15 anos após abuso crônico de inalantes\", no PubMed\n\nRecuperação real e mensurável\nUm estudo de longo prazo encontrou recuperação substancial de problemas cerebrais e de pensamento crônicos relacionados a inalantes após dois anos de abstinência.Com um ano, você está no caminho da recuperação.\n\nO que isso significa\nA memória, a atenção e a função motora continuam a melhorar.A abstinência a longo prazo produz uma recuperação cerebral genuína: em dois anos, a maior parte das pontuações cerebrais, de memória e de pensamento tinham regressado ao normal em utilizadores crónicos que não sofreram danos cerebrais causados ​​pelo chumbo.';

  @override
  String get inhalantsReferenceDay730 =>
      'Dois anos sem inalantes\n\nFonte: \"Um estudo prospectivo de alterações neurocognitivas 15 anos após abuso crônico de inalantes\", no PubMed\n\nA marca de dois anos\nEste é o marco principal da investigação: os défices que reflectem danos cerebrais decorrentes do uso prolongado de solventes mostraram uma recuperação substancial após dois anos de abstinência.Os autores concluíram que, na ausência de danos cerebrais causados ​​pela gasolina com chumbo, a abstinência a longo prazo pode permitir a recuperação da função cerebral normal.\n\nSinal de recuperação\nA principal excepção são os danos causados pelo abuso de gasolina com chumbo, que pode causar défices persistentes.Caso contrário, dois anos de abstinência representam a oportunidade de cura mais bem documentada do cérebro – juntamente com uma vida reconstruída em torno dele.';

  @override
  String get ketamineReferenceDay1 =>
      'Parar a cetamina: primeiro dia\n\nFonte: \"Cistite induzida por cetamina: uma revisão abrangente dos efeitos urológicos desta droga psicoativa\", no PubMed Central\n\nA retirada é principalmente psicológica\nAo contrário dos opioides ou do álcool, a cetamina raramente produz abstinência física grave.A descontinuação é geralmente segura;as pessoas lutam com mais frequência contra desejos e dependência psicológica do que com doenças físicas.\n\nO que você pode sentir\n• Mudanças de humor e mau humor\n• Desejos\n• Sudorese ou palpitações ocasionais\n\nA etapa principal\nPara qualquer pessoa com sintomas de bexiga, a cessação imediata e completa é o ponto de partida obrigatório para a recuperação – portanto, o primeiro dia é a decisão mais importante de todas.';

  @override
  String get ketamineReferenceDay7 =>
      'Uma semana sem cetamina\n\nFonte: \"Cistite induzida por cetamina: uma revisão abrangente\", no PubMed Central\n\nA Fase Psicológica\nO principal desafio na cessação precoce da cetamina é psicológico: desejos, humor alterado ou deprimido e alguma confusão mental.A abstinência física, quando presente, geralmente é leve.\n\nA confusão mental é comum nesta fase – a concentração parece difícil, o tempo de reação é mais lento e a memória de curto prazo pode parecer pouco confiável.Esses efeitos no pensamento e na memória melhoram com a abstinência: um estudo longitudinal com 114 usuários de cetamina encontrou ganhos significativos na memória verbal, memória visual, velocidade de processamento e planejamento, foco e tomada de decisões após 12 semanas sem cetamina.\n\nSintomas da bexiga\nSe você tem cistite induzida por cetamina (urgência urinária, frequência, dor ou sangue na urina), parar agora dá à bexiga a melhor chance de cura.A dor pode levar as pessoas a voltarem à cetamina para se automedicarem – um ciclo que vale a pena quebrar com um suporte adequado para a dor.';

  @override
  String get ketamineReferenceDay14 =>
      'Duas semanas sem cetamina\n\nFonte: \"Cistite induzida por cetamina: uma revisão abrangente\", no PubMed Central\n\nPensamento mais claro\nCom a droga totalmente eliminada, a névoa mental e o pensamento desconectado associados ao uso regular de cetamina começam a desaparecer.A memória e a concentração melhoram e o humor se estabiliza.\n\nInício da recuperação da bexiga\nPara a cistite em fase inicial, a revisão enfatiza que simplesmente parar a cetamina é o passo mais importante para reverter os sintomas, e que a cessação precoce dá as melhores probabilidades de recuperação antes que os danos se tornem permanentes.Duas semanas de abstinência são o início desse processo.';

  @override
  String get ketamineReferenceDay30 =>
      'Um mês sem cetamina\n\nFonte: \"Prevalência e história natural de sintomas urinários entre usuários recreativos de cetamina\", Winstock et al., BJU International (2012)\n\nRecuperação da Bexiga\nO tratamento mais importante para a cistite induzida pela cetamina é interromper a administração da cetamina.Este estudo com usuários recreativos de cetamina descobriu que 51% daqueles com sintomas urinários relataram melhora após interromper o uso, enquanto menos de 4% pioraram.Quanto mais cedo você parar, melhor será o resultado.\n\nMente e humor\nA cognição e o humor continuam a melhorar após um mês.O apoio psicológico e social aumenta significativamente as probabilidades de permanecer parado – a cessação funciona melhor quando é apoiada.';

  @override
  String get ketamineReferenceDay90 =>
      'Três meses sem cetamina\n\nFonte: \"Cistite induzida por cetamina: uma revisão abrangente\", no PubMed Central\n\nRecuperação Continuada\nA recuperação da bexiga após a cetamina costuma ser gradual;a revisão descreve a melhoria da gravidade dos sintomas após a cessação, embora possa ser prolongada e variável.Três meses dão ao trato urinário tempo suficiente para cicatrizar nos casos que vão responder.\n\nMente\nO pensamento e o humor claros são marcadamente mais claros do que na abstinência precoce, e os desejos são menos frequentes.Sintomas persistentes ou graves da bexiga devem ser avaliados por um urologista.';

  @override
  String get ketamineReferenceDay180 =>
      'Seis meses sem cetamina\n\nFonte: \"Cistite induzida por cetamina: uma revisão abrangente\", no PubMed Central\n\nMeio ano depois\nCom a abstinência sustentada, os sintomas da bexiga continuam a melhorar nos casos que respondem à cessação, e o pensamento, a memória e o humor permanecem estáveis.A compulsão pelo uso enfraqueceu consideravelmente.\n\nSinal de recuperação\nA recuperação dos danos estabelecidos na bexiga pode ser incompleta, razão pela qual a cessação precoce é tão importante.Qualquer que seja o estágio em que você parou, permanecer afastado proporciona à bexiga o melhor resultado possível.';

  @override
  String get ketamineReferenceDay365 =>
      'Um ano de folga com cetamina\n\nFonte: \"Cistite induzida por cetamina: uma revisão abrangente\", no PubMed Central\n\nUm ano depois\nDoze meses de abstinência dão à bexiga, em casos precoces, a oportunidade máxima de recuperação e deixam o pensamento, a memória e o humor estáveis e claros.A dependência psicológica que dificultava a parada desapareceu em grande parte.\n\nO panorama geral\nUm ano livre é uma mudança profunda – na saúde física, na clareza e na autodireção.Manter o apoio que o trouxe até aqui protege isso.';

  @override
  String get kratomReferenceDay1 =>
      'Retirada do Kratom: o primeiro dia\n\nFonte: Swogger et al.(2022), \"Compreendendo o uso do Kratom: um guia para profissionais de saúde\", Frontiers in Pharmacology\n\nPor que a retirada acontece\nOs compostos ativos do Kratom atuam nos mesmos receptores opioides que os opioides clássicos.Com o uso regular, o corpo se adapta, então a interrupção produz uma abstinência semelhante à dos opioides.Este guia clínico descreve a dependência e a abstinência como riscos reconhecidos do uso regular da kratom.\n\nO que as evidências mostram sobre o início\nEstudos em animais citados no guia mostram sinais de abstinência somática surgindo em cerca de 12 horas, com efeitos semelhantes aos da ansiedade evidentes em 24 horas;O tempo preciso de início em humanos é menos estabelecido, mas os primeiros sintomas comumente relatados incluem:\n• Inquietação, ansiedade e irritabilidade\n• Dores musculares e coriza\n• Suor e olhos lacrimejantes\n• Desejos\n\nUma nota sobre gravidade\nO guia observa que uma utilização mais prolongada e doses mais elevadas estão associadas a uma abstinência mais grave e mais duradoura.Vale a pena procurar apoio médico supervisionado, especialmente se o kratom tiver sido usado em altas doses ou junto com opioides.';

  @override
  String get kratomReferenceDay3 =>
      'Retirada do Kratom: os dias mais difíceis\n\nFonte: Singh et al.(2014), Dependência de Drogas e Álcool — pesquisa com 293 usuários regulares de kratom na Malásia\n\nO que as evidências mostram\nEm vez de um único “dia de pico” definido, esta pesquisa descobriu que a gravidade da abstinência monitora quanto e por quanto tempo alguém usou: pessoas que bebem três ou mais copos de kratom diariamente tinham chances significativamente maiores de dependência grave e abstinência mais difícil.Para a maioria das pessoas, os primeiros dias após a interrupção são os mais difíceis.\n\nSintomas comumente relatados\n• Dores musculares e articulares, pernas inquietas\n• Insônia apesar da exaustão\n• Náuseas, cólicas estomacais e diarreia\n• Ansiedade, mau humor e irritabilidade\n• Desejos fortes\n\nSuperando isso\nHidratação, descanso e suporte sintomático ajudam.Se a abstinência parece grave até agora, isso corresponde ao uso mais intenso ou mais longo, em vez de algo estar incomumente errado – e tende a diminuir a partir daqui.';

  @override
  String get kratomReferenceDay7 =>
      'Uma semana de folga no Kratom\n\nFonte: Swogger et al.(2022), \"Compreendendo o uso do Kratom: um guia para profissionais de saúde\", Frontiers in Pharmacology\n\nPassada a Fase Aguda\nOs dados de autorrelato humano citados neste guia indicam que os sintomas de abstinência desaparecem em cerca de um a três dias para a maioria das pessoas que param.Em uma semana, os sintomas físicos agudos – dores musculares, suores, náuseas – normalmente se instalam na maioria.O que pode permanecer é mais psicológico: fadiga, perturbações do sono e mau humor, à medida que os receptores opióides que o kratom estimulava se ajustam novamente aos sinais do próprio corpo.\n\nUm risco real\nO guia também observa que um pequeno número de pessoas acha muito difícil abandonar o kratom, com abstinência mais grave e mais duradoura relatada entre usuários mais pesados e de longo prazo.Esta semana é um ponto comum para recaídas, e a tolerância cai rapidamente – regressar a uma dose anterior, especialmente se estiverem envolvidos opiáceos, é agora genuinamente perigoso.';

  @override
  String get kratomReferenceDay14 =>
      'Duas semanas de folga no Kratom\n\nFonte: Instituto Nacional sobre Abuso de Drogas (NIDA), \"Kratom\"\n\nAlém da janela estudada\nDados humanos controlados sobre o tempo de retirada da kratom geralmente cobrem apenas os primeiros dias, portanto não há pesquisas bem estabelecidas que estabeleçam um marco específico de “duas semanas”.O que está documentado é o padrão mais amplo: o kratom atua nos mesmos receptores opioides que os opioides clássicos e, à medida que o uso regular é interrompido, esses receptores restauram gradualmente sua sensibilidade aos sinais do próprio corpo.\n\nO que as pessoas comumente relatam\n• O apetite e a energia geralmente melhoram\n• O sono tende a se tornar mais confiável\n• O humor é normalmente mais estável, embora ainda variável\n\nOs desejos ainda são desencadeados pelo estresse e por sinais familiares, portanto, ter um plano para eles continua sendo útil.';

  @override
  String get kratomReferenceDay30 =>
      'Um mês de desconto no Kratom\n\nFonte: Instituto Nacional sobre Abuso de Drogas (NIDA), \"Kratom\"\n\nUm sistema de recompensa em recuperação\nO NIDA descreve o kratom como agindo nos receptores opióides do cérebro, sendo a dependência e a abstinência riscos reconhecidos do uso regular.Não existe nenhum estudo específico que estabeleça um marco de recuperação de “um mês”, mas o padrão geral para a dependência baseada nos receptores de opiáceos é que a resposta do cérebro aos prazeres quotidianos normaliza gradualmente com a abstinência sustentada.\n\nO que um mês de folga pode construir\nUm mês sem kratom é um mês de sono, refeições e rotina consistentes, substituindo o tempo e o esforço necessários.Os desejos tendem a chegar com menos frequência e parecem mais controláveis, embora os momentos de alto estresse continuem sendo os mais vulneráveis.';

  @override
  String get kratomReferenceDay90 =>
      'Três meses de folga no Kratom\n\nFonte: Instituto Nacional sobre Abuso de Drogas (NIDA), \"Kratom\"\n\nUm estado diário mais estável\nO Kratom atua nos receptores opioides, portanto, três meses sem ele dão aos sistemas de recompensa e estresse do cérebro tempo sustentado para se acalmarem.Muitas pessoas relatam um pensamento mais claro e uma motivação mais estável à medida que avançam com o uso ativo.\n\nPor que é importante\nQuanto menos recente for o uso, mais a atração diária do kratom tende a desaparecer – tornando este marco uma base sólida para uma recuperação duradoura.';

  @override
  String get kratomReferenceDay365 =>
      'Um ano de desconto no Kratom\n\nFonte: Instituto Nacional sobre Abuso de Drogas (NIDA), \"Kratom\"\n\nBem Passada a Abstinência Aguda\nO NIDA não publica um cronograma específico de recuperação do kratom de um ano, mas um ano de abstinência sustentada está muito além da janela de abstinência psicológica aguda e precoce documentada na pesquisa do kratom.Para a maioria das pessoas que chegam a esse ponto, os desejos são raros e muito mais fáceis de controlar.\n\nO panorama geral\nUm ano de abstinência representa uma mudança substancial na saúde, nas finanças e na autogestão.Permanecer conectado ao suporte ajuda a manter esse progresso seguro.';

  @override
  String get maoiReferenceDay3 =>
      'Descontinuação do IMAO: a fase de maior risco\n\nFonte: Dilsaver (1988), pesquisa sobre reações de abstinência de IMAO\n\nAviso crítico de segurança\nOs IMAOs apresentam os riscos de descontinuação mais graves de qualquer classe de antidepressivos.A cessação abrupta – particularmente de fenelzina e tranilcipromina – pode produzir reações graves, incluindo:\n• Ansiedade e agitação intensas\n• Fala pressionada e inquietação\n• Insônia ou sonolência\n• Alucinações\n• Delirium e psicose paranóica\n\nSe você estiver apresentando esses sintomas, procure atendimento médico imediato.\n\nComo funcionam os IMAOs\nOs IMAOs atuam ligando-se irreversivelmente e desativando as enzimas monoamina oxidase (MAO-A e MAO-B).Essas enzimas normalmente decompõem a serotonina, a noradrenalina, a dopamina e a tiramina no cérebro e no intestino.Como a própria enzima é destruída e não apenas bloqueada, a recuperação depende da produção de enzima nova pelo corpo, e não da rapidez com que o medicamento limpa a corrente sanguínea.';

  @override
  String get maoiReferenceDay7 =>
      'Uma semana após os IMAOs: Síntese da enzima MAO em andamento\n\nFonte: \"Inibidores da Monoamina Oxidase (IMAO)\" (StatPearls, NCBI Bookshelf)\n\nO processo de recuperação enzimática\nAo contrário dos ISRS, SNRIs e TCAs – que inibem a recaptação química cerebral de forma reversível – os IMAOs irreversíveis (fenelzina, tranilcipromina) destroem permanentemente as moléculas da enzima monoamina oxidase.A eliminação clínica é, portanto, governada pela rapidez com que o corpo consegue sintetizar uma enzima inteiramente nova – cerca de 2 semanas – e não pela rapidez com que o próprio medicamento limpa a corrente sanguínea.\n\nO que está acontecendo em uma semana\n• A síntese das enzimas MAO-A e MAO-B está bem encaminhada, aproximadamente na metade da janela de ressíntese de aproximadamente 2 semanas\n• A fase de risco agudo descrita no dia 3 está passando, embora uma supervisão médica rigorosa continue importante\n\nCuidados dietéticos\nO tratamento com IMAO requer uma dieta pobre em tiramina, uma vez que estas enzimas normalmente decompõem a tiramina e evitam que esta desencadeie uma crise hipertensiva.A orientação é continuar observando as restrições alimentares através desta janela de ressíntese – seu médico irá aconselhar quando for seguro relaxá-las.';

  @override
  String get maoiReferenceDay14 =>
      'Duas semanas após IMAOs: Atividade da enzima MAO recuperada substancialmente\n\nFonte: Fritz et al.(1983), Psiquiatria Biológica\n\nA marca crítica de duas semanas\nDuas semanas é o período de eliminação clínica padrão para a recuperação da enzima MAO após a descontinuação de um IMAO irreversível como a tranilcipromina ou a fenelzina.Estudando a tranilcipromina, esta pesquisa descobriu que a atividade catalítica da MAO-B das plaquetas – drasticamente reduzida dentro de um dia após a administração – volta ao normal dentro de cerca de duas semanas, à medida que o corpo substitui as plaquetas afetadas pela droga por novas contendo enzima ativa, embora os níveis totais de proteína MAO-B nunca tenham mudado.\n\nRecuperação de enzima MAO\n• A atividade plaquetária da MAO-B se recuperou substancialmente neste ponto\n• A MAO-A e a MAO-B do cérebro, que seguem um cronograma de ressíntese bastante semelhante, também são amplamente restauradas\n• O metabolismo normal da tiramina está se restabelecendo — as restrições dietéticas de IMAO normalmente podem ser relaxadas em consulta com seu médico\n\nRetorno do equilíbrio químico-cérebro\nCom a recuperação da atividade da enzima MAO, os sistemas químicos cerebrais afetados pelos IMAOs começam a ficar sob regulação natural:\n• A serotonina, a norepinefrina e a dopamina não estão mais elevadas pela inibição da MAO\n• A supersensibilidade dos receptores de monoamina (causada por níveis químicos cerebrais elevados crônicos de IMAO) está começando a desaparecer\n• A regulação natural do humor e da energia está retornando';

  @override
  String get maoiReferenceDay30 =>
      'Um mês após os IMAOs: reequilíbrio dos sistemas químicos cerebrais\n\nFonte: \"Inibidores da Monoamina Oxidase (IMAO)\" (StatPearls, NCBI Bookshelf)\n\nA avaliação de um mês\nUm mês após a descontinuação do IMAO já passou bastante da janela de ressíntese da enzima MAO de aproximadamente 2 semanas descrita nesta fonte, portanto, neste ponto, a atividade da enzima MAO já se recuperou totalmente e os sistemas químicos cerebrais estão sob regulação inteiramente natural.\n\nO que se recuperou em um mês\n• Atividade completa da enzima MAO: tanto a MAO-A quanto a MAO-B estão totalmente operacionais\n• Restrições alimentares resolvidas: dieta normal sem restrições de tiramina\n• Degradação natural da serotonina: o ciclo normal de renovação da serotonina do cérebro é restaurado\n• Regulação natural de catecolaminas: níveis de dopamina e norepinefrina regulados pela atividade natural da MAO\n\nCuidados com a interação medicamentosa\nOs IMAOs estão associados a interações potencialmente fatais com medicamentos serotoninérgicos.Esses riscos de interação foram resolvidos em um mês.No entanto, informe sempre o seu médico e farmacêutico sobre o uso anterior de IMAO quando qualquer novo medicamento for prescrito.';

  @override
  String get maoiReferenceDay90 =>
      'Três meses após os IMAOs: retirada bem passada\n\nFonte: \"Síndrome de abstinência de antidepressivos\", Therapeutics Letter 112 (2018), Therapeutics Initiative, na estante do NCBI\n\nRetirada em todas as classes de antidepressivos\nEsta revisão de evidências trata a abstinência de antidepressivos como um fenômeno real de tolerância e dependência – colocando os antidepressivos “ao lado dos opiáceos e dos benzodiazepínicos”.As suas evidências detalhadas centram-se nos ISRS e nos IRSN, mas as reações de abstinência são reconhecidas em todas as classes de antidepressivos, inclusive após a interrupção de um IMAO.Os sintomas \'geralmente aparecem alguns dias após a interrupção\' e \'a maioria... desaparece em 2 semanas\', embora alguns durem mais.\n\nOnde ficam três meses\nAos três meses, a fase aguda de abstinência está bem atrasada para a grande maioria das pessoas, e o corpo há muito se reajustou à regulação das monoaminas sem inibição da MAO.\n\nSinal de recuperação em \'Resensibilização do receptor\'\nAfirmações confiantes de que os receptores de serotonina, norepinefrina e dopamina foram todos “ressensibilizados em três meses” vão além do que as evidências indicam.O que é confiável: a fase de abstinência normalmente já foi resolvida e, para a maioria das pessoas, o humor, a energia e a amplitude emocional estão se estabilizando por meio de sinalização cerebral natural e autorregulada.\n\nRetirada versus recaída\nA Carta enfatiza a separação entre a retirada e o retorno genuíno da condição subjacente.Se os sintomas persistirem após três meses, revise-os com o seu médico, em vez de presumir que são apenas abstinência.';

  @override
  String get maoiReferenceDay180 =>
      'Seis meses após os IMAOs: recuperação a longo prazo\n\nFonte: Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nA avaliação de seis meses\nEsta revisão explica que os antidepressivos funcionam em parte fazendo com que os receptores de monoamina sejam regulados negativamente ao longo do tempo, e que esta regulação negativa requer semanas a meses para ser revertida assim que a medicação parar – um processo mais lento do que a própria ressíntese da enzima MAO, que leva cerca de duas semanas.\n\nOnde ficam seis meses\nSeis meses passam confortavelmente pela janela de reajuste dos receptores de semanas a meses para a grande maioria das pessoas, juntamente com a atividade enzimática que se normalizou totalmente no primeiro mês.Sinal de recuperação: cronogramas precisos para a ressensibilização completa dos receptores de serotonina, norepinefrina e dopamina não são estabelecidos com certeza diária na literatura – o que é confiável é que, aos seis meses, a maioria das pessoas está funcionando com sinalização cerebral natural e autorregulada.\n\nUma nota sobre fenetilamina\nOs IMAOs também inibem a degradação da fenetilamina (PEA), uma amina ligada ao humor e à energia.Espera-se que o seu metabolismo se normalize juntamente com a recuperação geral da enzima MAO, embora – tal como acontece com a ressensibilização dos receptores – um cronograma preciso específico da PEA não esteja estabelecido na literatura de investigação.';

  @override
  String get maoiReferenceDay365 =>
      'Um ano após IMAOs: recuperação alcançada\n\nFonte: \"Inibidores da Monoamina Oxidase (IMAO)\" (StatPearls, NCBI Bookshelf)\n\nUm ano: uma conquista notável\nCompletar um ano após a descontinuação do IMAO é um marco genuinamente significativo.Os IMAOs estão entre os antidepressivos que mais exigem a eliminação dos medicamentos, com um mecanismo irreversível, uma dieta rigorosa com baixo teor de tiramina e precauções de interação medicamentosa que são diferentes de qualquer outra classe de antidepressivos.\n\nO que este ano representa\n• Um ano inteiro de atividade natural e autorregulada da monoamina oxidase, baseada na ressíntese enzimática que foi concluída no primeiro mês\n• Capacidade demonstrada para manter o bem-estar sem inibição da MAO induzida por drogas\n• Um histórico longo o suficiente para ter certeza de que os riscos agudos de descontinuação do dia 3 estão firmemente atrás de você\n\nUma nota sobre IMAOs\nOs IMAOs permanecem excepcionalmente eficazes para certas condições resistentes ao tratamento e depressão atípica.A descontinuação bem sucedida não diminui o seu valor como medicamentos – demonstra a capacidade de recuperação do cérebro e a capacidade do paciente de navegar num processo médico excepcionalmente exigente.Uma precaução duradoura: continue a informar qualquer novo prescritor ou anestesista sobre o uso anterior de IMAO, uma vez que vale a pena sinalizar alguns riscos de interação medicamentosa indefinidamente.';

  @override
  String get marijuanaReferenceDay1 =>
      'Retirada de maconha: primeiro dia\n\nFonte: \"A síndrome de abstinência de cannabis: insights atuais\", Abuso de Substâncias e Reabilitação (2017), no PubMed Central\n\nA abstinência de cannabis é real\nEsta revisão revisada por pares estabelece que a Síndrome de Abstinência de Cannabis (SPC) é uma condição clínica bem validada, ocorrendo em aproximadamente 90% das pessoas diagnosticadas com dependência de cannabis após pararem.Seu pico médio de gravidade é comparável ao da síndrome de abstinência do tabaco.\n\nPor que a retirada acontece\nO THC atua no sistema endocanabinóide – receptores CB1 envolvidos no humor, apetite, sono, memória e estresse.Com o uso crônico, o cérebro regula negativamente esse sistema;quando a cannabis é interrompida, ela fica temporariamente subativa.A revisão observa que os receptores CB1 retornam ao funcionamento normal cerca de quatro semanas após a abstinência.\n\nInício no primeiro dia\nA revisão documenta que os sintomas físicos tendem a aparecer primeiro – dentro de 1 a 3 dias após o último uso – enquanto os sintomas psicológicos surgem ao longo de 2 a 10 dias.Os primeiros sintomas incluem:\n• Irritabilidade, ansiedade e inquietação\n• Dificuldade para dormir\n• Diminuição do apetite\n• Tensão física, suor ou calafrios\n• Humor deprimido\n\nGravidade\nA CWS não é clinicamente perigosa e os sintomas são geralmente leves a moderados, mas a revisão observa que eles podem ser angustiantes o suficiente para causar uma recaída – e é por isso que entender o cronograma é importante.';

  @override
  String get marijuanaReferenceDay3 =>
      'Cronograma de retirada de cannabis: os primeiros dias\n\nFonte: \"Evolução temporal dos sintomas de abstinência de cannabis do DSM-5 em abusadores de múltiplas substâncias\", BMC Psychiatry (2013), no PubMed Central\n\nUm curso de tempo medido\nEste estudo acompanhou os sintomas de abstinência de cannabis do DSM-5 em 90 pacientes durante quatro semanas, produzindo uma das imagens mais claras de como os sintomas aumentam e diminuem.A gravidade geral seguiu uma curva: aumentando e diminuindo nas semanas seguintes.\n\nO que atinge o pico mais cedo\nVários dos sintomas mais perturbadores fisicamente atingem o pico nos primeiros dias após a interrupção:\n• Insônia — pico por volta do primeiro dia\n• Nervosismo – pico por volta do 4º dia\n• Humor deprimido e sintomas físicos — pico por volta do 5º dia\n• Inquietação – pico por volta do 6º dia\n\nO que atinge o pico mais tarde\nO estudo descobriu que alguns sintomas surgem e atingem o pico depois da primeira semana:\n• Sonhos vívidos e desagradáveis – pico por volta do 11º dia\n• Irritabilidade e raiva – pico por volta do 14º dia\n\nSono e Cannabis\nOs sonhos vívidos e atrasados refletem a recuperação do REM: a cannabis suprime o sono REM durante o uso e o cérebro compensa quando para.Os autores argumentam que este sintoma é comum o suficiente para pertencer aos critérios formais de abstinência.\n\nA conclusão do terceiro dia\nNo terceiro dia, você está no auge do pico físico inicial - insônia, nervosismo e inquietação estão perto do pior.A curva consistente e previsível é por si só tranquilizadora: estes sintomas têm um curso conhecido e declinam a partir daqui.';

  @override
  String get marijuanaReferenceDay7 =>
      'Uma semana sem cannabis: através do pior\n\nFonte: \"A síndrome de abstinência de cannabis: insights atuais\", Abuso de Substâncias e Reabilitação (2017), no PubMed Central\n\nOnde uma semana fica na síndrome\nEsta revisão documenta que a síndrome de abstinência de cannabis geralmente dura até cerca de três semanas, com o período mais angustiante ocorrendo entre a primeira e a terceira semana.Em uma semana, os primeiros sintomas físicos – insônia, perda de apetite, inquietação – normalmente ultrapassaram o pico e estão diminuindo.\n\nO que ainda está se resolvendo\nA revisão distingue os sintomas físicos de pico precoce dos psicológicos de pico tardio.Em uma semana:\n• O desconforto físico e o apetite estão melhorando bastante\n• O sono ainda é interrompido para muitos, com sonhos vívidos (rebote REM) muitas vezes atingindo o pico agora\n• A irritabilidade e o humor podem permanecer elevados, pois tendem a atingir o pico mais tarde nas primeiras duas semanas\n\nA Neurobiologia da Recuperação\nSubjacente a estas mudanças, a revisão observa que os receptores CB1 regulados negativamente regressam ao funcionamento normal cerca de quatro semanas após a abstinência.Uma semana depois, essa re-regulamentação está bem encaminhada – o sistema está se recuperando mesmo enquanto alguns sintomas persistem.\n\nA conclusão\nAlcançar uma semana significa que o pico físico agudo ficou para trás.Os sintomas restantes de sono e humor fazem parte de uma síndrome com curso conhecido e finito que continua a se resolver nas próximas semanas.';

  @override
  String get marijuanaReferenceDay14 =>
      'Duas semanas sem cannabis: fim da abstinência aguda\n\nFonte: Budney, AJ et al.(2003) — estudo revisado por pares sobre o tempo de abstinência de cannabis\n\nResultados da pesquisa\nEste estudo revisado por pares documentou sistematicamente a evolução dos sintomas de abstinência de cannabis em usuários regulares.Os resultados mostraram que a síndrome de abstinência aguda atinge o pico na primeira semana e se resolve em grande parte dentro de 2 semanas após a interrupção da maioria dos sintomas.\n\nO que resolve em 2 semanas\nO estudo documentou que, em 14 dias, os seguintes sintomas foram amplamente resolvidos nos participantes do estudo:\n• Desconforto físico e sintomas corporais\n• Perturbação do apetite\n• Maioria perturbação do sono\n• Pico de irritabilidade e ansiedade\n\nO que pode persistir além de 2 semanas\nA pesquisa também identificou sintomas que persistiram além da marca de duas semanas em alguns usuários:\n• Humor deprimido\n• Dificuldades de concentração\n• Qualidade do sono (embora melhorando)\n\nO significado da marca de 2 semanas\nPassar a marca de duas semanas é significativo porque significa que a síndrome de abstinência aguda está praticamente completa.Os desafios para além deste ponto estão principalmente relacionados com a recuperação cerebral a longo prazo e com a gestão das razões subjacentes ao consumo de cannabis, e não com a resposta fisiológica aguda à interrupção.';

  @override
  String get marijuanaReferenceDay30 =>
      'Um mês sem cannabis: a função da memória melhora\n\nFonte: Papa et al.(2001), Arquivos de Psiquiatria Geral\n\nCannabis e memória: o problema\nEste estudo acompanhou usuários pesados e de longo prazo de cannabis durante 28 dias de abstinência confirmada e comparou os resultados dos testes de pensamento e memória com usuários leves e não usuários.No início da abstinência, e novamente nos dias 1 e 7, os utilizadores pesados ​​tiveram um desempenho pior do que os controlos na recordação de listas de palavras – um défice que acompanhava os seus níveis urinários de metabolitos de THC, reflectindo a exposição recente à droga, em vez do uso ao longo da vida.\n\nA boa notícia: recuperação até o dia 28\nNo dia 28, usuários frequentes, usuários leves e não usuários tiveram desempenho praticamente igual nos testes de pensamento e memória do estudo.Também não houve relação significativa entre o consumo total de cannabis ao longo da vida e o desempenho nos testes naquele momento.\n\nO que isso significa em 30 dias\n• A aprendizagem verbal e a recordação retornaram aos níveis do grupo de controle\n• Os défices residuais observados na primeira semana foram resolvidos\n• O défice remanescente anteriormente estava ligado à exposição recente e não a danos permanentes\n\nO que as evidências mostram\nNo dia 28, os usuários pesados eram praticamente indistinguíveis dos usuários leves e dos não usuários em todo o conjunto de testes de pensamento e memória do estudo.Os défices de aprendizagem verbal e de recordação observados na primeira semana recuperaram para os níveis do grupo de controlo.';

  @override
  String get marijuanaReferenceDay60 =>
      'Dois meses sem cannabis: concentração aumenta\n\nFonte: Roten et al.(2015), Comportamentos viciantes\n\nA questão da pesquisa\nEste estudo sobre a cessação da cannabis entre jovens acompanhou os resultados dos testes de memória e pensamento juntamente com os testes de urina durante cerca de dois meses, comparando os consumidores continuados com pessoas que pararam recentemente ou permaneceram abstinentes.\n\nPrincipais conclusões\nA abstinência consistente foi associada a uma melhoria significativa em:\n• Pontuação de memória composta\n• Memória verbal especificamente — o domínio mais afetado\n• Desempenho de movimento e velocidade de reação\n\nAos dois meses\nApós cerca de oito semanas de abstinência consistente, as pontuações de desempenho de memória, movimento e velocidade de reação subiram mensuravelmente acima de onde estavam durante o uso ativo, acompanhando de perto o não uso confirmado, em vez do tempo sozinho.\n\nO que o estudo mostra\nEm adolescentes e adultos jovens com dependência de cannabis, a abstinência consistente produziu ganhos significativos na memória composta, na memória verbal e no desempenho de movimento e velocidade de reação ao longo da janela de tratamento de aproximadamente dois meses.';

  @override
  String get marijuanaReferenceDay90 =>
      'Três meses sem cannabis: retorno da estabilidade do humor\n\nFonte: Connor et al.(2022), Addiction — uma revisão clínica da abstinência de cannabis\n\nComo realmente era o cronograma de retirada\nEsta revisão descreve os sintomas de abstinência de cannabis que geralmente começam 24 a 48 horas após a cessação e atingem o pico por volta dos dias 2 a 6.A raiva, a agressão e o humor deprimido podem aparecer já em uma semana, mas normalmente atingem o pico após cerca de duas semanas de abstinência;os distúrbios do sono, em particular, podem persistir por mais tempo do que outros sintomas.\n\nOnde ficam três meses\nAos três meses, você está muito além do curso de abstinência documentado: os sintomas geralmente começam dentro de 24 a 48 horas, atingem o pico por volta dos dias 2 a 6, e os sintomas de humor e sono ainda mais lentos atingem o pico nas semanas seguintes.Noventa dias dão aos efeitos do humor e do sono causados ​​pela abstinência meses para se acalmarem.\n\nUma nota sobre o sistema endocanabinoide\nA investigação sobre a abstinência de cannabis também mostra que os receptores CB1 desregulados regressam ao funcionamento normal cerca de quatro semanas após a abstinência.Aos 90 dias, você já ultrapassou a janela de recuperação do receptor.\n\nOlhando para o futuro\nA revisão também discute o prognóstico pós-desintoxicação e a prevenção de recaídas, sublinhando que o apoio contínuo e as estratégias de sobrevivência são importantes muito para além da janela de abstinência aguda.';

  @override
  String get marijuanaReferenceDay180 =>
      'Seis meses sem cannabis: planejamento e recuperação da tomada de decisões\n\nFonte: Crean, Crane & Mason (2011), Journal of Addiction Medicine\n\nPlanejamento e tomada de decisão após a cannabis\nEsta revisão examinou a atenção, a tomada de decisões, o autocontrole, a memória de trabalho e a fluência verbal desde as primeiras horas após o uso até a abstinência de longo prazo.Aos seis meses, você estará muito além dos efeitos de curto prazo e profundamente no período de recuperação.\n\nO que a pesquisa descobriu\nVários problemas ligados ao uso pesado diminuem com a abstinência sustentada, com alguns estudos encontrando recuperação em 28 dias.As áreas de recuperação mais lenta após uso intenso e precoce incluem:\n• Tomada de decisões e assunção de riscos — especificamente sinalizados como domínios onde os défices podem persistir a longo prazo em utilizadores intensivos e crónicos\n• Raciocínio abstrato e habilidades verbais — particularmente prejudicadas em adultos que começaram a usar antes dos 17 anos\n\nRecuperação precoce\nSeis meses está muito além dos efeitos de curto prazo nesta revisão.O planeamento, a tomada de decisões e o raciocínio continuam a melhorar com a abstinência sustentada, tornando a abstinência contínua o caminho mais forte para uma maior recuperação.\n\nO quadro mais amplo\nPara o uso mais leve e com início na idade adulta, as perspectivas são mais favoráveis – muitas pessoas aos seis meses relatam um pensamento mais claro, uma tomada de decisão mais estável e um senso de autodireção mais forte.Os maiores ganhos vêm de permanecer abstinente, especialmente após uso intenso ou de início precoce.';

  @override
  String get marijuanaReferenceDay365 =>
      'Um ano sem cannabis: estrutura cerebral se recupera\n\nFonte: \"Danos, proteção e recuperação do hipocampo após uso regular de cannabis\", Psiquiatria Translacional (2016), no PubMed Central\n\nMudanças Estruturais da Cannabis\nEste estudo de tomografia cerebral examinou o hipocampo, uma área cerebral central para a memória, em usuários atuais, ex-usuários e não usuários.Os utilizadores atuais não expostos ao CBD tinham um hipocampo cerca de 11% mais pequeno e um marcador de saúde das células cerebrais cerca de 15% mais baixo do que os controlos.\n\nA principal descoberta: recuperação com abstinência\nAs análises de ajuste de curva apoiaram um modelo de “proteção e recuperação”.Crucialmente, os antigos utilizadores – abstinentes durante uma média de cerca de 29 meses – não diferiram dos controlos de não utilização em qualquer medida de integridade.Os autores concluem que os danos na área da memória relacionados ao THC “podem ser recuperados com longos períodos de abstinência”.\n\nRecuperação cerebral ao longo de um ano ou mais\nApós um ano sem cannabis, o sistema de memória do cérebro está em plena recuperação: o tamanho do hipocampo e a saúde das células cerebrais estão voltando ao normal, apoiando a memória e o controle emocional.\n\nSinal de recuperação\nEx-usuários abstinentes por cerca de 29 meses corresponderam aos não usuários nas medidas de saúde do hipocampo do estudo.Em um ano, o sistema de memória já está seguindo o caminho de recuperação documentado em direção ao normal.';

  @override
  String get mdmaReferenceDay1 =>
      'Depois do MDMA: A Queda\n\nFonte: Meyer (2013), \"3,4-Metilenodioximetanfetamina (MDMA): Perspectivas Atuais,\" Abuso de Substâncias e Reabilitação\n\nPor que você se sente deprimido\nO MDMA funciona estimulando uma grande liberação de serotonina (com um pouco de dopamina).Depois disso, o cérebro fica temporariamente sem serotonina.Esta revisão descreve uma diminuição do humor – a chamada “tristeza do meio da semana” – que os pesquisadores mediram em usuários novatos e experientes 2 a 5 dias após o uso.\n\nO que ajuda\n• Hidratação e alimentação nutritiva\n• Dormir\n• Paciência — a queda é o esgotamento, não um estado permanente\n\nA queda após um único uso difere da abstinência relacionada à dependência, que a mesma revisão descreve como envolvendo desejos, mas sem sintomas físicos significativos.';

  @override
  String get mdmaReferenceDay3 =>
      'Alguns dias depois do MDMA\n\nFonte: Meyer (2013), \"3,4-Metilenodioximetanfetamina (MDMA): Perspectivas Atuais,\" Abuso de Substâncias e Reabilitação\n\nO blues do meio da semana\nEsta é aproximadamente a janela que esta revisão descreve quando discute a \"tristeza do meio da semana\" - uma queda no humor medida 2 a 5 dias após o uso em usuários novatos e experientes, ligada à depleção de serotonina a curto prazo, em vez de mudança a longo prazo.\n\nO que melhora\n• O humor normalmente melhora do seu ponto mais baixo agora\n• Retornos de energia\n• O sono começa a normalizar';

  @override
  String get mdmaReferenceDay7 =>
      'Uma semana após MDMA\n\nFonte: Meyer (2013), \"3,4-Metilenodioximetanfetamina (MDMA): Perspectivas Atuais,\" Abuso de Substâncias e Reabilitação\n\nDepois do blues do meio da semana\nPara a maioria das pessoas, já passou uma semana da janela de 2 a 5 dias que esta revisão associa ao declínio agudo, então o humor deve voltar ao normal.A revisão observa que, para as pessoas que fazem uso intenso ou repetido, os desejos podem persistir como parte de um padrão de dependência, embora não descreva isso como envolvendo sintomas de abstinência física significativos.\n\nQuando procurar ajuda\nSe o mau humor, a ansiedade ou os problemas de sono persistirem por uma semana, isso pode ser mais do que um declínio – vale a pena conversar com um profissional.';

  @override
  String get mdmaReferenceDay14 =>
      'Duas semanas de folga no MDMA\n\nFonte: Meyer (2013), \"3,4-Metilenodioximetanfetamina (MDMA): Perspectivas Atuais,\" Abuso de Substâncias e Reabilitação\n\nCronograma de recuperação\nPara uma redução de uso único, duas semanas já passaram da queda de 2 a 5 dias que esta revisão documenta, portanto, o humor, o sono e a concentração devem estar estáveis.Após uso mais intenso ou repetido, a recuperação continua além da recuperação, e estudos de imagem em abstinência mostram que a capacidade de reciclagem da serotonina aumenta com a abstinência sustentada.\n\nO que isso significa para você\nSe o seu uso foi ocasional, provavelmente você já passou pelo pior.Se foi frequente ou intenso, seja paciente consigo mesmo – a recuperação total da sinalização da serotonina é um processo mais longo do que duas semanas, abordado nos próximos marcos.';

  @override
  String get mdmaReferenceDay30 =>
      'Um mês de desconto em MDMA\n\nFonte: \"Disponibilidade do transportador de serotonina, função neurocognitiva e sua correlação em usuários abstinentes de MDMA\", no PubMed\n\nOnde fica um mês\nA crise aguda e a abstinência ficaram bem atrás de você, e o humor, o pensamento e a memória estão mais estáveis.Pesquisas de imagem mostram que o MDMA reduz a capacidade do cérebro de processar a serotonina e que essa capacidade se recupera com a abstinência sustentada.\n\nSinal de recuperação\nA mesma pesquisa mostra que a capacidade de reciclagem da serotonina se recupera com a abstinência sustentada.O humor e a função da serotonina melhoram primeiro, enquanto a memória continua no seu próprio cronograma de recuperação – a abstinência contínua apoia ambos.';

  @override
  String get mdmaReferenceDay90 =>
      'Três meses de folga no MDMA\n\nFonte: \"Disponibilidade do transportador de serotonina, função neurocognitiva e sua correlação em usuários abstinentes de MDMA\", no PubMed\n\nRecuperação Continuada\nCom a abstinência sustentada, o sistema de serotonina do cérebro continua a se recuperar, especialmente nas regiões mais profundas do cérebro.O humor e o sono normalmente estão estáveis ​​neste ponto.\n\nSinal de recuperação\nA abstinência sustentada impulsiona a recuperação contínua do transportador de serotonina em todas as regiões do cérebro, enquanto o humor e o sono permanecem estáveis e a recuperação do pensamento e da memória continua.';

  @override
  String get mdmaReferenceDay365 =>
      'Um ano de desconto em MDMA\n\nFonte: \"Disponibilidade do transportador de serotonina, função neurocognitiva e sua correlação em usuários abstinentes de MDMA\", no PubMed\n\nUm ano depois\nCom um ano de abstinência, o processamento da serotonina no cérebro se recuperou substancialmente e o humor está estável.\n\nSinal de recuperação\nUm ano inteiro de abstinência dá ao sistema serotoninérgico uma janela de recuperação prolongada.Pesquisas de imagem mostram que a capacidade de reciclagem da serotonina aumenta com a abstinência, tornando a recuperação substancial da serotonina o sinal biológico mais claro nesta fase.';

  @override
  String get methReferenceDay1 =>
      'Abstinência de metanfetamina: as primeiras 24 horas\n\nFonte: McGregor et al., \"A natureza, o curso do tempo e a gravidade da retirada da metanfetamina\", Addiction (2005), no PubMed\n\nO acidente\nA metanfetamina provoca uma grande liberação de dopamina;quando o uso é interrompido, o sistema fica esgotado.Este estudo acompanhou os sintomas de abstinência diariamente durante as primeiras três semanas de abstinência e descobriu que a gravidade geral atingiu seu nível mais alto nas 24 horas após o último uso - o \'crash\', uma mudança abrupta de estimulação extrema para exaustão física e psicológica.\n\nSintomas do primeiro dia\nO estudo documentou as características de abstinência que são mais intensas agora:\n• Fadiga extrema e aumento do sono (hipersonia)\n• Aumento do apetite (a metanfetamina suprime poderosamente o apetite)\n• Humor deprimido e perda de prazer\n• Desejos fortes\n• Ansiedade e irritabilidade\n\nSegurança Física\nA síndrome de abstinência da metanfetamina em si geralmente não é fatal, mas os sintomas relacionados à depressão medidos neste estudo podem ser graves desde o início e podem incluir pensamentos suicidas.A supervisão médica é fortemente aconselhável, especialmente para usuários pesados.\n\nComeça a levantar\nA descoberta encorajadora desta pesquisa: a gravidade é mais alta no início e depois diminui.A partir desse pico de 24 horas, os sintomas diminuem de forma constante nos dias seguintes – o pior ponto é o começo.';

  @override
  String get methReferenceDay3 =>
      'Abstinência de metanfetamina: terceiro dia — ainda na fase aguda\n\nFonte: McGregor et al., \"A natureza, o curso do tempo e a gravidade da retirada da metanfetamina\", Addiction (2005), no PubMed\n\nDescendo do Pico\nEste estudo descobriu que a gravidade geral da abstinência atinge o pico nas primeiras 24 horas e depois diminui em um padrão aproximadamente linear ao longo da fase aguda (cerca de 7 a 10 dias).No terceiro dia, você já passou do ponto mais alto, mas ainda está firmemente na fase aguda – os sintomas permanecem proeminentes mesmo quando a tendência é de queda.\n\nSintomas do terceiro dia\nOs recursos rastreados pelo estudo que ainda são significativos agora:\n• Depressão e perda de prazer\n• Desejos fortes\n• Dificuldade de concentração e pensamento claro\n• Sono perturbado — insônia alternando com hipersonia\n• Fadiga contínua\n\nPor que parece assim\nA intensidade da abstinência da metanfetamina reflete a escala de depleção de dopamina que ela causa.Os sintomas relacionados à depressão que o estudo mediu são mais evidentes nestes primeiros dias – mas o mais importante é que o estudo descobriu que a gravidade geral da abstinência “reduziu-se para níveis próximos ao controle no final da primeira semana de abstinência”.\n\nIsso vai passar\nO período mais difícil ocorre nos primeiros dias e os dados mostram um declínio constante a partir daqui.Compreender este estado como temporário e cerebral e nervoso – não uma condição permanente – ajuda a superá-lo.';

  @override
  String get methReferenceDay7 =>
      'Uma semana sem metanfetamina: termina a fase aguda\n\nFonte: McGregor et al., \"A natureza, o curso do tempo e a gravidade da retirada da metanfetamina\", Addiction (2005), no PubMed\n\nFim da Fase Aguda\nEsta é uma das descobertas mais encorajadoras da pesquisa.O estudo relatou que a gravidade geral da abstinência – incluindo os sintomas relacionados à depressão que rastreou – “reduziu-se para níveis próximos do controle no final da primeira semana de abstinência”, marcando o fim da fase aguda.A parte mais íngreme da subida está atrás de você.\n\nDuas fases de retirada\nOs autores descreveram a retirada da metanfetamina como tendo:\n• Uma fase aguda que dura cerca de 7 a 10 dias, na qual a gravidade dos sintomas cai continuamente desde o seu pico inicial\n• Uma fase subaguda que dura pelo menos mais duas semanas, com sintomas mais leves e persistentes\n\nO que resta no dia 7\nAo entrar na fase subaguda, os desafios dominantes são agora psicológicos e não de choque agudo:\n• Humor deprimido, embora tenha melhorado muito desde os primeiros dias\n• Desejos, especialmente em resposta a estímulos\n• Concentração e memória ainda em recuperação\n• O sono ainda está se acalmando\n\nRecuperação física em andamento\nCom o fim da fase aguda, o apetite voltou e a energia está se acumulando lentamente à medida que o corpo se recupera dos efeitos da metanfetamina no sono, na nutrição e no sistema cardiovascular.';

  @override
  String get methReferenceDay30 =>
      'Um mês sem metanfetamina: o humor melhora, os desejos persistem\n\nFonte: Zorick et al., \"Sintomas de abstinência em indivíduos dependentes de metanfetamina abstinentes\", Addiction (2010), no PubMed Central\n\nAcompanhando as primeiras cinco semanas\nEste estudo acompanhou participantes dependentes de metanfetaminas que permaneceram abstinentes por até cinco semanas, comparando-os com controles saudáveis – dando uma imagem invulgarmente clara de onde fica a marca de um mês.\n\nO que melhorou em um mês\n• Os sintomas depressivos \'diminuíram substancialmente durante as primeiras 2 semanas de abstinência para níveis baixos estáveis\' e, no final de quatro semanas, estavam a aproximar-se, embora ainda não estatisticamente correspondentes, de níveis de controlo saudável (a diferença tinha diminuído para uma tendência limítrofe e não significativa)\n• Os sintomas psiquiátricos e do tipo psicótico atingiram um nível inicial baixo no final da segunda semana\nAssim, aos 30 dias, a forte depressão da abstinência precoce desapareceu em grande parte – uma melhoria genuína e medida.\n\nO que ainda permanece\nO estudo deixou claro que um sintoma dura mais que os outros: o desejo “ainda continuou em um nível reduzido durante 5 semanas de abstinência”.Os desejos são mais fracos do que na primeira semana, mas não desapareceram, razão pela qual um mês ainda é um período de alto risco e o apoio contínuo é importante.\n\nA conclusão\nAo fim de um mês, a maquinaria do humor do cérebro já se recuperou o suficiente para que a sensação do dia-a-dia seja muito melhor do que na abstinência precoce – embora os desejos persistentes sejam uma parte normal desta fase e não um sinal de fracasso.';

  @override
  String get methReferenceDay90 =>
      'Três meses sem metanfetamina: a cura começou – seja paciente\n\nFonte: Volkow et al., \"Perda de transportadores de dopamina em usuários de metanfetaminas recupera com abstinência prolongada\", Journal of Neuroscience (2001)\n\nSobre esta pesquisa\nEste estudo histórico de tomografia cerebral acompanhou usuários de metanfetamina duas vezes – cerca de três meses sem metanfetamina e novamente cerca de 14 meses – para ver como o sistema de dopamina se recupera.\n\nOnde ficam três meses\nAos três meses, o período de abstinência precoce já passou e uma recuperação mais profunda da dopamina está em andamento.O mesmo estudo descobriu mais tarde que as proteínas que reciclam a dopamina nas áreas de recompensa e movimento do cérebro aumentaram cerca de 16% a 19% após 12-17 meses sem metanfetamina.\n\nO que isso significa para você\nAos 90 dias, a abstinência aguda já passou, o humor e o sono melhoraram e o envolvimento com a terapia torna-se muito mais produtivo.Mas a recuperação mais profunda da dopamina é um projeto mais longo que se desenrola no ano seguinte.Se a motivação e o prazer ainda se sentirem fracos aos três meses, isso é esperado e não um sinal de fracasso – a trajetória neste estudo é claramente ascendente a partir daqui.\n\nPor que vale a pena esperar\nO mesmo estudo mostrou que permanecer abstinente é o que impulsiona a recuperação: quanto mais longa a abstinência, maior será a recuperação do DAT medida.Três meses é a base;os ganhos continuam chegando.';

  @override
  String get methReferenceDay180 =>
      'Seis meses sem metanfetamina: o coração pode se recuperar\n\nFonte: \"Stopping Drug Abuse Can Reverse Related Heart Damage\", American College of Cardiology (2017), relatando um estudo no JACC: Heart Failure\n\nMetanfetamina e o Coração\nA metanfetamina é uma das drogas recreativas mais cardiotóxicas.Pode causar hipertensão grave e arritmias e, com o tempo, cardiomiopatia associada à metanfetamina – um enfraquecimento do músculo cardíaco que leva à insuficiência cardíaca.\n\nO que o estudo descobriu\nO ACC relatou pacientes com cardiomiopatia associada à metanfetamina (todos com função de bombeamento cardíaco significativamente reduzida).A conclusão central e esperançosa: parar de fumar “pode reverter os danos que a droga causa ao coração e melhorar a função cardíaca”.Os pacientes que pararam de usar tiveram resultados significativamente melhores do que aqueles que continuaram a usar, e os autores enfatizaram que a detecção precoce “poderia prevenir uma maior deterioração da cardiomiopatia”.\n\nPor que seis meses são importantes\nCada mês de abstinência remove o estresse tóxico contínuo do coração e dá ao músculo a chance de se recuperar.Aos seis meses, você proporcionou ao seu sistema cardiovascular uma pausa substancial e sustentada desses danos – exatamente a condição sob a qual este estudo observou melhorias.\n\nSinal de recuperação\nO resultado apoiado por evidências é forte: parar a metanfetamina pode reverter os danos cardíacos associados à metanfetamina e melhorar a função cardíaca.Seis meses sem o insulto estimulante repetido dão ao coração uma janela de recuperação substancial.';

  @override
  String get methReferenceDay365 =>
      'Um ano sem metanfetamina: recuperação cerebral mensurável\n\nFonte: Wang et al., \"Recuperação parcial do metabolismo cerebral em usuários de metanfetamina após abstinência prolongada\", American Journal of Psychiatry (2004), no PubMed\n\nO que a imagem mostra\nEste estudo de tomografia cerebral verificou usuários de metanfetaminas no início da abstinência e novamente após 12–17 meses.Encontrou uma recuperação cerebral genuína, com algumas áreas recuperando mais rapidamente do que outras.\n\nA boa notícia: recuperação profunda do cérebro e do pensamento\nO tálamo, um centro retransmissor cerebral profundo, começou a usar a energia de forma mais normal com a abstinência prolongada.Essa recuperação acompanhou um melhor desempenho de movimento e memória verbal, de modo que a melhoria do exame cerebral apareceu no pensamento e na memória reais.\n\nOs circuitos de recompensa se recuperam mais lentamente\nAos 12-17 meses, o centro de retransmissão cerebral profundo recuperou-se fortemente e esse ganho foi acompanhado por melhores movimentos e memória verbal.Os sistemas de recompensa e motivação também continuaram a fortalecer-se, tornando o cenário de um ano de grande recuperação do pensamento e da memória.\n\nO que isso significa em um ano\nEm um ano, espere um cérebro que pensa e lembra muito melhor do que no início da recuperação – uma cura clara e mensurável.Mas se a motivação ou a capacidade de sentir prazer ainda ficam por vezes atrasadas, isso é consistente com a ciência, e não uma falha pessoal: este estudo descobriu que esses circuitos de recompensa podem recuperar mais lentamente, com alguns défices ainda presentes bem mais de um ano depois.';

  @override
  String get methReferenceDay420 =>
      '14 meses sem metanfetamina: o marcador de dopamina se recupera\n\nFonte: Volkow et al., \"Perda de transportadores de dopamina em usuários de metanfetaminas recupera com abstinência prolongada\", Journal of Neuroscience (2001)\n\nA descoberta do título\nEste estudo histórico de tomografia cerebral verificou usuários de metanfetamina no início da abstinência e novamente após cerca de 12 a 17 meses.As proteínas que reciclam a dopamina aumentaram cerca de 16% a 19% nas áreas de recompensa e movimento do cérebro e atingiram níveis que já não diferiam significativamente dos controles saudáveis.Uma abstinência mais longa significou maior recuperação.\n\nPor que o DAT é importante\nEssas proteínas reciclam a dopamina depois de liberada.A metanfetamina os esgota, deixando o sistema de dopamina mal regulado.A recuperação deles em cerca de 14 meses é um sinal genuíno e mensurável de cura.\n\nSinal de recuperação\nApós 12 a 17 meses, as proteínas que reciclam dopamina nas áreas de recompensa e movimento aumentaram cerca de 16% a 19% e atingiram níveis de controle saudáveis.O sistema de dopamina voltou ao normal de forma mensurável, enquanto o pensamento, a memória e o movimento continuam melhorando.\n\nO que isso significa aos 14 meses\nO hardware do sistema de dopamina está se recuperando de forma mensurável em direção ao normal – motivo real para otimismo.Mas a recuperação funcional completa (memória, motivação, controle motor fino) pode ficar atrasada em relação à imagem e continua a melhorar com a abstinência contínua.';

  @override
  String get methReferenceDay730 =>
      'Dois anos sem metanfetamina: pensamento e humor continuam melhorando\n\nFonte: Iudicello et al., \"Melhoria a longo prazo no funcionamento neurocognitivo e sofrimento afetivo entre usuários de metanfetamina que alcançam abstinência estável\", Journal of Clinical and Experimental Neuropsychology (2010), no PubMed Central\n\nRecuperação que continua após um ano\nEste estudo acompanhou usuários de metanfetamina por cerca de 13 meses e comparou abstêmios estáveis com usuários continuados e controles saudáveis.A abstinência estável melhorou o pensamento geral e reduziu o sofrimento emocional, com os ganhos continuando além de um ano.\n\nO que melhora\n• O pensamento geral em abstêmios alcançou controles saudáveis, enquanto os usuários continuados permaneceram significativamente prejudicados\n• Os maiores ganhos foram na velocidade de processamento e na capacidade motora, especialmente para aqueles mais prejudicados no início\n• O humor melhorou acentuadamente: apenas os abstêmios apresentaram melhora significativa na depressão e no humor geral\n\nSinal de recuperação\nOs abstêmios estáveis alcançaram controles saudáveis no pensamento geral e relataram menos sofrimento emocional.A aprendizagem verbal, a memória de trabalho, o planeamento e a concentração podem continuar a melhorar para além do primeiro ano, pelo que a tendência de recuperação continua no segundo ano.\n\nDois anos depois\nA mensagem baseada em evidências: a abstinência sustentada continua a dar frutos bem depois do primeiro ano – pensamento mais aguçado, melhor humor e melhoria constante da função – mesmo que algumas áreas demorem mais para voltar.';

  @override
  String get nitrousOxideReferenceDay1 =>
      'Dia Um: O Gás Acabou, mas Assista B12\n\nFonte: Knuf & Maani, \"Óxido Nitroso\", StatPearls (Estante NCBI)\n\nQuão rápido ele limpa\nO óxido nitroso tem um rápido início de ação – 2 a 5 minutos – e é eliminado do corpo com a mesma rapidez quando você para de inalá-lo.Até hoje, nenhum gás permanece em seu sistema.\n\nO verdadeiro risco não é o gás\nO que importa depois de parar é o que a exposição repetida já pode ter feito.O óxido nitroso inativa a metionina sintase, uma enzima que depende da vitamina B12.StatPearls observa que a exposição repetida – ocupacional ou recreativa – pode levar à anemia megaloblástica e à disfunção cerebral e nervosa e, em casos raros, à degeneração da medula espinhal.\n\nSe você usou muito ou frequentemente\nNão está documentado que o óxido nitroso cause uma síndrome de abstinência física como os opioides ou o álcool, portanto, o primeiro dia não é sobre seu corpo exigir a droga.Trata-se de começar a prestar atenção aos sintomas relacionados à B12 – abordados nos próximos marcos – e ser verificado se algum aparecer.';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 horas: sem abstinência física, mas observe sintomas nervosos\n\nFonte: Knuf & Maani, StatPearls;Tikaria et al.(2026), Cureus\n\nAo contrário dos opioides ou do álcool, não está documentado que o óxido nitroso cause síndrome de abstinência física.Os impulsos nesta fase são o hábito e o desejo, e não o corpo que exige que a droga funcione.\n\nCuidado com estes\nUma revisão sistemática de 1.809 casos recreativos de óxido nitroso (Tikaria et al., 2026) descobriu que sintomas cerebrais e nervosos – especialmente formigueiro ou dormência (parestesia) – eram o sinal mais comum de danos relacionados com B12, aparecendo frequentemente mesmo quando os exames de sangue padrão pareciam normais.Problemas de marcha e fraqueza também foram relatados.\n\nSe você notar algum destes\nProcure avaliação médica.A mesma revisão constatou que os exames de sangue padrão (hemoglobina, soro B12) falharam uma parcela significativa de pacientes afetados – os exames de ácido metilmalônico (MMA) e homocisteína são mais sensíveis e devem ser solicitados especificamente se você revelar o uso de óxido nitroso.';

  @override
  String get nitrousOxideReferenceDay7 =>
      'Uma semana: faça o teste se você usou muito\n\nFonte: Tikaria et al.(2026), \"O legado tóxico do uso recreativo de óxido nitroso\", Cureus\n\nO que as evidências mostram\nEsta revisão sistemática descobriu que a deficiência de vitamina B12 proveniente do óxido nitroso é muitas vezes “funcional” – a vitamina B12 sérica parecia normal em cerca de metade dos pacientes afetados, mesmo quando apresentavam danos cerebrais e nervosos reais.A homocisteína e o MMA foram anormais com muito mais frequência (84% e 73% dos pacientes testados, respectivamente) e são os marcadores mais confiáveis.\n\nO que fazer\nSe o seu uso foi intenso ou frequente, uma semana de folga é um período razoável para consultar um médico e solicitar testes específicos de homocisteína e MMA – não apenas um nível padrão de B12 – especialmente se você tiver formigamento, dormência, problemas de equilíbrio ou fraqueza inexplicável.\n\nA recuperação cerebral é comum após a suspensão do nitro e o tratamento com vitamina B12: grandes séries clínicas relatam melhora parcial ou completa na maioria dos pacientes acompanhados, com a recuperação continuando durante os primeiros meses após o tratamento.';

  @override
  String get nitrousOxideReferenceDay14 =>
      'Duas semanas: sintomas cerebrais e nervosos merecem acompanhamento\n\nFonte: Tikaria et al.(2026), Cureus;Knuf & Maani, StatPearls\n\nO que foi relatado\nRelatos de casos e séries revisadas por Tikaria et al.descrevem danos nervosos relacionados ao óxido nitroso que se apresentam como perda sensorial, ataxia da marcha e, às vezes, fraqueza que afeta a marcha – achados que podem se assemelhar a outras condições cerebrais e nervosas e às vezes passam despercebidos se o uso de óxido nitroso não for mencionado a um médico.\n\nSinal de recuperação nos cronogramas\nNenhuma das fontes informa quanto tempo normalmente leva a recuperação depois que o uso é interrompido e qualquer deficiência é tratada.Os relatos de casos descrevem uma ampla gama de resultados – desde a recuperação total até déficits duradouros – dependendo em grande parte da quantidade de danos ocorridos antes do diagnóstico.O que é consistente na literatura é que o tratamento precoce leva a melhores resultados.\n\nSe você não foi verificado\nDuas semanas de folga ainda é um bom momento para fazer exames de sangue, mesmo sem sintomas – principalmente homocisteína e MMA, em vez de soro B12 sozinho.';

  @override
  String get nitrousOxideReferenceDay30 =>
      'Um Mês: Hábito e Desejo, Não Dependência Física\n\nFonte: Knuf & Maani, \"Óxido Nitroso\", StatPearls (Estante NCBI)\n\nOnde você está\nStatPearls não descreve o óxido nitroso como produtor de uma síndrome de dependência física, então um mês de folga significa que quaisquer impulsos persistentes são relacionados ao hábito, ao contexto social ou ao tédio, e não a um corpo ainda se adaptando à ausência da droga.\n\nA questão B12\nSe você foi testado e tratado para deficiência de vitamina B12, um mês é um período razoável para o seu médico verificar se seus níveis – e quaisquer sintomas – responderam.Se você não foi testado e usado muito, ainda vale a pena perguntar.\n\nO que está protegido\nCada mês que você não usa é um mês que você não está adicionando a nenhuma inativação existente da metionina sintase ou ao risco cerebral e nervoso que vem com ela.';

  @override
  String get nitrousOxideReferenceDay90 =>
      'Três meses: hora de verificar novamente, se ainda não o fez\n\nFonte: Tikaria et al.(2026), \"O legado tóxico do uso recreativo de óxido nitroso\", Cureus\n\nO que sabemos - e não sabemos\nEsta base de pesquisa é construída a partir de relatos de casos e séries de casos, e não de estudos de recuperação controlados, portanto, não há um cronograma publicado confiável sobre como os sintomas desaparecem especificamente em três meses.O que a evidência mostra é que os resultados variam amplamente – alguns pacientes com deficiência ligeira e detectada precocemente recuperam totalmente, enquanto aqueles com diagnóstico tardio ou lesões nervosas mais graves podem ter défices duradouros.\n\nA parte acionável\nSe você teve algum sintoma cerebral e nervoso e não fez exames de sangue de acompanhamento ou uma avaliação especializada, três meses de folga é um ponto sensato para fazê-lo.Se você foi tratado e está melhorando, este é um momento razoável para confirmar com seu médico se a tendência continua.\n\nFicar afastado é o que mais importa\nA revisão é consistente sobre uma coisa: a exposição contínua continua inativando a B12 e aumentando o risco.Não usar é o maior fator a seu favor.';

  @override
  String get nitrousOxideReferenceDay365 =>
      'Um ano: a melhor proteção é a abstinência contínua\n\nFonte: Knuf & Maani, StatPearls;Tikaria et al.(2026), Cureus\n\nOnde a evidência realmente chega\nNenhuma das fontes promete um cronograma de recuperação específico, e vale a pena ser honesto sobre isso – a literatura sobre óxido nitroso e deficiência de vitamina B12 é construída quase inteiramente a partir de relatos de casos individuais, em vez de estudos de acompanhamento de longo prazo.O que está bem estabelecido é o mecanismo: o óxido nitroso inativa a vitamina B12 toda vez que é usado, e interrompê-lo elimina totalmente o dano contínuo.\n\nSe você tivesse sintomas relacionados à deficiência\nOs relatos de casos descrevem uma ampla gama de resultados, desde a recuperação total até sintomas nervosos persistentes, em grande parte ligados à quantidade de danos ocorridos e ao quão precocemente foram tratados.Se você ainda estiver apresentando sintomas daqui a um ano, esse é um motivo para continuar trabalhando com um neurologista, e não um sinal de que nada pode ser feito – a recuperação do nervo pode continuar por um longo período.\n\nO que é certo\nUm ano sem óxido nitroso é um ano sem mais inativação da metionina sintase.Essa é a garantia de suporte de ambas as fontes.';

  @override
  String get opioidReferenceDay1 =>
      'Abstinência de opioides: primeiro dia\n\nFonte: \"Diretrizes Clínicas para Gerenciamento de Abstinência e Tratamento da Dependência de Drogas em Ambientes Fechados\", Organização Mundial da Saúde (2009), na estante do NCBI\n\n⚠ Nota de segurança\nA abstinência de opioides raramente é fatal em indivíduos saudáveis, mas causa sofrimento físico grave e acarreta um alto risco de recaída.A recaída após um período de abstinência é particularmente perigosa porque a tolerância cai rapidamente – usar a mesma dose que antes da abstinência pode causar overdose fatal.Supervisão médica e tratamento com agonistas opioides são fortemente recomendados.\n\nQuando a retirada começa\nO calendário de retirada da OMS define o momento por tipo de opioide:\n• Opioides de ação curta (heroína, oxicodona): início de 8 a 24 horas após o último uso, duração de 4 a 10 dias\n• Opioides de ação prolongada (metadona): início de 12 a 48 horas, duração de 10 a 20 dias\n\nSintomas do primeiro dia\nAs diretrizes da OMS listam as primeiras características da abstinência de opioides:\n• Ansiedade e agitação\n• Cãibras e dores musculares\n• Descarga aquosa dos olhos e nariz\n• Bocejo e transpiração\n• Insônia, com ondas de calor e frio\n• Náuseas precoces\n\nPor que parece tão ruim\nO sistema opioide regula a dor, o estresse, o bem-estar emocional e o conforto básico.O uso prolongado de opioides suprime a produção de opioides do próprio corpo (endorfinas).Quando os opioides são removidos, o corpo fica sem o seu sistema de conforto normal – sentindo dor, ansiedade e angústia a um nível que reflete a profundidade dessa supressão.As directrizes da OMS aconselham cuidados de suporte, incluindo beber 2–3 litros de água por dia e monitorizar 3–4 vezes por dia.';

  @override
  String get opioidReferenceDay7 =>
      'Uma semana sem opioides: pico de sintomas diminuindo\n\nFonte: \"Diretrizes Clínicas para Gerenciamento de Abstinência e Tratamento da Dependência de Drogas em Ambientes Fechados\", Organização Mundial da Saúde (2009), na estante do NCBI\n\nO pico e o declínio\nO calendário da OMS prevê a abstinência de opiáceos de curta duração entre 4 e 10 dias, com os sintomas a desenvolverem-se precocemente e depois a diminuir ao longo desse período.No final da primeira semana:\n• Vômitos e diarreia são amplamente resolvidos\n• As cãibras musculares são menos graves\n• O sofrimento físico é significativamente reduzido\n\nO que resta no dia 7\nEmbora os sintomas físicos agudos estejam a melhorar, persistem desafios significativos:\n• Insônia – a interrupção do sono é um dos sintomas de abstinência de opioides mais persistentes\n• Humor deprimido e monotonia emocional\n• Fadiga e fraqueza\n• Desejos\n• Ansiedade\n\nRetirada Pós-Aguda\nApós o primeiro período de abstinência, os problemas de sono, as mudanças de humor e as ondas de desejo podem continuar por semanas ou meses.O apoio contínuo é mais importante durante esta fase de recuperação mais longa.\n\nTratamento com Agonistas Opioides\nAs diretrizes da OMS descrevem a metadona e a buprenorfina como tratamentos eficazes que reduzem a gravidade da abstinência e apoiam a recuperação.Esses medicamentos também reduzem a mortalidade por transtorno por uso de opioides, e muitas pessoas em recuperação bem-sucedida a longo prazo os utilizam durante a fase inicial de recuperação.';

  @override
  String get opioidReferenceDay14 =>
      'Duas semanas sem opioides: padrões de sono começando a melhorar\n\nFonte: Pesquisa farmacológica revisada por pares sobre opioides e sono\n\nA conexão opioide-sono\nEste artigo de pesquisa examina a relação bidirecional entre o uso de opióides e perturbações do sono.As descobertas documentam que os opioides perturbam gravemente a arquitetura normal do sono através de múltiplos mecanismos:\n• Supressão do sono de ondas lentas (profundo)\n• Perturbação do sono REM\n• Causar distúrbios respiratórios do sono (apneia central do sono)\n• Interrupção da regulação do ritmo circadiano\n\nUm ciclo vicioso\nA investigação destaca a natureza bidireccional do problema: o uso de opiáceos perturba o sono e o sono deficiente aumenta a sensibilidade à dor e a intensidade do desejo, impulsionando ainda mais o consumo de opiáceos.Acabar com a dependência de opiáceos também significa quebrar este ciclo de perturbação do sono.\n\nDurma em duas semanas\nAos 14 dias de abstinência de opioides, o sono começa a normalizar:\n• A apneia central do sono (se presente) desaparece em poucos dias\n• O sono profundo de ondas lentas está começando a se recuperar\n• O sono REM está retornando à proporção normal\n• O início do sono está se tornando mais confiável\n\nO sono continua a ser um desafio significativo para muitas pessoas em duas semanas, mas a trajetória está claramente melhorando.Um sono melhor melhora diretamente o humor, reduz os desejos e apoia o pensamento claro necessário para a recuperação.';

  @override
  String get opioidReferenceDay30 =>
      'Um mês sem opioides: o pensamento e a memória começam a se recuperar\n\nFonte: Clínica Mayo\n\nCompreendendo o transtorno por uso de opióides\nA Clínica Mayo explica que os opióides se ligam a receptores em todo o cérebro e corpo, produzindo alívio da dor, euforia e sonolência.Com o uso repetido, o cérebro responde com menos força e produz menos substâncias químicas semelhantes aos opioides.Isso cria dependência física.\n\nPensamento e memória em um mês\nAos 30 dias, ocorreu uma recuperação significativa do pensamento e da memória.A pior névoa cerebral foi dissipada e a parte frontal do cérebro – que lida com o planejamento e o autocontrole – está se recuperando:\n• A tomada de decisões está melhorando\n• A memória de trabalho está se recuperando\n• Aumento da velocidade de processamento\n• Concentração mais confiável\n\nO sistema de endorfina\nNum mês, o sistema natural de endorfinas do cérebro está a recuperar ativamente: está a produzir mais dos seus próprios produtos químicos semelhantes aos opiáceos e a responder novamente com mais normalidade.A planura emocional e a menor tolerância à dor continuam melhorando à medida que a recuperação continua.\n\nPrevenção de recaídas\nA Clínica Mayo enfatiza que um mês de sobriedade não significa que o risco de recaída tenha passado – ele permanece elevado.A tolerância caiu significativamente, o que significa que a recaída com doses anteriores acarreta sério risco de overdose.';

  @override
  String get opioidReferenceDay60 =>
      'Dois meses sem opioides: os circuitos de estresse do cérebro começam a se acalmar\n\nFonte: \"Neuroplasticidade da amígdala estendida na abstinência de opióides e abstinência prolongada de opióides\", Frontiers in Pharmacology (2023)\n\nDe onde vêm os sentimentos negativos\nEsta revisão mapeia como o uso prolongado de opioides altera os circuitos de estresse e medo do cérebro.Durante a abstinência, esses circuitos tornam-se hiperativos enquanto a sinalização de dopamina nos circuitos de recompensa cai.Essa combinação ajuda a explicar a ansiedade, o mau humor e os desejos no início da recuperação.\n\nPor que dois meses trazem alívio\nFundamentalmente, a revisão documenta que algumas destas alterações são reversíveis.Em modelos animais, a perda de densidade da coluna vertebral na concha accumbens é descrita como “uma diminuição duradoura, mas reversível”, retornando aos valores anteriores ao medicamento ao longo de algumas semanas.À medida que estes circuitos de stress e recompensa se reregulam, a base mecanicista para a turbulência emocional de recuperação precoce diminui – consistente com a reatividade reduzida e o humor mais estável que muitas pessoas relatam por volta dos dois meses.\n\nSinal de recuperação\nAs alterações reversíveis na densidade da coluna e no circuito de estresse documentadas nesta literatura mostram um verdadeiro processo de recuperação biológica: o circuito que conduz o estado emocional negativo de dependência retorna ao seu estado pré-drogas durante a abstinência.';

  @override
  String get opioidReferenceDay90 =>
      'Três meses sem opioides: a química da recompensa começa a se recuperar\n\nFonte: \"Recuperação estrutural e funcional do cérebro em indivíduos com transtornos por uso de substâncias durante a abstinência: uma revisão de estudos de neuroimagem longitudinal\", Drug and Alcohol Dependence (2022), no PubMed Central\n\nDopamina e opioides\nOs opioides estimulam a liberação de dopamina no sistema de recompensa do cérebro.O uso a longo prazo deixa esse sistema esgotado: num estudo de tomografia cerebral, as proteínas que reciclam a dopamina estavam cerca de 30% abaixo dos níveis saudáveis ​​no início.Isso ajuda a explicar a perda de prazer observada no transtorno por uso de opioides e na recuperação precoce.\n\nA recuperação é gradual\nEsta revisão reuniu estudos longitudinais que examinaram novamente as mesmas pessoas durante a abstinência.O défice do transportador de dopamina recuperou-se em cerca de 20% ao longo de 6-12 meses de abstinência, e algumas anomalias frontais da substância cinzenta e da substância branca observadas na abstinência precoce já não eram detectáveis ​​após cerca de um mês.Aos três meses, você está no início da curva de recuperação: os sistemas frontal e de recompensa estão se recuperando de forma mensurável, mas ainda não terminaram.\n\nO que as pessoas experimentam\nÀ medida que esses circuitos se recuperam, muitas pessoas, por volta dos 90 dias, notam:\n• Prazer mais genuíno em atividades, comida e relacionamentos\n• Desejos reduzidos em comparação com a recuperação precoce\n• Pensamento mais claro e melhor tomada de decisões\n\nSinal de recuperação\nImagens humanas longitudinais mostram que a disponibilidade do transportador de dopamina aumenta ao longo de 6 a 12 meses de abstinência, enquanto as anormalidades frontais da substância cinzenta e branca começam a normalizar muito mais cedo.Aos 90 dias, a recuperação cerebral mensurável já está estabelecida.';

  @override
  String get opioidReferenceDay180 =>
      'Seis meses sem opioides: o sistema imunológico começa a se recuperar\n\nFonte: \"Efeitos da tolerância e abstinência de opióides no sistema imunológico\", Journal of Neuroimmune Pharmacology (2006), no PubMed\n\nOpioides e o sistema imunológico\nEsta revisão mostra que o uso prolongado de opioides enfraquece o sistema imunológico de várias maneiras:\n• Ação direta dos opioides nas células do sistema imunológico (células T, células NK, macrófagos)\n• Produtos químicos de sinalização imunológica interrompidos\n• Rompimento do eixo hipoprofundo-cérebro-hipófise-adrenal (HPA)\n• Maior suscetibilidade a infecções\n\nSinal de recuperação\nOs opioides de longo prazo suprimem várias partes do sistema imunológico.Aos seis meses sem opioides, essa supressão constante desapareceu há meio ano e a função imunológica está se reconstruindo ativamente em direção ao normal.\n\nO que significa seis meses\nSeis meses sem opioides proporcionam às células imunológicas, à sinalização imunológica e ao sistema de estresse do corpo tempo sustentado para se recuperarem ao normal.\n\nPor que isso ainda é importante\nIsto é particularmente relevante para as pessoas que injetaram opiáceos, que enfrentaram riscos adicionais de infeção, como o VIH e a hepatite C. A remoção dos opiáceos, a melhoria da nutrição e a manutenção da abstinência proporcionam ao sistema imunitário as condições necessárias para continuar a recuperar.';

  @override
  String get opioidReferenceDay365 =>
      'Um ano de folga em opioides: estrutura cerebral e recuperação química\n\nFonte: \"Recuperação estrutural e funcional do cérebro em indivíduos com transtornos por uso de substâncias durante a abstinência: uma revisão de estudos de neuroimagem longitudinal\", Drug and Alcohol Dependence (2022), no PubMed Central\n\nO que a imagem humana mostra\nEsta revisão reuniu os estudos que examinaram as mesmas pessoas com transtorno por uso de opioides mais de uma vez durante a abstinência.As descobertas apontam consistentemente para a recuperação:\n• As proteínas que reciclam dopamina nas áreas de recompensa e movimento, cerca de 30% abaixo do normal no início, aumentaram cerca de 20% ao longo de 6 a 12 meses sem opioides\n• Anormalidades frontais da substância cinzenta presentes na abstinência precoce não eram mais detectáveis após cerca de um mês de abstinência\n• A substância branca (frontal e cingulada) e a atividade frontal em estado de repouso também começaram a voltar ao normal no primeiro mês\n\nOnde fica um ano\nAos doze meses, você atingiu ou ultrapassou a janela mais longa que esses estudos mediram.O sistema de dopamina teve mais tempo para se recuperar, e os circuitos frontais que sustentam o autocontrole e o julgamento vêm se recuperando há meses – a contrapartida biológica do pensamento mais claro, dos desejos mais fracos e do humor mais estável que as pessoas descrevem em um ano.\n\nSinal de recuperação\nAo fim de um ano, o sinal de imagem humano é fortemente orientado para a recuperação: a disponibilidade do transportador de dopamina aumentou ao longo do período de 6 a 12 meses, enquanto as anomalias estruturais e funcionais frontais tiveram muitos meses para se normalizarem.';

  @override
  String get opioidReferenceDay730 =>
      'Dois anos sem opioides: uma base estável\n\nFonte: \"Tratamento do transtorno por uso de opióides\", Centros de Controle e Prevenção de Doenças (CDC)\n\nUma condição crônica, bem gerenciada\nO CDC descreve o transtorno por uso de opioides como “uma doença crônica que pode afetar qualquer pessoa” – “uma condição médica, não uma falha moral”.Alcançar dois anos de recuperação sustentada significa que você tem gerenciado essa condição com sucesso durante um de seus períodos mais vulneráveis.\n\nO que o CDC diz que funciona\nA orientação do CDC centra-se em tratamentos que mantêm a recuperação estável a longo prazo:\n• Medicamentos para transtorno de uso de opioides – buprenorfina, metadona e naltrexona – que são considerados especialmente eficazes\n• Combinar medicação com terapia comportamental e aconselhamento\n• Tratamento que dura períodos variados, adaptados à pessoa\nO CDC observa que esses medicamentos ajudam a “normalizar a química do cérebro” e a aliviar os desejos – a química que parecia sequestrada no vício ativo funciona com você novamente.\n\nFicar seguro\nO CDC insta as pessoas em recuperação a perguntarem ao seu médico sobre o risco de voltar a usar e a sobredosagem, e a manterem a naloxona à mão.A tolerância cai durante a abstinência, portanto, retornar aos opioides depois de tanto tempo é especialmente perigoso – saber que isso faz parte da proteção do que você construiu.\n\nDois anos depois\nO CDC deixa claro que a recuperação é muitas vezes um processo de longo prazo e não uma linha de chegada.Dois anos não é o fim da jornada – é uma base estável e saudável e uma forte evidência de que a abordagem que você está usando funciona.';

  @override
  String get pornographyReferenceDay1 =>
      'Dia Um: Retomando o Controle\n\nFonte: Kraus et al., Transtorno de comportamento sexual compulsivo na CID-11, World Psychiatry (2018).\n\nO problema clinicamente importante não é o uso da pornografia por si só.O Transtorno de Comportamento Sexual Compulsivo é definido em torno da dificuldade persistente de controlar o comportamento sexual repetitivo quando esse padrão causa sofrimento ou prejuízo significativo.O uso problemático da pornografia pode ser uma apresentação desse problema mais amplo.\n\nIsso torna o primeiro dia mais concreto do que místico: você interrompeu um comportamento que decidiu estar fora de controle.Um dia completo não prova uma reinicialização cerebral e nervosa, mas fornece a primeira observação real de quando os impulsos aparecem, quais situações os desencadeiam e o que você pode fazer em seu lugar.\n\nSe o seu uso não for angustiante, prejudicial ou difícil de controlar, a estrutura clínica do CSBD pode não se aplicar a você.Esses marcos destinam-se a pessoas que estão mudando deliberadamente o uso problemático ou compulsivo.';

  @override
  String get pornographyReferenceDay3 =>
      'Dia Três: Saiba como pode ser um desejo\n\nFonte: Lewczuk et al., Retirada e tolerância relacionadas ao transtorno de comportamento sexual compulsivo e uso problemático de pornografia, Journal of Behavioral Addictions (2022).\n\nEm uma amostra polonesa pré-registrada nacionalmente representativa de 1.541 adultos, experiências mais fortes de abstinência auto-relatadas foram associadas a maior CSBD e gravidade do uso problemático de pornografia.Entre os participantes com uso problemático de pornografia, as experiências comumente relatadas incluíam pensamentos sexuais difíceis de parar, desejo difícil de controlar, aumento da excitação, irritabilidade, alterações de humor e problemas de sono.\n\nInquietação, pensamentos sexuais intrusivos, impulsos fortes e irritabilidade estão documentados em pessoas com uso problemático mais grave.Se eles aparecerem por volta do terceiro dia, trate-os como um padrão real de abstinência e controle os gatilhos.\n\nAnote quais impulsos estão realmente acontecendo, o que os precedeu e que resposta ajudou.A recuperação fica mais fácil de controlar quando o gatilho é nomeado, em vez de tratado como um evento cerebral misterioso.';

  @override
  String get pornographyReferenceDay7 =>
      'Uma semana: o que um estudo randomizado de abstinência encontrou\n\nFonte: Efeitos de um período de abstinência de pornografia de 7 dias nos sintomas relacionados à abstinência em usuários regulares de pornografia, Archives of Sexual Behavior (2023).\n\nOs pesquisadores randomizaram 176 usuários regulares de pornografia para tentarem sete dias de abstinência ou continuarem normalmente.Em toda a amostra, a abstinência não produziu um aumento global significativo no desejo, no humor negativo ou nos sintomas de abstinência.\n\nUma análise exploratória encontrou aumento do desejo entre pessoas que combinaram altas pontuações de uso problemático com uso diário de pornografia antes do estudo.Esse resultado precisa ser replicado, mas é útil: uma primeira semana difícil pode ser real para usuários mais problemáticos, enquanto uma síndrome universal de abstinência de pornografia não é apoiada por este ensaio.\n\nSe você já passou uma semana, agora tem melhores evidências sobre seu próprio padrão do que qualquer linha do tempo genérica da Internet pode fornecer.';

  @override
  String get pornographyReferenceDay14 =>
      'Duas semanas: mapeie os gatilhos que realmente importam\n\nFonte: Determinantes biopsicossociais do uso problemático de pornografia: uma revisão sistemática (2023).\n\nEsta revisão sintetizou 66 estudos e descobriu que o uso problemático de pornografia está associado a uma combinação de fatores, e não a um simples mecanismo de dopamina.Fatores psicológicos e sociais identificados repetidamente incluíam desejo, estresse, evitação, solidão, autoestima, crenças negativas e estilo de enfrentamento.\n\nDuas semanas proporcionam exposição repetida a dias de semana, fins de semana, tédio, estresse, privacidade, dispositivos e outros contextos que podem ter sugerido o antigo comportamento.Use esses dados.Se o estresse for o gatilho, crie uma resposta ao estresse.Se a solidão for o gatilho, adicione contato.Se o acesso fácil for o gatilho, mude o ambiente.\n\nAs evidências apoiam o trabalho sobre os motivadores do uso problemático;não é necessário fingir que todas as pessoas seguem a mesma contagem regressiva biológica.';

  @override
  String get pornographyReferenceDay30 =>
      'Um mês: o controle é mais importante do que uma simples contagem de frequência\n\nFonte: Bőthe et al., Os problemas de funcionamento sexual estão associados ao uso frequente de pornografia e/ou ao uso problemático de pornografia?, Addictive Behaviors (2021).\n\nNuma amostra comunitária de 14.581 adultos, o uso problemático de pornografia teve uma associação positiva moderada com problemas de funcionamento sexual tanto em homens como em mulheres.A frequência do uso de pornografia por si só mostrou uma associação negativa fraca com esses problemas.\n\nEssa distinção é importante.As evidências não apoiam dizer a todos os usuários de pornografia que a frequência de visualização por si só prejudica a função sexual.O alvo clinicamente mais relevante é a perda de controle e os problemas que envolvem esse padrão.\n\nCom um mês, compare a vida agora com quando você começou: preocupação, tempo perdido, capacidade de parar, funcionamento sexual, conflito de relacionamento e angústia.Essas mudanças são mais importantes do que esperar por uma reinicialização cerebral mítica no dia 30.';

  @override
  String get pornographyReferenceDay90 =>
      'Três Meses: Mudança Durável é Possível\n\nFonte: Crosby & Twohig, Terapia de aceitação e compromisso para uso problemático de pornografia na Internet: um ensaio randomizado, terapia comportamental (2016).\n\nEste pequeno estudo randomizado comparou um programa ACT de 12 sessões com uma lista de espera em 28 homens adultos.A visualização de pornografia caiu muito mais no grupo ACT no final do tratamento, e reduções substanciais permaneceram no acompanhamento de três meses.\n\nO estudo não prova que 90 dias de abstinência por si só causem o mesmo resultado, e sua amostra foi pequena e demograficamente estreita.O que demonstra é importante: o uso problemático de pornografia é modificável e habilidades estruturadas podem produzir mudanças que persistem além do período imediato de tratamento.\n\nSe o seu progresso ainda depende principalmente de coragem, três meses é um bom ponto para fortalecer o sistema em torno dele: desencadear planos, aceitação de impulsos sem agir, atrito ambiental, responsabilidade e terapia quando necessário.';

  @override
  String get pornographyReferenceDay180 =>
      'Seis meses: o controle dos sintomas a longo prazo pode persistir\n\nFonte: Hallberg et al., Um estudo randomizado controlado de terapia cognitivo-comportamental administrada em grupo para transtorno hipersexual em homens, Journal of Sexual Medicine (2019).\n\nEm 137 homens com comportamento sexual descontrolado, sete semanas de TCC em grupo produziram maiores reduções nos sintomas hipersexuais e na compulsividade sexual do que uma lista de espera, juntamente com melhor bem-estar psiquiátrico.Os ganhos do tratamento permaneceram estáveis ​​no acompanhamento de três e seis meses.\n\nEste estudo cobriu o distúrbio hipersexual de forma mais ampla, em vez de apenas a abstinência de pornografia, por isso não deve ser transformado em uma afirmação de que todas as pessoas estão biologicamente recuperadas aos seis meses.Apoia uma afirmação mais forte e mais útil: a melhoria sustentada no comportamento sexual compulsivo pode permanecer estável durante este período de tempo.\n\nSeis meses é, portanto, um marco de manutenção.Mantenha as rotinas que facilitaram o controle ao invés de tratar a data como uma permissão para desmontá-las.';

  @override
  String get pornographyReferenceDay365 =>
      'Um ano: evidências de mudança duradoura de comportamento\n\nFonte: Efeitos de acompanhamento de um ano de um tratamento baseado na aceitação para hipersexualidade (2026).\n\nNo acompanhamento de um ano, os participantes deste estudo de tratamento baseado na aceitação não retornaram aos níveis de hipersexualidade anteriores ao tratamento.Os autores descreveram os resultados como evidências preliminares de benefícios duradouros e clinicamente significativos, com controle percebido sobre o desejo entre os processos seguidos ao longo do tempo.\n\nEsta é uma evidência de acompanhamento do tratamento, não uma prova de uma reinicialização cerebral de um ano.De qualquer forma, a afirmação significativa é melhor: o controlo clinicamente relevante pode persistir durante um ano em vez de desaparecer assim que a intervenção inicial termina.\n\nUm ano de mudanças mantidas por você também é um grande conjunto de dados pessoais.Compare o controle atual, a angústia, o funcionamento, os relacionamentos e o uso do tempo com o ponto de partida;esses são os resultados que importam clinicamente.';

  @override
  String get pornographyReferenceDay1825 =>
      'Cinco anos: o controle de longo prazo é o resultado\n\nFonte: Transtorno de comportamento sexual compulsivo e uso problemático de pornografia: uma revisão interdisciplinar abrangente informada por especialistas (2026).\n\nAs revisões modernas tratam o CSBD e o uso problemático da pornografia como problemas complexos que envolvem controle, angústia, funcionamento, contexto e diferenças individuais.Não há limite validado de redefinição cerebral e nervosa de cinco anos.\n\nMas cinco anos não é um marco vazio.São 1.825 dias mantendo a direção comportamental que você escolheu.Como o problema clínico é a perda persistente de controle com sofrimento ou prejuízo, o controle sustentado e o funcionamento restaurado ao longo dos anos são resultados significativos por si só.\n\nNeste estágio, a questão útil não é mais se o seu cérebro atingiu uma porcentagem fictícia de religação.É se o antigo padrão ainda controla suas escolhas ou atrapalha a vida que você deseja.Caso contrário, será um sucesso substancial a longo prazo.';

  @override
  String get smokingReferenceDay1 =>
      'Primeiro dia: benefícios começam agora\n\nFonte: NHS Melhor Saúde\n\nOs benefícios começam em minutos – não em dias.O corpo começa a normalizar assim que a fumaça cessa.\n\nO que acontece hoje\n• 20 minutos: a frequência cardíaca começa a voltar ao normal\n• 8 horas: o monóxido de carbono no sangue cai pela metade;os níveis de oxigênio estão se recuperando\n• 48 horas: o monóxido de carbono caiu ao nível de um não fumante\n\nO monóxido de carbono liga-se aos glóbulos vermelhos com mais força do que o oxigênio, deslocando-os do sangue.Cada órgão estava recebendo menos oxigênio do que deveria.Isso se reverte em dois dias.\n\nA retirada começa no primeiro dia\n• Desejos — cada um durando normalmente de 3 a 5 minutos\n• Irritabilidade e dificuldade de concentração\n• Aumento do apetite\n\nEstes são temporários e gerenciáveis.O programa NHS Better Health oferece suporte gratuito, incluindo aplicativos e aconselhamento farmacêutico.';

  @override
  String get smokingReferenceDay3 =>
      'Dia Três: Pico de Retirada\n\nFonte: McLaughlin, Dani & De Biasi\n\nEm 72 horas, a nicotina desaparece do seu corpo.O cérebro construiu receptores extras de nicotina durante os anos de fumo;agora eles estão subestimulados, causando a síndrome de abstinência.\n\nSintomas de pico\n• Desejos — mais intensos agora\n• Irritabilidade, frustração, inquietação\n• Dificuldade de concentração\n• Ansiedade\n• Dores de cabeça\n• Aumento do apetite\n• Tosse (as vias aéreas estão desobstruídas – um bom sinal)\n\nEste é o dia mais difícil.Não pode ficar pior do que isso - a partir daqui os sintomas diminuem constantemente à medida que seu cérebro se reajusta.\n\nA TRN, a vareniclina e a bupropiona reduzem significativamente a gravidade da abstinência nesta fase.';

  @override
  String get smokingReferenceDay7 =>
      'Uma semana: retorno do paladar e do olfato\n\nFonte: NHS Melhor Saúde\n\nChegar a uma semana sem fumar é um forte preditor de sucesso a longo prazo – as pessoas que passam a primeira semana têm muito mais probabilidade de deixar de fumar para sempre.\n\nO que foi recuperado\n• A comida fica mais saborosa\n• Os cheiros são mais vívidos\n• A respiração é mais fácil – as vias aéreas estão desobstruídas\n• A circulação está melhorando\n• A pele fica melhor hidratada\n\nFumar prejudica diretamente os receptores de paladar e olfato;poucos dias depois de parar, eles começam a se recuperar.\n\nA abstinência aguda da nicotina está diminuindo.Os desejos físicos são mais curtos e menos frequentes.Os desejos baseados em gatilhos ainda podem estar presentes, mas o pior da urgência física já ficou para trás.';

  @override
  String get smokingReferenceDay14 =>
      'Duas semanas: circulação melhora\n\nFonte: NHS Melhor Saúde\n\nDentro de 2 a 12 semanas após a interrupção, a circulação sanguínea melhora.A nicotina estreita os vasos sanguíneos a cada cigarro;sem ele, os vasos relaxam e o sangue flui mais livremente.\n\nO que isso significa\n• O fluxo sanguíneo para mãos, pés e tecidos periféricos melhora\n• Muitas pessoas notam mãos e pés mais quentes\n• Andar e subir escadas começa a ficar mais fácil\n\nCom o monóxido de carbono já eliminado do sangue no primeiro dia e a circulação melhorando agora, o oxigênio chega aos músculos de forma mais eficaz.\n\nOs cílios que revestem as vias aéreas estão se recuperando e expelindo o muco acumulado.Se você tossir mais do que o normal, é um sinal de recuperação, não um revés.';

  @override
  String get smokingReferenceDay30 =>
      'Um mês: aumento da função pulmonar\n\nFonte: NHS Melhor Saúde\n\nA respiração torna-se mais fácil e a função pulmonar melhora – aumentando até 10% no período de 3 a 9 meses.Em um mês, você já está nessa curva de recuperação.\n\nO que está acontecendo nos pulmões\n• Os cílios cresceram novamente e estão eliminando o muco de forma mais eficaz\n• A inflamação das vias aéreas está diminuindo\n• A tosse persistente do fumante está desaparecendo\n• A tolerância ao exercício está melhorando\n\nQuaisquer tosse, chiado no peito e problemas respiratórios melhoram à medida que a função pulmonar aumenta.Um mês é um ponto significativo nessa curva de recuperação.';

  @override
  String get smokingReferenceDay90 =>
      'Três meses: queda no risco de ataque cardíaco\n\nFonte: PMC — Efeitos cardiovasculares do tabagismo e da cessação (2024)\n\nFumar prejudica o coração e as artérias de várias maneiras: acelera o acúmulo de placas nas artérias, promove a coagulação do sangue, aumenta a pressão arterial e danifica o revestimento arterial.Os efeitos pró-coagulantes e promotores de coágulos são revertidos alguns dias após a interrupção, e esta revisão relata um declínio notável nos ataques cardíacos e derrames no primeiro ano após a interrupção.\n\nO que melhorou agora\n• Os fatores de coagulação sanguínea estão se normalizando\n• A pressão arterial e a frequência cardíaca estão se estabilizando\n• A queda precoce mais acentuada no risco de eventos cardiovasculares agudos está bem encaminhada\n\nOs benefícios de ação mais lenta – reverter anos de acúmulo de placa arterial – demoram mais e são abordados em etapas posteriores.Cada mês sem fumo contribui para a recuperação.';

  @override
  String get smokingReferenceDay180 =>
      'Seis meses: recuperação das defesas imunológicas\n\nFonte: Período sem fumo e recuperação da função das células imunológicas alveolares (PubMed)\n\nFumar suprime as células imunológicas nas profundezas dos pulmões, prejudicando sua capacidade de engolir e matar bactérias.A recuperação é gradual – aqueles que estão abstinentes há apenas 2 meses apresentam maior comprometimento, enquanto a função melhora de forma constante com abstinência mais longa.Aos 6 meses, as defesas imunitárias pulmonares recuperaram substancialmente.\n\nO que isso significa\nOs pulmões podem eliminar bactérias e partículas inaladas de forma mais eficaz, reduzindo a suscetibilidade a resfriados, gripes e pneumonia.\n\nAs defesas imunitárias continuam a melhorar depois dos seis meses – mas agora a protecção do corpo é marcadamente mais forte do que naquelas primeiras semanas.';

  @override
  String get smokingReferenceDay365 =>
      'Um ano: o risco de ataque cardíaco cai acentuadamente\n\nFonte: PMC — Cessação do Tabagismo e Resultado do AVC;CDC, Benefícios de parar de fumar\n\nFumar praticamente duplica o risco de acidente vascular cerebral, promovendo o acúmulo de placas nas artérias, aumentando a coagulação sanguínea, aumentando a pressão arterial e danificando os vasos sanguíneos cerebrais.O cronograma de benefícios de abandono do próprio CDC coloca a queda acentuada no risco de ataque cardíaco na marca de 1 a 2 anos – você está no limite dessa janela.\n\nCronograma de recuperação\nA normalização total do risco de AVC leva mais tempo: o estudo de AVC citado acompanhou os que abandonaram o hábito durante uma mediana de quase cinco anos para mostrar uma taxa de AVC significativamente mais baixa do que os fumantes continuados, e os dados do CDC colocam o risco de doença coronariana reduzido pela metade em 3 a 6 anos, com o risco de AVC diminuindo ao longo da marca de 5 a 10 anos.\n\nUm ano ainda é um marco médico genuíno – a parte mais acentuada do declínio do risco agudo já ficou para trás, embora os benefícios cardiovasculares e oncológicos a longo prazo continuem a aumentar durante anos.';

  @override
  String get smokingReferenceDay1825 =>
      'Cinco anos: queda no risco de câncer\n\nFonte: CDC, Benefícios de parar de fumar\n\nAos cinco anos, chegam alguns dos benefícios mais dramáticos do câncer.\n\nMarcos de cinco a dez anos\n• Risco adicional de câncer de boca, garganta e caixa vocal: reduzido pela metade\n• Risco de acidente vascular cerebral: diminuindo\n\nAinda à frente\n• Dez anos: risco de morte por cancro do pulmão reduzido aproximadamente para metade (após 10-15 anos);risco de câncer de bexiga, esôfago e rim diminuindo\n• Quinze anos: risco de doença coronariana próximo ao de um não fumante\n• Vinte anos: risco de cancro da boca, garganta e caixa vocal próximo dos níveis dos não fumadores;risco adicional de câncer cervical caiu pela metade\n\nCinco anos sem fumar é uma conquista genuína – agora você está dentro da janela onde algumas das reduções mais significativas do risco de câncer acontecem, embora vários benefícios (como a normalização total do risco de doença coronariana) ainda estejam a anos de distância.';

  @override
  String get snriReferenceDay3 =>
      'Descontinuação do SNRI: os primeiros dias\n\nFonte: Harvard Health Publishing\n\nNota importante de segurança\nOs SNRIs só devem ser interrompidos sob supervisão médica após uma redução gradual.A venlafaxina (Effexor), em particular, tem uma meia-vida extremamente curta de aproximadamente 5 horas, o que significa que o medicamento é eliminado do corpo muito rapidamente e os sintomas de descontinuação podem ser graves e repentinos.\n\nPor que os SNRIs são mais difíceis de parar do que os ISRSs\nOs IRSNs afetam duas substâncias químicas cerebrais reguladoras do humor – serotonina e noradrenalina – o que significa que ambas precisam ser reajustadas quando você para.Os sintomas de descontinuação são frequentemente mais intensos com ISRSs do que com ISRSs:\n• Sintomas semelhantes aos da gripe (fadiga, sudorese, dores musculares)\n• Insônia e distúrbios do sono\n• Náusea – muitas vezes mais pronunciada do que com ISRSs\n• Desequilíbrio e tontura\n• Distúrbios sensoriais — \'zaps cerebrais\' podem ser muito intensos com venlafaxina\n• Hiperexcitação, irritabilidade e ansiedade\n\nComparando IRSNs\nA venlafaxina apresenta o perfil de descontinuação mais difícil devido à sua meia-vida curta.A duloxetina (Cymbalta) tende a ser um pouco mais fácil devido à sua meia-vida mais longa, de 12 horas.A desvenlafaxina fica entre os dois.';

  @override
  String get snriReferenceDay7 =>
      'Uma semana após SNRIs: ajuste de dois sistemas químicos cerebrais\n\nFonte: NHS – Parar ou interromper os antidepressivos (orientação geral sobre antidepressivos; os mecanismos específicos da noradrenalina abaixo refletem a farmacologia geral do SNRI, em vez dos detalhes específicos do SNRI da própria página do NHS)\n\nO desafio do sistema duplo\nAo contrário da maioria dos antidepressivos que afetam um sistema, os IRSNs afetam tanto a serotonina quanto a noradrenalina.Em uma semana, ambos os sistemas estão se ajustando:\n\nEfeitos do sistema de noradrenalina\nO sistema de noradrenalina governa a resposta de luta ou fuga do corpo, a regulação da pressão arterial e os níveis de energia.À medida que se reajusta:\n• Podem ocorrer flutuações na pressão arterial\n• A ansiedade pode parecer mais física (coração acelerado, suor)\n• Os níveis de energia podem ser inconsistentes\n\nEfeitos do sistema serotonina\nSimultaneamente, o sistema da serotonina está se ajustando – produzindo os sintomas de abstinência típicos da interrupção de qualquer antidepressivo.A combinação do ajuste de ambos os sistemas pode tornar a primeira semana particularmente desafiadora.\n\nFisicamente, isso geralmente se mostra como uma melhora na estabilidade da pressão arterial e menos episódios de tontura ao ficar em pé.Emocionalmente, o humor é mais variável do que será em 30 dias, mas não está mais em queda livre.';

  @override
  String get snriReferenceDay14 =>
      'Duas semanas após SNRIs: sintomas físicos desaparecem\n\nFonte: Davies & Read (2019), Comportamentos viciantes\n\nStatus de duas semanas\nPara a maioria das pessoas que seguem uma redução gradual adequada, a fase física aguda é amplamente resolvida em duas semanas:\n• Zaps cerebrais significativamente reduzidos ou ausentes\n• Náuseas e sintomas semelhantes aos da gripe foram resolvidos\n• Tonturas e problemas de equilíbrio melhorando\n• A pressão arterial e a frequência cardíaca se estabilizam à medida que a noradrenalina se reequilibra\n\nO que pode persistir\n• Sensibilidade emocional e variabilidade de humor\n• Ansiedade – que o sistema de noradrenalina influencia particularmente\n• Fadiga, pois o sistema de noradrenalina proporciona estado de alerta e energia\n\nContexto de pesquisa\nA revisão sistemática de Addictive Behaviors (Davies & Read, 2019) confirmou que os efeitos da descontinuação dos SNRI estão entre os mais graves de qualquer classe de antidepressivos, com a venlafaxina associada a taxas particularmente elevadas de sintomas de abstinência significativos.';

  @override
  String get snriReferenceDay30 =>
      'Um mês após SNRIs: Estabilização de sistema duplo\n\nFonte: Davies & Read (2019), Addictive Behaviors — revisão sistemática da incidência, gravidade e duração da abstinência de antidepressivos\n\nA Fase de Estabilização\nUm mês representa um marco significativo na recuperação da serotonina e da noradrenalina.Esta revisão descobriu que, embora uma minoria substancial de pessoas experimente efeitos de abstinência que duram mais de algumas semanas, a maioria das pessoas já passou da fase aguda e mais grave dos sintomas físicos de descontinuação neste ponto.\n\nO que normalmente melhora em um mês\n• Os sintomas físicos de descontinuação (choques cerebrais, náuseas, tonturas) foram resolvidos para a maioria\n• Pressão arterial retornando ao nível natural\n• Melhoria da qualidade do sono — padrões de sono REM restaurados naturalmente\n• Os níveis de energia começam a se estabilizar à medida que a regulação da noradrenalina se normaliza\n\nResolução de embotamento emocional\nUma das experiências mais comumente relatadas nesta fase é a resolução do embotamento emocional – muitas pessoas que tomam SNRIs notam uma amplitude emocional “achatada”.À medida que a droga desaparece e o cérebro se reajusta, o alcance emocional e a sensibilidade normalmente retornam.';

  @override
  String get snriReferenceDay90 =>
      'Três meses após SNRIs: retirada bem passada\n\nFonte: \"Síndrome de abstinência de antidepressivos\", Therapeutics Letter 112 (2018), Therapeutics Initiative, na estante do NCBI\n\nPor que os SNRIs merecem cuidado extra\nEsta revisão de evidências destaca os antidepressivos de meia-vida curta – incluindo a venlafaxina e a duloxetina (ambos IRSNs) – como apresentando um risco maior de sintomas de abstinência.Um estudo financiado pelo fabricante descobriu que 51% das pessoas que interromperam a duloxetina apresentaram um ou mais sintomas.Portanto, a retirada do SNRI pode ser pronunciada, e é exatamente por isso que uma redução gradual e supervisionada é importante.\n\nOnde ficam três meses\nA Carta observa que os sintomas de abstinência “geralmente aparecem alguns dias após a interrupção” e que “a maioria dos sintomas de abstinência de antidepressivos desaparecem dentro de 2 semanas” (ocasionalmente mais tempo).Aos três meses, a fase aguda de abstinência já está bem atrasada para a grande maioria das pessoas.\n\nSinal de recuperação em \'Recuperação do receptor\'\nCronogramas populares afirmam que os sistemas de serotonina e noradrenalina foram “totalmente reequilibrados” em três meses.A evidência sólida diz respeito à síndrome de abstinência e ao seu momento, e não a um relógio preciso de recuperação dos receptores.O que é confiável: em três meses, a fase de abstinência normalmente foi resolvida e muitas pessoas notam que o embotamento emocional que alguns sentem nos IRSNs diminui após a interrupção.\n\nRetirada versus recaída\nA Carta aconselha distinguir a retirada de um verdadeiro retorno da condição subjacente.Se a ansiedade ou o mau humor persistirem após três meses, revise-os com o seu médico, em vez de presumir que se trata apenas de uma abstinência.';

  @override
  String get snriReferenceDay180 =>
      'Seis meses após SNRIs: recuperação cerebral e nervosa\n\nSinal de recuperação em dados de seis meses\nSeis meses após uma redução gradual completa e supervisionada por um médico, o grave período de abstinência precoce do SNRI já ficou para trás.Humor, sono, função sexual e pensamento claro tiveram meses para se recuperar:\n• Vias de serotonina: substancialmente restauradas\n• Vias de noradrenalina: normalizadas, com o sistema de resposta ao estresse também se estabilizando\n• Arquitetura do sono: deverá ser totalmente restaurada\n• Função sexual: amplamente restaurada para a maioria das pessoas (a disfunção sexual é um efeito colateral comum dos SNRI, embora para alguns possa persistir e vale a pena discutir com um médico)\n\nResiliência ao estresse\nMuitas pessoas aos seis meses relatam uma resiliência notavelmente melhorada aos factores de stress diários, à medida que o papel do sistema de noradrenalina na excitação e na resposta ao stress – que os SNRIs modulam poderosamente – regressa ao seu nível natural.';

  @override
  String get snriReferenceDay365 =>
      'Um ano após SNRIs: Recuperação alcançada\n\nUm ano: uma recuperação completa de sistema duplo\nUm ano após a conclusão da redução gradual do SNRI, tanto o sistema da serotonina como o da noradrenalina tiveram um ciclo completo para se adaptarem e estabilizarem.\n\nO que as evidências realmente apoiam em um ano\nEsta revisão da Carta Terapêutica observa que os sintomas de abstinência documentados “geralmente aparecem alguns dias após a interrupção” e que a maioria desaparece em cerca de duas semanas – não há nenhum estudo controlado acompanhando pessoas especificamente um ano após a descontinuação do SNRI.O que é bem apoiado pelo quadro clínico mais amplo a esta distância:\n• A maioria daqueles que completaram uma redução gradual adequada e receberam apoio psicológico permanecem bem\n• O embotamento emocional e a disfunção sexual que caracterizam o uso de SNRI foram totalmente resolvidos para a maioria das pessoas\n• O pensamento claro, incluindo os benefícios de concentração que os SNRIs podem proporcionar, são mantidos através da função cerebral natural\n\nO significado deste marco\nA descontinuação bem-sucedida de um IRSN – particularmente a venlafaxina – é uma conquista significativa.A intensidade do processo de interrupção e o compromisso necessário para o gerir sob supervisão médica demonstram uma resiliência notável.';

  @override
  String get socialMediaReferenceDay1 =>
      'Afastando-se das mídias sociais: primeiro dia\n\nFonte: Lambert et al., \"Fazer uma pausa de uma semana nas mídias sociais melhora o bem-estar, a depressão e a ansiedade: um ensaio clínico randomizado\", Ciberpsicologia, comportamento e redes sociais (2022), no PubMed\n\nO que as evidências mostram\nNeste forte estudo controlado, as pessoas foram designadas aleatoriamente para fazer uma pausa de uma semana no Facebook, Instagram, Twitter e TikTok ou para continuar a usá-los normalmente.O grupo do intervalo mostrou melhorias significativas no bem-estar e reduções na depressão e ansiedade.Esta é uma prova real e controlada de que recuar ajuda.\n\nO que as evidências mostram\nO uso compulsivo das redes sociais está fortemente ligado à diminuição do humor e ao aumento da ansiedade, e ensaios randomizados mostram que reduzir deliberadamente o consumo pode melhorar o bem-estar e, ao mesmo tempo, reduzir a depressão e a ansiedade em uma semana.\n\nPrimeiro dia: o que esperar\n• Inquietação e vontade de verificar\n• Notificações \"fantasmas\" — sentindo um zumbido que não aconteceu\n• Tédio à medida que você se adapta a estímulos menos constantes\nEstas são sensações normais relacionadas ao hábito e são temporárias.Reconhecer o padrão é o primeiro passo para mudá-lo.';

  @override
  String get socialMediaReferenceDay3 =>
      'Três dias sem redes sociais: ansiedade e humor\n\nFonte: Lambert et al., \"Fazer uma pausa de uma semana nas mídias sociais melhora o bem-estar, a depressão e a ansiedade: um ensaio clínico randomizado\", Ciberpsicologia, comportamento e redes sociais (2022), no PubMed\n\nPor que uma pausa ajuda o humor\nNeste estudo controlado, as pessoas designadas aleatoriamente para uma pausa de uma semana nas redes sociais terminaram a semana com menos ansiedade e depressão e maior bem-estar do que aquelas que continuaram navegando.Grande parte do sofrimento diário do uso pesado vem da comparação social – medir sua vida real em relação aos destaques selecionados por outras pessoas – e da atração de baixa qualidade do medo de perder.\n\nO que acontece por volta de 72 horas\nNo início do intervalo, o hábito ainda é alto:\n• Forte necessidade de verificar, muitas vezes desencadeada por momentos rotineiros (acordar, esperar na fila)\n• Alguma irritabilidade e inquietação\n• Para algumas pessoas, o primeiro alívio da ansiedade causada pela comparação\n• O hábito de rolar antes do sono está começando a diminuir\n\nA armadilha da comparação se solta\nSem uma alimentação constante dos destaques de outras pessoas, a comparação que alimenta grande parte da ansiedade nas redes sociais tem menos combustível.Os resultados do ensaio sugerem que, no final da primeira semana, estas mudanças iniciais resultam numa melhoria mensurável do humor – portanto, o desconforto aos três dias é a parte mais difícil de uma mudança que compensa.';

  @override
  String get socialMediaReferenceDay7 =>
      'Uma semana sem mídia social: a recompensa medida\n\nFonte: Lambert et al., \"Fazer uma pausa de uma semana nas mídias sociais melhora o bem-estar, a depressão e a ansiedade: um ensaio clínico randomizado\", Ciberpsicologia, comportamento e redes sociais (2022), no PubMed\n\nExatamente uma semana – e funcionou\nEste é o marco ao qual a pesquisa fala mais diretamente: a intervenção do ensaio foi um intervalo de uma semana.Em comparação com as pessoas que continuaram a utilizar as redes sociais, o grupo do intervalo apresentou um bem-estar significativamente maior e uma depressão e ansiedade significativamente mais baixas após apenas sete dias.Chegar a uma semana é chegar ao ponto em que um estudo controlado encontrou benefícios reais.\n\nO que as pessoas geralmente notam\nJuntamente com os ganhos de humor medidos, as pessoas frequentemente relatam:\n• Mais tempo recuperado — muitos ficam surpresos com o quanto estavam gastando\n• Foco mais fácil, à medida que o hábito de mudar constantemente a atenção diminui\n• Noites mais calmas e sono mais fácil sem a rolagem pré-cama\nEstes ganhos enquadram-se na melhoria mais ampla do bem-estar medida no ensaio.\n\nContinue\nUma semana é um marco genuíno e comprovado.Os benefícios de humor, tempo e atenção tendem a se aprofundar quanto mais tempo o padrão saudável se mantiver.';

  @override
  String get socialMediaReferenceDay14 =>
      'Duas semanas sem redes sociais: ganhos em duas semanas\n\nFonte: Coyne & Woodruff, \"Fazendo uma pausa: os efeitos de participar de uma desintoxicação digital de mídia social de duas semanas... entre jovens adultos\", Ciências Comportamentais (2023), no PubMed Central\n\nSobre este estudo\nOs jovens adultos limitaram as redes sociais a cerca de 30 minutos por dia durante duas semanas, com o uso rastreado objetivamente em seus telefones (caiu cerca de 78%).Os participantes reduziram o uso das redes sociais em cerca de 78%, dando a este marco um teste direto e real do que acontece quando o uso é drasticamente reduzido durante duas semanas.\n\nO que melhorou\nAo longo das duas semanas, os participantes mostraram melhorias em:\n• Sono — duração e qualidade\n• Satisfação com a vida\n• Estresse\n• Bem-estar percebido\n• Pontuações em escalas de dependência de smartphones e mídias sociais\nOs ganhos medidos foram concretos: sono mais longo e melhor, menor estresse, maior satisfação com a vida e percepção de bem-estar, e menores pontuações de dependência de smartphones/mídias sociais.\n\nCuidado com o retrocesso\nOs pesquisadores também notaram que o uso voltou aos níveis anteriores posteriormente.Duas semanas é um ganho real, mas destaca por que um plano intencional – e não apenas uma pausa temporária – é o que mantém os benefícios.';

  @override
  String get socialMediaReferenceDay30 =>
      'Um mês sem redes sociais: a conexão real se aprofunda\n\nFonte: Coyne & Woodruff, \"Fazendo uma pausa: os efeitos de participar de uma desintoxicação digital de mídia social de duas semanas... entre jovens adultos\", Ciências Comportamentais (2023), no PubMed Central\n\nA conexão pode melhorar quando você recua\nParece paradoxal – mas neste estudo, cortar as redes sociais foi associado à melhoria das relações de apoio, juntamente com uma melhor satisfação com a vida e menor stress.O tempo e a atenção destinados ao feed tornaram-se disponíveis para as pessoas que realmente fazem parte da sua vida.\n\nO que um mês tende a trazer\nAos 30 dias, com a verificação automática muito mais fraca, muitas pessoas descobrem:\n• As conversas são mais presentes e menos interrompidas\n• Mais interesse em atividades e hobbies do mundo real\n• Autoimagem baseada menos em curtidas, comentários e contagens de seguidores\n\nSinal de recuperação\nEm um mês, você manteve o padrão mais saudável durante o dobro da janela de intervenção do estudo.Os ganhos de sono, estresse, satisfação com a vida, bem-estar e relacionamento medidos em duas semanas tiveram mais duas semanas para se consolidarem na rotina.\n\nFaça o tempo contar\nProcure preencher o tempo livre com atividades que criem conexão e realização genuínas, em vez de simplesmente trocar uma tela por outra.';

  @override
  String get socialMediaReferenceDay60 =>
      'Dois meses sem redes sociais: o que as evidências apoiam\n\nFonte: Ramadhan et al., \"Impactos da desintoxicação de mídia social digital para a saúde mental: uma revisão sistemática e meta-análise\", Narra J (2024), no PubMed Central\n\nA imagem mais confiável\nOs pesquisadores combinaram os resultados de 10 estudos, incluindo sete ensaios controlados.O resultado mais claro foi uma redução significativa nos sintomas depressivos depois que as pessoas abandonaram as redes sociais.\n\nO resultado mais forte\nA pesquisa combinada encontrou uma clara redução nos sintomas depressivos.Aos dois meses, você está sustentando o mesmo tipo de menor exposição digital que produziu esse benefício para a saúde mental.\n\nComo podem ser dois meses\nCom menos comparações diárias e menos reforço impulsionado por feeds, a autoimagem tem muito menos motivos para depender de curtidas, comentários ou contagens de seguidores, enquanto as evidências mais fortes agrupadas apontam para sintomas depressivos mais baixos.\n\nA lição prática\nA evidência recompensa a mudança intencional e sustentada.Use o ponto de dois meses para manter os limites deliberados em vez de retroceder e para investir em fontes off-line de significado e conexão.';

  @override
  String get socialMediaReferenceDay90 =>
      'Três meses sem redes sociais: um novo normal\n\nFonte: Coyne & Woodruff, \"Fazendo uma pausa: os efeitos de participar de uma desintoxicação digital de mídia social de duas semanas... entre jovens adultos\", Ciências Comportamentais (2023), no PubMed Central\n\nO sono é o destaque\nUma das descobertas mais claras deste estudo foi a melhoria do sono – tanto na duração como na qualidade – quando os participantes cortaram as redes sociais imediatamente.Após três meses de um padrão sustentado de saúde, o pergaminho noturno que costumava consumir durante o sono há muito deixou de competir com o descanso, e um sono melhor tende a melhorar o humor, o foco e a energia com ele.\n\nO que mais melhorou\nO mesmo estudo encontrou ganhos em estresse, satisfação com a vida, bem-estar percebido e relacionamentos de apoio.Aos três meses, estas já não são novidades – tiveram tempo para se estabelecerem numa nova normalidade.\n\nSinal de recuperação no mecanismo\nCortar as redes sociais melhorou drasticamente a duração e a qualidade do sono no estudo de intervenção.Três meses mantendo esse padrão transformam a redução da rolagem noturna em um hábito de sono duradouro.\n\nPresença e Relacionamentos\nCom o reflexo de preencher cada momento de silêncio com o telefone muito mais fraco, estar presente - nas conversas, nas refeições e nos momentos de inatividade - vem com mais naturalidade, e os relacionamentos nos quais você investiu ao longo de três meses tendem a parecer mais fortes por isso.';

  @override
  String get socialMediaReferenceDay180 =>
      'Seis Meses Sem Redes Sociais: Recuperação Medida\n\nFonte: Ramadhan et al., \"Impactos da desintoxicação de mídia social digital para a saúde mental: uma revisão sistemática e meta-análise\", Narra J (2024), no PubMed Central\n\nO que a meta-análise adiciona\nCombinando 10 estudos, incluindo sete ensaios controlados, os pesquisadores encontraram uma clara redução nos sintomas depressivos depois que as pessoas reduziram ou pausaram as redes sociais.\n\nO que realmente encontrou\n• Depressão: uma redução estatisticamente significativa (o benefício mais claro e consistente)\n• Satisfação com a vida: nenhum efeito significativo\n• Estresse: nenhum efeito significativo\n• Bem-estar mental geral: nenhum efeito significativo\nO resultado mais forte é claro: a desintoxicação digital reduz significativamente os sintomas depressivos.\n\nPor que você ainda pode sentir amplos benefícios\nSeis meses de exposição reduzida aos alimentos agravam os ganhos práticos observados em intervenções mais curtas: mais tempo disponível, menos verificações compulsivas e uma redução sustentada na exposição digital associada a sintomas depressivos.\n\nMantenha o controle do feed\nOs maiores ganhos vêm da quebra do uso pesado, passivo e compulsivo.Aos seis meses, o controle intencional sobre as mídias sociais é o novo padrão, em vez do feed controlar sua atenção.';

  @override
  String get socialMediaReferenceDay365 =>
      'Um ano sem redes sociais: uma relação renegociada\n\nFonte: Ramadhan et al., \"Impactos da desintoxicação de mídia social digital para a saúde mental: uma revisão sistemática e meta-análise\", Narra J (2024), no PubMed Central\n\nUm ano de mudança sustentada\nA pesquisa combinada mais forte mostra que afastar-se das redes sociais reduz os sintomas depressivos.Um ano inteiro significa que o padrão de exposição mais baixa se tornou normal, em vez de uma pequena pausa.\n\nO que um ano constrói\nUm ano inteiro lhe dá centenas de horas para relacionamentos reais, hobbies, habilidades, reflexão e criatividade.A verificação automática teve um ano inteiro para enfraquecer, enquanto as rotinas off-line tiveram um ano inteiro para se fortalecer.\n\nBenefícios sustentados\nO ganho de saúde mental medido mais claramente é a redução dos sintomas depressivos.Os ganhos práticos – mais tempo, menos interrupções e menos verificações compulsivas – aumentam a cada dia que você mantém o controle da alimentação.\n\nO que vem a seguir\nUm ano de mudanças deliberadas redefiniu o relacionamento.Quer você retorne ao uso limitado e intencional ou fique totalmente afastado, o ciclo compulsivo foi quebrado – e essa é a vitória duradoura.';

  @override
  String get ssriReferenceDay3 =>
      'Descontinuação do SSRI: os primeiros dias\n\nFonte: Harvard Health Publishing\n\nNota importante de segurança\nOs ISRS só devem ser interrompidos sob supervisão médica após uma redução gradual.A cessação abrupta – especialmente após uso prolongado – aumenta significativamente a gravidade dos sintomas de descontinuação.\n\nO que é a síndrome de descontinuação de ISRS?\nA síndrome de descontinuação dos ISRS é um fenômeno médico bem documentado que ocorre quando os ISRS são interrompidos ou substancialmente reduzidos.Os médicos usam a sigla FINISH para descrever os sintomas comuns:\n• Sintomas semelhantes aos da gripe (fadiga, sudorese, dores musculares)\n• Insônia e distúrbios do sono\n• Náusea\n• Desequilíbrio e tontura\n• Distúrbios sensoriais — particularmente \'zaps cerebrais\'\n• Hiperexcitação, irritabilidade e ansiedade\n\nMeia-vida é importante\nA fluoxetina (Prozac) tem uma meia-vida muito longa de 4 a 6 dias, por isso diminui automaticamente e produz efeitos de descontinuação mais leves.A paroxetina (Paxil) tem a meia-vida mais curta dos ISRSs comuns e produz os sintomas de descontinuação mais intensos.Sertralina, citalopram e escitalopram ficam no meio.';

  @override
  String get ssriReferenceDay7 =>
      'Uma semana após os ISRS: a fase aguda\n\nFonte: NHS – Parar ou interromper os antidepressivos\n\nA fase de descontinuação aguda\nO NHS documenta que a maioria dos sintomas de descontinuação de antidepressivos começa cinco dias após a interrupção e duram até seis semanas na maioria dos casos.Em uma semana, os sintomas físicos agudos são normalmente mais pronunciados e começam a diminuir para aqueles que diminuíram gradualmente.\n\nO que esperar em uma semana\n• Os sintomas físicos (náuseas, tonturas, sensação de gripe) são mais intensos, mas devem estar começando a diminuir\n• Distúrbios do sono, incluindo sonhos vívidos ou insônia, são comuns\n• Labilidade emocional — mudanças rápidas de humor — é frequente nesta fase\n• Os choques cerebrais ainda podem estar presentes, mas normalmente começam a diminuir em frequência\n\nO papel da redução gradual\nO NHS recomenda fortemente uma redução lenta – às vezes ao longo de meses para usuários de longo prazo – para minimizar os efeitos da descontinuação.O Royal College of Psychiatrists desenvolveu directrizes de redução gradual que sugerem reduções de dose muito graduais, muitas vezes utilizando formulações líquidas, para aqueles que tomaram ISRS durante longos períodos.';

  @override
  String get ssriReferenceDay14 =>
      'Duas semanas após os ISRS: resolução dos sintomas físicos\n\nFonte: Davies & Read (2019), Addictive Behaviors — \'Uma revisão sistemática sobre a incidência, gravidade e duração dos efeitos da abstinência de antidepressivos\'\n\nO que a pesquisa descobriu\nEsta revisão sistemática marcante descobriu que aproximadamente 56% das pessoas que descontinuam os antidepressivos experimentam efeitos de abstinência, e 46% delas os descrevem como graves.Para a maioria das pessoas que seguem uma redução gradual adequada, a fase aguda é amplamente resolvida em duas semanas:\n• Zaps cerebrais significativamente reduzidos ou ausentes\n• Náuseas e sintomas semelhantes aos da gripe foram resolvidos\n• Tonturas e problemas de equilíbrio melhorando\n• Sono começando a normalizar\n\nDistinguindo a descontinuação da recaída\nOs sintomas que aparecem alguns dias após a interrupção e correspondem ao perfil FINISH são provavelmente síndrome de descontinuação.Os sintomas que surgem após 2 a 4 semanas e se assemelham à condição original sendo tratada são mais prováveis ​​de recidiva.É importante monitorizar esta distinção com o seu médico.';

  @override
  String get ssriReferenceDay30 =>
      'Um mês após ISRS: estabilização\n\nFonte: Haddad PM (2001), Drug Safety — \'Antidepressant Discontinuation Syndromes\'\n\nA Fase de Estabilização\nEsta revisão descreve o início da descontinuação como rápido, normalmente alguns dias após a interrupção ou redução de um antidepressivo, e observa que a maioria das reações são leves e de curta duração, resolvendo-se sem tratamento específico.Um mês representa a transição dessa janela aguda para a estabilização;para a maioria das pessoas que completaram uma redução gradual, os sintomas agudos de descontinuação estão agora amplamente resolvidos.\n\nPaisagem emocional em um mês\nAs mudanças emocionais em um mês são variáveis e importantes de monitorar:\n• Algumas pessoas sentem-se emocionalmente \"mais planas\" inicialmente à medida que o cérebro se ajusta - isto normalmente melhora\n• Outros experimentam uma vivacidade emocional que não sentiam há anos\n• Os níveis de ansiedade variam significativamente de acordo com a condição individual e subjacente\n\nO valor do suporte não medicamentoso\nA pesquisa mostra consistentemente que a terapia da fala, como a TCC (TCC) e outras terapias psicológicas baseadas em evidências, são altamente eficazes para as condições tratadas pelos ISRS.A marca de um mês é um excelente momento para garantir que esses apoios estejam em vigor.';

  @override
  String get ssriReferenceDay90 =>
      'Três meses após SSRIs: retirada bem passada\n\nFonte: \"Síndrome de abstinência de antidepressivos\", Therapeutics Letter 112 (2018), Therapeutics Initiative, na estante do NCBI\n\nOnde ficam três meses\nEsta revisão de evidências observa que os sintomas de abstinência de antidepressivos “geralmente aparecem alguns dias após a interrupção ou redução da dose” e que “a maioria dos sintomas de abstinência de antidepressivos desaparecem em 2 semanas” – embora os casos graves possam durar semanas a meses.Aos três meses, a fase aguda de abstinência já está bem atrasada para a grande maioria das pessoas.\n\nPor que os SSRIs variam\nA abstinência é mais provável com ISRSs de meia-vida mais curta (como a paroxetina) do que com os de meia-vida longa (fluoxetina).A Carta é franca ao afirmar que as reações de abstinência podem ser substanciais – duas revisões sistemáticas consideraram-nas “muito semelhantes” às das benzodiazepinas – e ocorrem em pelo menos um terço das pessoas que param.\n\nSinal de recuperação em \'Recuperação do receptor\'\nVocê pode ver afirmações confiantes de que os receptores de serotonina \'resensibilizam totalmente em 2 a 3 meses\'.A evidência robusta diz respeito à síndrome de abstinência e ao seu momento, e não a um relógio preciso de recuperação dos receptores.O que é confiável: em três meses, a fase de abstinência normalmente foi resolvida e muitas pessoas notam o embotamento emocional e os efeitos colaterais sexuais que alguma experiência com os ISRSs diminuem após a interrupção.\n\nSe os sintomas persistirem\nA Carta aconselha distinguir a retirada de um retorno genuíno da condição subjacente.Se o mau humor ou a ansiedade persistirem após três meses, vale a pena revisar isso com seu médico, em vez de presumir que é \'apenas abstinência\'.';

  @override
  String get ssriReferenceDay180 =>
      'Seis meses após os ISRS: uma visão fundamentada\n\nFonte: \"Síndrome de abstinência de antidepressivos\", Therapeutics Letter 112 (2018), Therapeutics Initiative, na estante do NCBI\n\nO que está bem estabelecido em seis meses\nEsta revisão observa que mesmo os sintomas de abstinência graves e prolongados normalmente duram semanas a meses, em vez de indefinidamente – portanto, em seis meses, a síndrome de abstinência aguda, para a grande maioria das pessoas, está claramente resolvida.\n\nSendo honesto sobre o resto\nAos seis meses, o período normal de abstinência já passou e o sistema da serotonina teve meses para se acalmar.Os efeitos colaterais sexuais geralmente melhoram após a interrupção;se persistirem, discuta-os com o seu médico.\n\nO que as pessoas comumente relatam\n• Uma gama emocional mais ampla em comparação com estar sob medicação\n• Melhor sono e energia para a maioria\n• Melhoria gradual contínua, embora o ritmo varie amplamente entre os indivíduos';

  @override
  String get ssriReferenceDay365 =>
      'Um ano após ISRS: recuperação medida\n\nFonte: Duffy et al.(2021), Avaliação de Tecnologias em Saúde — o ensaio ANTLER\n\nO que este teste realmente encontrou\nANTLER acompanhou usuários de antidepressivos de longa data na atenção primária do Reino Unido que permaneceram com a medicação ou a interromperam.No ano seguinte, 56% dos que interromperam o tratamento tiveram uma recaída, em comparação com 39% dos que continuaram a tomar a medicação – aproximadamente o dobro do risco – e o grupo que interrompeu o tratamento relatou, em média, uma qualidade de vida um pouco inferior.\n\nA imagem mais completa\nApesar da taxa de recaída mais elevada, uma percentagem substancial de pessoas que interromperam o tratamento não teve recaída e permaneceu bem sem medicação.Cerca de um terço dos que interromperam o tratamento acabaram por reiniciar o seu antidepressivo – uma escolha clínica razoável, não um fracasso.\n\nUma nota sobre o futuro\nDepressão e ansiedade são condições crônicas para algumas pessoas.Não há falha no retorno à medicação se a condição subjacente se reafirmar.O objetivo é o bem-estar – e um ano de descontinuação bem-sucedida é uma conquista genuína, independentemente do que vier a seguir.';

  @override
  String get steroidsReferenceDay1 =>
      'Parando os esteróides anabolizantes: os primeiros dias\n\nFonte: \"Sintomas comuns associados ao uso e cessação de esteróides androgênicos anabolizantes em homens\", Melhores Práticas e Pesquisa Clínica Endocrinologia e Metabolismo (2022)\n\nA Fase Aguda\nEsta revisão descreve a retirada do AAS como se desdobrando em duas fases.O primeiro, impulsionado pela ativação do sistema nervoso simpático e não pelos níveis hormonais, aparece 1–2 dias após a interrupção e pode incluir:\n• Dor de cabeça\n• Tremores\n• Palpitações\n• Náusea\n\nPor que os sintomas aparecem\nOs esteróides anabolizantes também suprimem a produção de testosterona do próprio corpo – o cérebro detecta os esteróides e desliga os sinais hormonais que normalmente os impulsionam.Essa supressão persiste após a interrupção, estabelecendo a segunda fase de abstinência, mais duradoura, descrita em marcos posteriores.\n\nUma nota de segurança\nA depressão pode surgir durante a retirada dos esteróides e tornar-se grave.Procure atendimento médico e ajuda urgente para qualquer pensamento de automutilação.Os médicos geralmente orientam a recuperação;alguns usam medicamentos para apoiá-lo.';

  @override
  String get steroidsReferenceDay14 =>
      'Duas semanas sem esteróides anabolizantes\n\nFonte: \"Sintomas comuns associados ao uso e cessação de esteróides androgênicos anabolizantes em homens\", Melhores Práticas e Pesquisa Clínica Endocrinologia e Metabolismo (2022)\n\nA fase crônica se instala\nEm duas semanas, os breves sintomas simpáticos dos primeiros dias normalmente passaram, e a segunda fase da revisão – impulsionada pela deficiência contínua de testosterona – é mais proeminente:\n• Fadiga e mau humor\n• Dores musculares (mialgia)\n• Libido reduzida\n• Insônia e desejos\n\nAinda em Low Ebb\nA produção natural de testosterona leva muito mais do que duas semanas para ser reiniciada, então esta fase é esperada e não um sinal de que algo está errado.\n\nUma armadilha conhecida\nAlguns homens voltam a usar especificamente para escapar desta lacuna – um ciclo que reinicia o relógio de recuperação em vez de encerrá-lo.O apoio de um médico ou conselheiro ajuda a superar essa fase, em vez de medicá-la com mais esteróides.';

  @override
  String get steroidsReferenceDay30 =>
      'Um mês sem esteróides anabolizantes\n\nFonte: \"Recuperação física, psicológica e bioquímica do hipogonadismo induzido por esteróides anabolizantes: uma revisão de escopo\", no PubMed\n\nA recuperação começa\nDepois de parar, os sinais hormonais que dizem aos testículos para fazerem a testosterona começarem a ser reativados.A investigação coloca grande parte desta recuperação no intervalo de três a seis meses, pelo que num mês o processo já está em curso.\n\nO que esperar\nO mau humor, a libido e a energia geralmente persistem enquanto os hormônios voltam a subir.A recuperação depende da idade e da intensidade e duração do uso.';

  @override
  String get steroidsReferenceDay90 =>
      'Três meses sem esteróides anabolizantes\n\nFonte: \"Recuperação física, psicológica e bioquímica do hipogonadismo induzido por esteróides anabolizantes: uma revisão de escopo\", no PubMed\n\nUm bom momento para um exame de sangue\nAos três meses, o sistema hormonal teve tempo de mostrar uma recuperação significativa.Este é um ponto útil para pedir ao seu médico de família que verifique a testosterona e os hormônios que a controlam.\n\nO que esperar\nPara muitos homens aos três meses, os níveis estão a subir, mas não estão totalmente normalizados.O humor e a libido geralmente melhoram antes que a testosterona seja totalmente recuperada.O tamanho dos testículos e a produção de espermatozoides se recuperam mais lentamente e podem continuar melhorando no ano seguinte.É improvável que o crescimento do tecido mamário (ginecomastia), onde ocorreu, seja revertido sem tratamento específico.';

  @override
  String get steroidsReferenceDay180 =>
      'Seis meses sem esteróides anabolizantes\n\nFonte: \"Recuperação física, psicológica e bioquímica do hipogonadismo induzido por esteróides anabolizantes: uma revisão de escopo\", no PubMed\n\nOnde as evidências apontam\nA revisão relata que o LH e o FSH – os hormônios que instruem os testículos a produzir testosterona – geralmente se recuperam em cerca de três a seis meses.Aos seis meses, a própria testosterona também está no caminho de recuperação.\n\nSe você ainda não chegou lá\nSe os sintomas de baixa testosterona ainda estiverem presentes aos seis meses, um endocrinologista pode verificar o que está acontecendo e discutir o tratamento, em vez de deixá-lo esperar.';

  @override
  String get steroidsReferenceDay365 =>
      'Um ano de desconto em esteróides anabolizantes\n\nFonte: \"Hipogonadismo induzido por esteróides anabólicos androgênicos, uma condição reversível em indivíduos do sexo masculino? Uma revisão sistemática\", no PubMed\n\nUm ano grátis\nUm ano de folga dá ao sistema hormonal uma longa janela de recuperação.A testosterona, o humor, a libido, a força natural e a saúde do coração tiveram um tempo substancial para se recuperar.\n\nA imagem de longo prazo\nSe os sintomas de níveis baixos de testosterona ainda estiverem presentes após um ano, a avaliação hormonal especializada é o próximo passo certo.Ficar sem esteróides protege a recuperação já feita.';

  @override
  String get steroidsReferenceDay730 =>
      'Dois anos sem esteroides anabolizantes\n\nFonte: \"Hipogonadismo induzido por esteróides anabólicos androgênicos, uma condição reversível em indivíduos do sexo masculino? Uma revisão sistemática\", no PubMed\n\nUm novo normal\nAos dois anos, seus níveis hormonais refletem a produção natural do seu corpo.Para a maioria dos homens que se recuperam, o humor, a libido, a força e a motivação permanecem estáveis ​​sem esteróides.\n\nRecuperação hormonal a longo prazo\nA pesquisa mostra que a testosterona se recupera ao longo de meses, enquanto os hormônios que sinalizam os testículos geralmente se recuperam dentro de três a seis meses.O tamanho dos testículos, a produção de espermatozoides e a libido podem continuar melhorando ao longo de meses ou anos.Aos dois anos, os sintomas persistentes de baixa testosterona pertencem a um especialista, e não a outro ciclo de esteróides.';

  @override
  String get tcaReferenceDay3 =>
      'Descontinuação do TCA: Os primeiros dias – Recuperação da acetilcolina\n\nFonte: Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — \'Sintomas de abstinência de antidepressivos tratados com agentes anticolinérgicos\' (relato de caso, 3 pacientes)\n\nO que torna a descontinuação do TCA diferente\nOs antidepressivos tricíclicos diferem fundamentalmente dos ISRS e SNRIs no seu mecanismo.Além de bloquear a recaptação de serotonina e noradrenalina, os ADTs bloqueiam fortemente o sistema de acetilcolina do corpo.Quando você para, esse sistema se recupera.\n\nSintomas de rebote de acetilcolina\nAo contrário da descontinuação dos ISRS, a retirada do TCA produz um rebote da acetilcolina:\n• Náuseas, vômitos e diarreia\n• Salivação e suor excessivos\n• Dor de cabeça e dores musculares\n• Insônia com sonhos vívidos ou perturbadores\n• Ansiedade e inquietação\n\nTCAs comuns e seus perfis\nA amitriptilina e a imipramina têm os efeitos bloqueadores da acetilcolina mais fortes e normalmente produzem a recuperação mais pronunciada.A nortriptilina tem efeitos um pouco mais leves.A clomipramina também tem efeitos significativos relacionados à serotonina, juntamente com seu perfil de bloqueio da acetilcolina.';

  @override
  String get tcaReferenceDay7 =>
      'Uma semana após ADTs: alívio dos sintomas de acetilcolina\n\nA recuperação da acetilcolina\nA recuperação da acetilcolina normalmente atinge seu pico nos primeiros dias e começa a diminuir substancialmente em uma semana.À medida que o sistema de acetilcolina retorna ao seu nível natural:\n\nO que está melhorando\n• Os sintomas gastrointestinais (náuseas, cólicas, diarreia) estão diminuindo\n• Sudorese e sintomas semelhantes aos da gripe estão diminuindo\n• O sono, embora ainda interrompido, está começando a se estabilizar\n• A salivação excessiva está desaparecendo\n\nSistema Nervoso Corporal Automático\nOs ADTs afetam as funções automáticas do corpo – frequência cardíaca, pressão arterial, digestão – através de vários mecanismos.Em uma semana, os sintomas corporais automáticos mais intensos – incluindo tonturas ao ficar em pé e alterações rápidas da frequência cardíaca – começam a desaparecer à medida que o sistema nervoso se reajusta.';

  @override
  String get tcaReferenceDay14 =>
      'Duas semanas após os ADTs: reversão dos efeitos da antiacetilcolina\n\nOs elevadores de carga antiacetilcolina\nOs TCAs impõem efeitos significativos de bloqueio da acetilcolina no corpo que afetam vários sistemas.À medida que esse fardo diminui nas primeiras duas semanas:\n\nBenefícios físicos\n• Resolução da boca seca — função das glândulas salivares retornando ao normal\n• Resolução da constipação – motilidade intestinal restaurada naturalmente\n• Normalização da função urinária – a retenção urinária que os ADTs podem causar está desaparecendo\n• Limpeza da visão turva — olhos se ajustando normalmente à luz novamente\n\nBenefícios de pensamento e memória\nA acetilcolina é essencial para memória, atenção e aprendizagem.As vias da acetilcolina suprimidas pelos TCAs estão se recuperando:\n• Melhoria da memória de trabalho\n• Aumento da velocidade de processamento\n• Clareza mental retornando\n\nMuitas pessoas ficam surpresas com a quantidade de confusão mental e problemas de memória aos quais se adaptaram enquanto tomavam ADTs.';

  @override
  String get tcaReferenceDay30 =>
      'Um mês após TCAs: Estabilização automática do sistema nervoso corporal\n\nRecuperação cardíaca\nOs TCAs afetam o ritmo cardíaco durante o uso através de sua ação nos sistemas nervosos relacionados à acetilcolina e à adrenalina.A literatura clínica sobre a descontinuação do ADT confirma que os sintomas agudos de abstinência – incluindo os efeitos corporais automáticos provocados por este “overdrive relacionado à acetilcolina e adrenalina” – são tipicamente leves e desaparecem dentro de uma a duas semanas após a interrupção.Em um mês, a maioria das pessoas já passou dessa janela aguda e pode esperar:\n• Ritmo cardíaco voltando ao nível inicial pré-medicação\n• Variabilidade da frequência cardíaca tendendo a níveis naturais\n• Regulação da pressão arterial, anteriormente afetada pela ação do medicamento nas vias da adrenalina, continuando a estabilizar\n\nRestauração da Arquitetura do Sono\nOs TCAs suprimem fortemente o sono onírico.À medida que o efeito antiacetilcolina desaparece (a acetilcolina é necessária para o sono onírico):\n• O sono REM está retornando, muitas vezes produzindo uma onda de sonhos vívidos à medida que o sono onírico retorna\n• O sono de ondas lentas (profundo) está melhorando\n• A qualidade geral e a restauração do sono são significativamente melhores do que durante o uso de TCA';

  @override
  String get tcaReferenceDay90 =>
      'Três meses após os ACTs: deixando os riscos reais para trás\n\nO que as evidências mostram\nUma meta-análise de 2024 de 103 ensaios aleatorizados (10.590 participantes) descobriu que, em comparação com o placebo, os ADTs reduzem os sintomas depressivos – mas também apresentam quase o triplo das probabilidades de um evento adverso grave (razão de probabilidades 2,78).Os próprios ensaios apenas acompanharam as pessoas durante até 12 semanas de tratamento, pelo que não existem dados controlados a longo prazo sobre o que acontece após a interrupção.Tudo o que se segue reflecte a compreensão clínica geral da farmacologia do TCA, e não uma descoberta específica das evidências deste ensaio.\n\nA recuperação multissistema\nOs TCAs afetam uma gama mais ampla de sistemas químicos cerebrais do que os ISRS ou SNRIs:\n• Sistema de serotonina: ajuste\n• Sistema de noradrenalina: ajuste\n• Sistema de acetilcolina: voltando ao normal\n• Sistema histamínico: a sedação semelhante ao anti-histamínico foi resolvida\n\nAos três meses, todos esses sistemas tiveram um tempo substancial para se recuperar e – tão importante quanto – o elevado risco de eventos adversos graves que acompanha o tratamento ativo com TCA ficou para trás.Muitas pessoas notam:\n• Melhoria do pensamento claro – especialmente memória e atenção\n• Melhor estabilidade de humor\n• Maior energia e motivação\n• Sedação reduzida e melhor estado de alerta';

  @override
  String get tcaReferenceDay180 =>
      'Seis meses após ACTs: recuperação do coração e do pensamento\n\nSinal de recuperação em dados de longo prazo\nO período de abstinência precoce após os ADTs é geralmente leve e desaparece dentro de uma a duas semanas.Seis meses após uma redução gradual supervisionada, os efeitos dos ADTs na frequência cardíaca, na memória e no pensamento tiveram meses para se recuperar.\n\nRecuperação Cardiovascular\nAos seis meses, os efeitos diretos dos ADTs no ritmo cardíaco devem estar resolvidos há muito tempo:\n• Ritmo cardíaco normal mantido sem influência de drogas\n• Espera-se que a variabilidade da frequência cardíaca (uma medida de quão bem o seu coração se adapta) seja substancialmente melhorada\n• Tontura ao ficar em pé totalmente resolvida\n\nPensamento e recuperação de memória\nOs TCAs podem causar confusão mental e problemas de memória ao bloquear a acetilcolina, especialmente em adultos mais velhos.Esses efeitos melhoram após a interrupção do medicamento.Aos seis meses:\n• A consolidação da memória melhorou substancialmente\n• Velocidade de processamento normalizada\n• O planejamento, a memória de trabalho e a capacidade de alternar entre tarefas ou ideias são recuperados de forma significativa';

  @override
  String get tcaReferenceDay365 =>
      'Um ano após TCAs: Recuperação alcançada\n\nUm ano: recuperação completa de vários sistemas\nEsta revisão das síndromes de descontinuação de antidepressivos – abrangendo ADTs, IMAOs, ISRSs e outros – descobriu que os sintomas de abstinência geralmente começam alguns dias após a interrupção e, se não forem tratados, desaparecem por conta própria dentro de alguns dias a algumas semanas.Não há nenhum estudo que meça especificamente os sistemas afetados pelo TCA um ano depois, mas um ano após a conclusão da redução gradual é muitos meses além dos sintomas de descontinuação mais longos relatados, portanto, todos os sistemas químicos cerebrais afetados – serotonina, noradrenalina, acetilcolina e histamina – podem ter tido um ciclo completo para normalizar.\n\nO significado da recuperação do TCA\nOs ADTs impõem uma carga mais ampla causada pelos medicamentos do que os antidepressivos mais recentes, afetando mais sistemas receptores simultaneamente.A descontinuação bem-sucedida representa a recuperação de vários sistemas:\n• Reversão completa do comprometimento da memória e do pensamento causado pelo bloqueio da acetilcolina pelos ADTs\n• Recuperação completa do coração\n• Regulação química natural do cérebro restaurada em todas as vias afetadas\n\nUm ano de auto-regulação bem sucedida após a descontinuação do ADT representa uma conquista genuína – tanto na gestão do processo de descontinuação como na manutenção do bem-estar sem apoio impulsionado pelos medicamentos.';
}
